INSERT INTO `portal_guest` VALUES (149, 'Elizabeth Chetty', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-24/1c410891f3604c38906388939f1d3621.png', 27, 1, '<p>博士</p><p>南非约翰内斯堡大学视光系的高级讲师</p><p>非洲视觉与眼健康杂志》（African Vision and Eye Health）的副主编</p><p>联合视光师论坛（UOF）非洲区域的区域总监</p>', NULL, '2026-06-23 17:13:13', NULL, '2026-06-24 21:45:09', 0, '2', 'ZH');
