INSERT INTO `portal_guest` VALUES (151, 'Eef van der Worp', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-24/60f60c1c5ed54de28f75293a20dcfb85.png', 26, 1, '<p>BOptom, Ph.D\nFormer Head of the Contact Lens Department at HU University of Applied Sciences Utrecht, the Netherlands\nOwner of Eye-Contact-Lens Research &amp; Education Consultancy\nAdjunct Assistant Professor at Pacific University College of Optometry (Oregon, USA)\nAdjunct Professor at the University of Montreal School of Optometry (Canada)</p>', NULL, '2026-06-23 17:15:41', NULL, '2026-06-24 17:49:26', 0, '2', 'EN');
