INSERT INTO `portal_question` VALUES (11, '123', '<p>氨基酸的绿卡规范网络和是客观的发圣诞快乐发噶上课爱上了官方·大华股份VS看到高房价面前我就会绿卡事故发生的卡号发过来空前的·1</p><h1 class=\"ql-align-center\"><span style=\"color: rgb(230, 0, 0);\">1112123</span></h1>', 1, 1, NULL, '2026-04-23 18:20:31', NULL, '2026-04-23 18:53:36', 1, NULL, NULL);
INSERT INTO `portal_question` VALUES (12, '一、大会基本信息', '<h3 class=\"ql-align-center\"><strong><u>Q1:大会的具体日期、时间和地点?</u></strong></h3><h3 class=\"ql-align-center\"><span style=\"color: rgb(230, 0, 0);\">A:大会将于2026年1月15日至1月17日在上海绿地铂瑞酒店举行。</span></h3><h3 class=\"ql-align-center\">地址:上海市青浦区诸光路1588弄100号</h3><h3 class=\"ql-align-center\">大会日程详见:&nbsp;https://www.medcircle.cn/meeting/index/6148?sourceCode=null</h3><p><br></p>', 1, 1, NULL, '2026-04-23 18:54:41', NULL, '2026-04-25 23:56:54', 1, '1212321', NULL);
INSERT INTO `portal_question` VALUES (13, '二、大会主要阐述问题', '<h3 class=\"ql-align-center\"><strong><u>Q1:生命的意义?</u></strong></h3><h3 class=\"ql-align-center\"><span style=\"color: rgb(0, 102, 204);\">A:大会将于2026年1月15日至1月17日在上海绿地铂瑞酒店举行。</span></h3><h3 class=\"ql-align-center\"><span style=\"background-color: rgb(178, 107, 0); color: rgb(0, 102, 204);\">地址:上海市青浦区诸光路1588弄100号</span></h3><h3 class=\"ql-align-center\">大会日程详见:&nbsp;https://www.medcircle.cn/meeting/index/6148?sourceCode=null</h3><p><br></p>', 2, 1, NULL, '2026-04-24 09:47:11', NULL, '2026-04-25 23:56:54', 1, NULL, NULL);
INSERT INTO `portal_question` VALUES (14, '一、大会基本信息', '<p><br></p><p><strong>Q1：大会的具体日期、时间和地点？</strong></p><p><br></p><p>A：大会将于2027年1月7日至1月9日在<span style=\"color: black;\">上海西岸国际会展中心</span>举行 地址：<span style=\"color: black;\">上海市徐汇区龙耀路7号</span></p><p><br></p><p><br></p><p><strong>Q2：如何获取最新的大会通知和更新？</strong></p><p><br></p><p><strong>A：</strong>请密切关注本次大会官方网站<a href=\"https://myopiacontactlens.com/\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>https://myopiacontactlens.com/</strong></a>所有重要通知将通过网站发布</p><p><br></p><p><br></p><p><strong>Q3:大会的完整日程在哪里查看？</strong></p><p><br></p><p><strong>A：</strong>大会官方网站中<strong>“会议日程”</strong>中查看<a href=\"https://myopiacontactlens.com/\" rel=\"noopener noreferrer\" target=\"_blank\"><strong>https://myopiacontactlens.com/</strong></a></p><p><br></p><p><br></p>', 2, 1, NULL, '2026-04-26 16:36:44', NULL, '2026-06-29 16:42:19', 0, '大会基本信息', 'ZH');
INSERT INTO `portal_question` VALUES (15, '二、注册与签到', '<p><br></p><p><strong>Q4：注册截止时间和如何注册？</strong></p><p><br></p><p><strong>A：</strong>请在<strong>2026年10月8日-2027年1月9日</strong>期间，在大会官方网站内进行注册</p><p><br></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\">Q5：注册费用是多少？是否有早鸟优惠或学生优惠？</strong></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\"> A：</strong><span style=\"color: rgb(15, 17, 21);\">注册费用请于注册流程的付款页面查询。早鸟优惠及学生优惠正在制定中，详情请留意官网更新</span>https://myopiacontactlens.com/</p><p><br></p><p><br></p><p><strong>Q6：</strong><strong style=\"color: black;\">我可以取消注册并获得退款吗</strong><strong>？</strong></p><p><br></p><p><strong>A：</strong>可以的。如需取消注册或退款请与我们联系，联系方式：<span style=\"color: rgb(51, 51, 51);\">137-0192-6282</span></p><p><br></p><p><br></p><p><strong>Q7：是否可以现场注册？</strong></p><p><br></p><p><strong>A：</strong>可以</p><p><br></p><p><br></p>', 3, 1, NULL, '2026-04-26 16:37:40', NULL, '2026-06-25 14:16:09', 0, '注册与签到', 'ZH');
INSERT INTO `portal_question` VALUES (16, 'I. General Information', '<p><br></p><p><br></p><p><strong>Q1：What are the specific dates,times, and venue of the conference?</strong></p><p><br></p><p><strong>A:</strong>The conference will be held from January 7 to January 9, 2027 at the West Bund International Convention and Exhibition Center.</p><p>Address: No.7 Longyao Road, Xuhui District,Shanghai</p><p><br></p><p><br></p><p><strong>Q2: What is the best way to stay updated with the latest conference announcements and updates?</strong></p><p><br></p><p><strong>A: </strong>We kindly advise you to regularly check the official conference website at:<a href=\"https://myopiacontactlens.com/\" rel=\"noopener noreferrer\" target=\"_blank\">https://myopiacontactlens.com/</a></p><p><strong>All important announcements will be posted there</strong></p><p><br></p><p><br></p><p><strong>Q3: Where can I find the complete conference agenda?</strong></p><p><br></p><p><strong>A:</strong> The full conference agenda is available in the<strong> \"Conference Agenda\"</strong> section on the official website:<a href=\"https://myopiacontactlens.com/\" rel=\"noopener noreferrer\" target=\"_blank\">https://myopiacontactlens.com/</a></p><p><br></p><p><br></p>', 2, 1, NULL, '2026-05-11 17:44:59', NULL, '2026-06-25 16:17:17', 0, 'General Information', 'EN');
INSERT INTO `portal_question` VALUES (17, 'II. Registration & Check-in', '<p><br></p><p><strong>Q4: What is the registration deadline and how do I register?</strong></p><p><br></p><p><strong>A:</strong> Online registration is available on the official conference website from <strong>October 8, 2026 to January 9, 2027</strong></p><p><br></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\">Q5: What is the registration fee? Are there early-bird or student discounts?</strong></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\"> A: </strong><span style=\"color: rgb(15, 17, 21);\">Please check the registration fee on the payment page during the registration process. Early-bird and student discounts are currently being finalized. For details, please stay tuned to the conference website:</span><strong style=\"color: rgb(15, 17, 21);\"> </strong><a href=\"https://myopiacontactlens.com/\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(57, 100, 254);\"><strong>https://myopiacontactlens.com/</strong></a></p><p><br></p><p><br></p><p><strong>Q6：Is it possible to cancel my registration and receive a refund?</strong></p><p><br></p><p><strong>A:</strong> Yes. Should you need to cancel your registration or request a refund, please contact us at <span style=\"color: rgb(51, 51, 51);\">137-0192-6282</span></p><p><br></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\">Q7: Is on-site registration available?</strong></p><p><strong style=\"color: rgb(15, 17, 21);\"> A: </strong><span style=\"color: rgb(15, 17, 21);\">Yes</span></p><p><br></p><p><br></p>', 3, 1, NULL, '2026-05-11 17:45:33', NULL, '2026-06-25 16:17:42', 0, 'Registration & Check-in', 'EN');
INSERT INTO `portal_question` VALUES (18, '三、学术报告与论文提交', '<p><br></p><p><strong style=\"color: rgb(15, 17, 21);\">Q8：讲者需要提前多久到达试片室？</strong></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\"> A：</strong><span style=\"color: rgb(15, 17, 21);\">请所有讲者于演讲前至少2小时前往试片室（Speaker Ready Room）完成PPT最终确认。试片室位置及开放时间详见现场指引</span></p><p><br></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\">Q9：PPT是否有统一模板或格式要求？</strong></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\"> A：</strong><span style=\"color: rgb(15, 17, 21);\">建议使用16:9宽屏比例，并将视频文件转换为MP4格式。大会不提供统一模板，但请确保字体清晰、图表可读</span></p><p><br></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\">Q10：论文提交的截止日期是什么时候？</strong></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\"> A：</strong>论文投稿截止日期是2026年9月27日</p><p><br></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\"><span class=\"ql-cursor\">﻿﻿﻿﻿</span>Q11：论文被接收后，如何准备壁报或口头报告？</strong></p><p><br></p><p><strong> A：</strong><span style=\"color: rgb(15, 17, 21);\">壁报尺寸、PPT模板及提交方式将在摘要接收通知中详细说明。请您留意后续邮件</span></p><p><br></p><p><br></p>', 4, 1, NULL, '2026-05-13 06:04:06', NULL, '2026-07-05 15:00:39', 0, '学术报告与论文提交', 'ZH');
INSERT INTO `portal_question` VALUES (19, '四、会场与服务', '<p><br></p><p><strong>Q12：大会是否提供同声传译服务？</strong></p><p><br></p><p><strong>A：</strong>是的。主会场演讲将提供中英同声传译。您可在签到处领取相关设备，具体领取流程<span style=\"color: black;\">可与现场工作人员咨询</span></p><p><br></p><p><br></p><p><strong>Q13:茶歇和午餐如何安排？</strong></p><p><br></p><p><strong>A：</strong><span style=\"color: black;\">大会为您提供了茶歇与午餐，具体安排可与现场工作人员咨询</span></p><p><br></p><p><br></p><p><strong>Q14：</strong><strong style=\"color: rgb(15, 17, 21);\">会场附近有哪些推荐酒店？</strong></p><p><br></p><p><strong>五星级</strong></p><p><br></p><p><strong>1、上海世博洲际酒店</strong></p><p>地址：上海浦东新区雪野路1188号</p><p>距离会场直线距离：约3.2公里</p><p><br></p><p><strong>2、上海前滩香格里拉酒店</strong></p><p>地址：浦东新区三林镇海阳西路551号</p><p>距离会场直线距离：约2.1公里</p><p><br></p><p><strong>3、上海西岸美高梅酒店</strong></p><p>地址：上海徐汇区云锦路688号</p><p>距离会场直线距离：约570米</p><p><br></p><p><strong>4、上海世博滨江大酒店</strong></p><p>地址：上海浦东新区世博大道1588号</p><p>距离会场直线距离：约2.8公里</p><p>&nbsp;</p><p><strong>四星级</strong></p><p><br></p><p><strong>1、上海前滩美居酒店</strong></p><p>地址：上海市浦东新区泳耀路480号</p><p>距离会场直线距离：约1.8公里</p><p><br></p><p><strong>2、上海前滩雅辰尚酒店</strong></p><p>地址：上海市浦东新区杨思西路568号</p><p>距离会场直线距离：约2.3公里</p><p><br></p><p><strong>3、上海徐汇日月光美居酒店</strong></p><p>地址：上海市徐汇区沪闵路9505号</p><p>距离会场直线距离：约2.8公里</p><p><br></p>', 5, 1, NULL, '2026-05-13 06:05:43', NULL, '2026-07-16 13:06:41', 0, '会场与服务', 'ZH');
INSERT INTO `portal_question` VALUES (20, 'III. Presentations & Paper Submissions', '<p><br></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\">Q8: How early should speakers arrive at the Speaker Ready Room?</strong></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\"> A:</strong><span style=\"color: rgb(15, 17, 21);\"> All speakers are requested to go to the Speaker Ready Room at least 2 hours before their presentation to finalize their PowerPoint slides. The location and opening hours of the Speaker Ready Room are detailed in the on-site signage</span></p><p><br></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\">Q9: Is there a uniform template or format requirement for PowerPoint presentations?</strong></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\"> A: </strong><span style=\"color: rgb(15, 17, 21);\">It is recommended to use a 16:9 widescreen aspect ratio and convert video files to MP4 format. The conference does not provide a uniform template, but please ensure that fonts are clear and charts are readable</span></p><p><br></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\">Q10: What is the deadline for paper submission?</strong></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\"> A:</strong><span style=\"color: rgb(15, 17, 21);\"> </span>The deadline for paper submission is September 27, 2026</p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\"><span class=\"ql-cursor\">﻿﻿﻿﻿﻿﻿</span>Q11: How should I prepare my poster or oral presentation after my paper has been accepted?</strong></p><p><br></p><p><strong> A: </strong><span style=\"color: rgb(15, 17, 21);\">Details on poster dimensions, PowerPoint templates, and submission methods will be provided in the abstract acceptance notification. Please check your email for further information</span></p><p><br></p><p><br></p>', 4, 1, NULL, '2026-05-13 06:12:14', NULL, '2026-07-05 15:00:58', 0, 'Presentations & Paper Submissions', 'EN');
INSERT INTO `portal_question` VALUES (21, 'IV. Venue & Services', '<p><br></p><p><strong>Q12: Is simultaneous interpretation provided at the conference?</strong></p><p><br></p><p><strong>A: </strong>Yes, simultaneous Chinese-English interpretation will be provided for sessions in the main auditorium. The reception equipment will be available at the Registration Desk. For specific collection procedures, please inquire with our on-site staff</p><p><br></p><p><br></p><p><strong>Q13: How are refreshment breaks and lunch arranged?</strong></p><p><br></p><p><strong>A:</strong> Refreshment breaks and lunch will be available to all participants. For specific arrangements, please refer to the on-site staff or consult the detailed schedule in the conference program</p><p><br></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\">Q14：Are there any recommended hotels near the venue?</strong></p><p><br></p><p><strong>Five-Star</strong></p><p><br></p><p><strong>1、InterContinental Shanghai Expo</strong></p><p>Address: 1188 Xueye Road, Pudong New Area, Shanghai</p><p>Straight-line distance from venue: approx. 3.2 km</p><p><br></p><p><strong>2、Shangri-La Qiantan, Shanghai</strong></p><p>Address: 551 Haiyang West Road, Sanlin Town, Pudong New Area, Shanghai</p><p>Straight-line distance from venue: approx. 2.1 km</p><p><br></p><p><strong>3、MGM Shanghai West Bund</strong></p><p>Address: 688 Yunjin Road, Xuhui District, Shanghai</p><p>Straight-line distance from venue: approx. 570 m</p><p><br></p><p><strong>4、Shanghai Expo Riverside Hotel</strong></p><p>Address: 1588 Expo Avenue, Pudong New Area, Shanghai</p><p>Straight-line distance from venue: approx. 2.8 km</p><p>&nbsp;</p><p><strong>Four-Star</strong></p><p><br></p><p><strong>1、Mercure Shanghai Qiantan</strong></p><p>Address: 480 Yongyao Road, Pudong New Area, Shanghai</p><p>Straight-line distance from venue: approx. 1.8 km</p><p><br></p><p><strong>2、The Shàng by Artyzen Qiantan Shanghai</strong></p><p>Address: 568 Yangsi West Road, Pudong New Area, Shanghai</p><p>Straight-line distance from venue: approx. 2.3 km</p><p><br></p><p><strong>3、Mercure Shanghai Xujiahui South</strong></p><p>Address: 9505 Humin Road, Xuhui District, Shanghai</p><p>Straight-line distance from venue: approx. 2.8 km</p><p><br></p><p><br></p>', 5, 1, NULL, '2026-05-13 06:13:51', NULL, '2026-07-16 13:05:49', 0, 'IV. Venue & Services', 'EN');
INSERT INTO `portal_question` VALUES (22, '尊敬的各位嘉宾：', '<p><br></p><p><br></p><p>欢迎您莅临本次大会！为了帮助您更好地规划行程并顺利参会，我们整理了以下常见问题与解答。请随时查阅，如有未尽事宜，敬请通过文末联系方式与我们联系。</p><p><br></p><p><br></p>', 1, 1, NULL, '2026-05-13 06:30:26', NULL, '2026-06-17 15:23:15', 0, '尊敬的各位嘉宾', 'ZH');
INSERT INTO `portal_question` VALUES (23, 'Distinguished Guests,', '<p><br></p><p><br></p><p>We are delighted to welcome you to this conference. To assist you in planning your visit and participating seamlessly, we have compiled the following Frequently Asked Questions (FAQ). Please feel free to refer to this section, and should you require any additional information, do not hesitate to contact us using the details provided below.</p><p><br></p><p><br></p>', 1, 1, NULL, '2026-05-13 06:34:24', NULL, '2026-06-17 15:55:05', 0, 'Distinguished Guests', 'EN');
INSERT INTO `portal_question` VALUES (24, '五、其他常见问题', '<p><br></p><p><strong>Q15：大会的着装要求</strong></p><p><br></p><p><strong>A：</strong>大会建议商务正装</p><p><br></p><p><br></p><p><strong>Q16：如果有紧急情况或需要现场帮助，可以联系谁？</strong></p><p><br></p><p><strong>A：</strong>您可以前往会议问询处，或联系身边任何佩戴工作人员胸牌的人员或志愿者。或拨打联系电话：<span style=\"color: rgb(51, 51, 51);\">137-0192-6282</span></p><p><br></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\">Q17：是否有线上参会选项？</strong></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\">A：</strong><span style=\"color: rgb(15, 17, 21);\">目前暂未安排线上直播。若后续增加，将第一时间在官网公布</span></p><p><br></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\">Q18：大会是否提供签证邀请函？</strong></p><p><br></p><p><span style=\"color: rgb(15, 17, 21);\"> </span><strong style=\"color: rgb(15, 17, 21);\">A：</strong><span style=\"color: rgb(15, 17, 21);\">如需签证邀请函，请在官网注册时勾选“需要签证邀请函”选项。会务组核实信息后将发送邀请函至您的注册邮箱</span></p><p><br></p><p><br></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\">期盼与您相聚上海，共谱学术新篇！</strong></p><p><br></p><p><strong>大会名称：“海上之光”眼视光学与视觉科学学术会议第十四届近视与接触镜学术会议</strong></p><p><br></p><p><strong>联系人：邓老师</strong></p><p><br></p><p><strong>联系电话：</strong><span style=\"color: rgb(51, 51, 51);\">137-0192-6282</span></p><p><br></p><p><strong>邮箱：</strong>organizerMCLC@163.com</p><p><br></p><p><br></p>', 6, 1, NULL, '2026-06-17 15:29:44', NULL, '2026-07-16 11:46:37', 0, '其他常见问题', 'ZH');
INSERT INTO `portal_question` VALUES (25, 'V. Additional FAQs', '<p><br></p><p><strong>Q15: What is the dress code for the conference?</strong></p><p><br></p><p><strong>A: </strong>Business formal attire is recommended</p><p><br></p><p><br></p><p><strong>Q16: Who should I contact in case of an emergency or if I need on-site assistance?</strong></p><p><br></p><p><strong>A: </strong>Please feel free to approach the Information Desk, any staff member or volunteer wearing an official conference badge, or call the Conference Helpline at +86 <span style=\"color: rgb(51, 51, 51);\">137-0192-6282</span></p><p><br></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\">Q17: Is online participation available?</strong></p><p><br></p><p><span style=\"color: rgb(15, 17, 21);\"> </span><strong style=\"color: rgb(15, 17, 21);\">A: </strong><span style=\"color: rgb(15, 17, 21);\">Live streaming is not currently planned. Should it become available, any updates will be announced on the conference website at the earliest opportunity.</span></p><p><br></p><p><br></p><p><strong style=\"color: rgb(15, 17, 21);\">Q18: Does the conference provide a visa invitation letter?</strong></p><p><br></p><p><strong> A: </strong><span style=\"color: rgb(15, 17, 21);\">If you need a visa invitation letter, please select the \"Visa Invitation Letter Required\" option when registering on the official website. After verifying the information, the organizing committee will send the invitation letter to your registered email address</span></p><p><br></p><p><br></p><p><strong>We look forward to welcoming you to Shanghai and co-authoring a new chapter in academic excellence.</strong></p><p><br></p><p>Conference Title:The 14th Myopia and Contact Lens Conference</p><p><br></p><p>Contact: Ms. DENG</p><p><br></p><p>Tel: <span style=\"color: rgb(51, 51, 51);\">137-0192-6282</span></p><p><br></p><p>Email: organizerMCLC@163.com</p><p><br></p><p><br></p>', 6, 1, NULL, '2026-06-17 15:55:52', NULL, '2026-07-16 11:47:03', 0, ' Additional FAQs', 'EN');
INSERT INTO `portal_speech` VALUES (12, 'MCLC 2026特邀嘉宾演讲集锦 第九期', 'Debarun Dutta', 192, 1, NULL, '2026-04-25 12:56:29', NULL, '2026-06-25 17:53:27', 0, 'Safety first: Antimicrobial strategies for CL-related infections: recent updates', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260425/b9cccc02907347359f41f407450455b0.png', 'Debarun Dutta教授围绕接触镜相关感染的安全性议题，系统梳理了当前软性接触镜与角膜塑形镜在临床应用中的感染风险、抗菌策略及近视控制对眼表的影响，为临床安全实践提供了重要指导。', '<p class=\"ql-align-justify\">	接触镜相关性角膜炎的发病率是衡量其安全性的核心指标。基于多变量分析的流行病学数据显示，接触镜相关微生物角膜炎的发生率为13.9例/万人年，范围在0.9至34.5例/万人年。关于过夜配戴硬性镜片及角膜塑形镜的数据相对有限，严重微生物角膜炎病例并不多见。在儿童配戴软性接触镜方面，研究显示微生物角膜炎发病率为2.7例/万人年，有症状的角膜浸润发生率为42例/万人年，总体而言儿童不良事件发生率与成人相当或更低。</p><p class=\"ql-align-justify\">	抗生素耐药性问题为接触镜相关感染的治疗增添了新的挑战。中国2013至2015年的住院患者数据显示，约27.45%的患者存在抗生素耐药性感染或耐药菌定植，其中单药耐药占11.68%，多药耐药占15.77%。这一严峻背景凸显了在接触镜领域发展有效抗菌策略的迫切性。</p><p class=\"ql-align-justify\">	针对如何抑制微生物污染、降低镜片相关不良事件，Dutta教授系统介绍了多种抗菌策略。研究表明，影响细菌黏附的因素包括镜片材料、表面特性、配戴方式及护理方案。近年来，抗菌接触镜及镜盒的研发取得了积极进展，但临床应用仍需进一步验证。对于角膜塑形镜，文献检索显示超过75%的相关安全性研究发表于过去十年，而感染相关研究中近半数集中于近十年，但多数为屈光矫正或近视控制效果研究，感染防控方面缺乏重大突破。2005至2008年间有29篇报告，多数来自中国。</p><p class=\"ql-align-center\"><img src=\"https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260426/3a915151a8ce456a845c11925d3f782d.png\"></p><p>	<span style=\"background-color: rgb(248, 249, 252); color: rgb(34, 34, 34);\">Dutta教授指出，许多早期棘阿米巴角膜炎病例发生在角膜塑形镜市场尚未规范之时，当时存在使用自来水冲洗镜片等不当操作。当前，提升安全性的关键在于持续开展医生与验光师培训、建立交流网络与导师指导机制、规范配戴程序并要求患者现场演示操作、监督使用推荐护理液、严格执行镜盒清洁与定期更换、以及建立24小时分诊热线等。他强调，禁止使用自来水、充分洗手与擦干双手是预防感染的基础。</span></p><p class=\"ql-align-center\"><img src=\"https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260426/f58df1a14a674f5781a5fee297cc6919.png\"></p><p class=\"ql-align-justify\">	关于近视控制对眼表的不良影响，Dutta教授展示了一项系统综述结果。该综述从PubMed、Scopus及Web of Science筛选900余篇文献，最终纳入109篇临床试验报告，51项研究进入分析，共涉及8113名患者。结果显示，角膜塑形镜对眼表影响最大，主要表现为非侵入性泪膜破裂时间降低、睑板腺功能障碍发生率增高；软性接触镜对眼表参数有中度影响，主要表现为角膜染色和泪膜不稳定性增加；阿托品影响泪液分泌与稳定性；框架眼镜则几乎不产生影响。需要注意的是，研究方法存在显著差异，且软性接触镜相关研究中商业资助比例较高，可能引入偏倚。</p><p class=\"ql-align-justify\">	综上所述，Dutta教授的报告最终指向一个核心结论：接触镜相关安全性的提升，需要从抗菌策略研发、规范护理流程、强化患者教育、定期随访监测等多维度协同推进。在当前抗生素耐药性日益严峻的背景下，安全意识的强化与科学护理的普及，是保障近视控制手段可持续应用的前提。</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/170f28e15c2f425f8cf134852cdd39a6.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Szczotka-Flynn LB, Shovlin JP, Schnider CM, et al. American Academy of Optometry Microbial Keratitis Think Tank. <em>Optom Vis Sci</em>. 2021;98(3):182-198. doi:10.1097/OPX.0000000000001664</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Bullimore MA, Richdale K. Incidence of Corneal Adverse Events in Children Wearing Soft Contact Lenses. <em>Eye Contact Lens</em>. 2023;49(5):204-211. doi:10.1097/ICL.0000000000000976</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Dutta D, Cole N, Willcox M. Factors influencing bacterial adhesion to contact lenses. <em>Mol Vis</em>. 2012;18:14-21.</p><p class=\"ql-align-center\">4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Khan SA, Lee CS. Recent progress and strategies to develop antimicrobial contact lenses and lens cases for different types of microbial keratitis. <em>Acta Biomater</em>. 2020;113:101-118. doi:10.1016/j.actbio.2020.06.039</p><p><br></p>', '博士，现任英国接触镜协会（BCLA）学术委员会主席', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-25/ac679771f7f84667801554aa35cc902f.png', 'ZH');
INSERT INTO `portal_speech` VALUES (13, 'MCLC 2026特邀嘉宾演讲集锦 第八期', '李仕明', 193, 1, NULL, '2026-04-26 09:28:46', NULL, '2026-06-25 17:53:55', 0, 'CRY1 缺失导致昼夜节律紊乱并促进近视形成机制', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260426/911fc16bccd643cf9bf229daaf104b9e.png', '李仕明，首都医科大学附属北京同仁医院眼科主任医师、教授、博士生导师，首届国家优秀青年医师，现任医学视光中心主任、眼视光学系副主任、临床流行病学和循证医学联合教研室主任。主要研究近视等屈光不正的发生机制和防治措施。', '<p>	李仕明教授系统报告了其团队在昼夜节律与近视发病机制方面的系列研究成果，揭示了生物钟基因<em>Cry1</em>在近视发生中的核心作用。</p><p>	近视已成为全球性公共卫生挑战，预计到2050年全球近视人口将达47.58亿。其病因受遗传与环境因素共同影响，其中睡眠不足、夜间光照等节律相关因素日益受到关注。李仕明教授团队基于“安阳儿童眼病研究”发现，睡眠时间增加与儿童近视程度降低显著相关，且在女孩中更为明显，提示昼夜节律紊乱可能参与近视发生。</p><p><img src=\"data:image/png;base64,\"></p><p>	动物实验进一步验证了这一假说。李仕明教授团队构建异常光暗周期小鼠模型，发现节律紊乱组小鼠出现明显近视漂移和眼轴延长，巩膜组织排列疏松，I型胶原纤维比例减少。转录组学分析富集到多巴胺、γ-氨基丁酸等神经递质信号通路，提示节律紊乱通过影响视网膜神经递质系统参与近视调控。</p><p>	在众多生物钟基因中，<em>Cry1</em>引起团队特别关注。<em>Cry1</em>基因敲除小鼠出现自发性近视，表现为屈光向近视漂移、眼轴延长、巩膜厚度变薄，同时视网膜功能发生改变。转录组分析揭示Cry1缺失涉及细胞外基质重塑、氧化应激和炎症激活等途径。</p><p>	机制研究阐明<strong>（未发表数据）</strong>，CRY1蛋白可结合并抑制腺苷酸环化酶，从而降低细胞内cAMP水平。<em>Cry1</em>缺失导致巩膜cAMP含量升高，激活PKA信号通路，进而上调HIF-1α和α-SMA表达，促进成纤维细胞转分化，最终引起巩膜重塑和眼轴延长。在人胚眼巩膜成纤维细胞中，低氧环境下CRY1表达下降，而上调CRY1表达则可逆转这一过程。</p><p>李仕明教授的研究系统揭示了<em>Cry1</em>通过cAMP通路影响巩膜重塑、导致近视发生的分子机制，为近视防控开辟了新靶点。基于此，他提出“节律优化”策略：开发<em>Cry1</em>激动剂、优化光环境（白天增加户外光暴露、夜间减少人造光），以及开展节律基因筛查与多维评估，实现近视风险的个体化预警与精准干预。</p><p><img src=\"data:image/png;base64,\"></p><p><br></p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/9696efb66dda46979cb140e4cfca1dff.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Li SM, Ran AR, Kang MT, et al. Effect of Text Messaging Parents of School-Aged Children on Outdoor Time to Control Myopia: A Randomized Clinical Trial. <em>JAMA Pediatr</em>. 2022;176(11):1077-1083. doi:10.1001/jamapediatrics.2022.3542</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wei SF, Li SM, Liu L, et al. Sleep Duration, Bedtime, and Myopia Progression in a 4-Year Follow-up of Chinese Children: The Anyang Childhood Eye Study. <em>Invest Ophthalmol Vis Sci</em>. 2020;61(3):37. doi:10.1167/iovs.61.3.37IF: 4.7 Q1</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Bai WL, Wang MJ, Gan JH, et al. Circadian rhythm disruption induces myopia in mice. <em>Exp Eye Res</em>. 2026;264:110823. doi:10.1016/j.exer.2025.110823</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Doorly R, Ong J, Waisberg E, et al. Applications of generative adversarial networks in the diagnosis, prognosis, and treatment of ophthalmic diseases. <em>Graefes Arch Clin Exp Ophthalmol</em>. 2025;263(8):2117-2134. doi:10.1007/s00417-025-06830-9</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Talamanca L, Gobet C, Naef F. Sex-dimorphic and age-dependent organization of 24-hour gene expression rhythms in humans. <em>Science</em>. 2023;379(6631):478-483. doi:10.1126/science.add0846</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Nickla DL, Totonelly K. Brief light exposure at night disrupts the circadian rhythms in eye growth and choroidal thickness in chicks. <em>Exp Eye Res</em>. 2016;146:189-195. doi:10.1016/j.exer.2016.03.003</p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Allada R, Bass J. Circadian Mechanisms in Medicine. <em>N Engl J Med</em>. 2021;384(6):550-561. doi:10.1056/NEJMra1802337</p>', '首都医科大学附属北京同仁医院眼科主任医师、教授、博士生导师', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-25/2fe1d677bbf54bc19993d7245bb808d1.png', 'ZH');
INSERT INTO `portal_speech` VALUES (14, 'MCLC 2026特邀嘉宾演讲集锦 第七期', 'Pauline Kang', 194, 1, NULL, '2026-04-26 10:01:47', NULL, '2026-06-25 17:54:31', 0, 'The Influence of Visual Behaviour on Myopia Control Outcomes', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260426/648746189f914244a79ac8f2261c9774.png', 'Pauline Kang，悉尼新南威尔士大学视光学与视觉科学学院副教授。主要研究方向为儿童近视防控及其发病与进展机制', '<p>	Pauline Kang教授围绕视觉行为对近视控制的影响展开系统论述。她指出，近视的风险因素可划分为固定因素与可改变因素两大类，其中户外光照暴露与近距离工作作为核心的可改变因素，正成为近视防控干预的关键靶点。</p><p>	户外光照暴露已被大量研究证实对近视发生具有保护作用，并可能延缓近视进展。Pauline Kang教授强调，起保护作用的是光照本身而非体力活动，其机制尚未完全阐明，目前认为与多巴胺释放及昼夜节律调节相关。在测量方法上，主观问卷易受偏倚影响，可穿戴传感器等客观工具正成为研究新标准。她介绍了ROAM研究、Recess Outside Classroom Trial及上海STORM研究等代表性工作，这些研究通过客观光照监测证实了户外暴露的干预价值。研究提示，光照的时间特征、光谱组成与强度均是影响效应的关键参数。基于现有证据，她建议临床实践中应鼓励儿童每日至少2小时户外光照暴露，可分次累积，并做好紫外线防护。</p><p><img src=\"data:image/png;base64,\"></p><p>	关于近距离工作与近视的关联，Pauline Kang教授指出，更高的教育程度与近视相关，但阅读写作等近距离工作与近视的直接联系仍存争议。部分研究显示持续时长过长与过近用眼距离可能增加风险。随着数字设备普及，儿童个人娱乐及学校教育中的屏幕时间显著增加，这可能带来更近的用眼距离与更长的近距离注视时长，从而改变视觉行为模式。COVID-19疫情期间的行为与环境变化则进一步加剧了近视进展。</p><p><img src=\"data:image/png;base64,\"></p><p>	Pauline Kang教授强调，对近距离用眼行为的准确测量同样依赖客观工具。她介绍了多中心MENOK研究采用可穿戴传感器Vivior连续记录儿童视觉行为，初步结果显示近距离注视时长与近视进展可能存在正向关联，但需更长随访周期验证。该研究纳入的近视儿童接受包括近视防控镜片、接触镜、低浓度阿托品及联合治疗等多种干预方案，为探索不同治疗背景下视觉行为的影响提供了丰富数据。</p><p><img src=\"data:image/png;base64,\"></p><p>	综上，Pauline Kang教授指出深入理解户外光照与近距离工作对视网膜调控信号的影响机制，将为优化近视控制策略提供重要依据。客观监测技术的应用与多中心研究的推进，正推动视觉行为研究从经验判断走向循证实践，为临床医生指导儿童视觉行为、提升近视控制效果开辟了新路径。</p><p><br></p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/1527a3df62c1402684a0d506c20747f8.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wu PC, Chen CT, Lin KK, et al. Myopia Prevention and Outdoor Light Intensity in a School-Based Cluster Randomized Trial. <em>Ophthalmology</em>. 2018;125(8):1239-1250. doi:10.1016/j.ophtha.2017.12.011</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Chen J, Wang J, Qi Z, et al. Smartwatch Measures of Outdoor Exposure and Myopia in Children. <em>JAMA Netw Open</em>. 2024;7(8):e2424595. doi:10.1001/jamanetworkopen.2024.24595</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Zong Z, Zhang Y, Qiao J, Tian Y, Xu S. The association between screen time exposure and myopia in children and adolescents: a meta-analysis. <em>BMC Public Health</em>. 2024;24(1):1625. Published 2024 Jun 18. doi:10.1186/s12889-024-19113-5</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ha A, Lee YJ, Lee M, Shim SR, Kim YK. Digital Screen Time and Myopia: A Systematic Review and Dose-Response Meta-Analysis. <em>JAMA Netw Open</em>. 2025;8(2):e2460026. doi:10.1001/jamanetworkopen.2024.60026</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Morgan IG, French AN, Ashby RS, et al. The epidemics of myopia: Aetiology and prevention. <em>Prog Retin Eye Res</em>. 2018;62:134-149. doi:10.1016/j.preteyeres.2017.09.004</p><h3 class=\"ql-align-center\">Bhandari KR, Ostrin LA. Validation of the Clouclip and utility in measuring viewing distance in adults. <em>Ophthalmic Physiol Opt</em>. 2020;40(6):801-814. doi:10.1111/opo.12735</h3><p><br></p>', '悉尼新南威尔士大学视光学与视觉科学学院副教授', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-25/e46a3a7c3e52469da28155514db4df22.png', 'ZH');
INSERT INTO `portal_speech` VALUES (15, 'MCLC 2026特邀嘉宾演讲集锦 第六期', '吕帆', 195, 1, NULL, '2026-04-26 10:05:34', NULL, '2026-06-25 17:54:53', 0, '高度近视研究与近视防控', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260426/36f7b96049ec474383110b640bc9e2ab.png', '吕帆，教授，博士生导师，温州医科大学眼视光医学部主任，国家眼部疾病临床医学研究中心主任。', '<p>	吕帆教授从全球流行病学趋势出发，系统阐释了高度近视研究的核心命题及其对临床防控的深刻启示。</p><p>	近视已成为全球性的公共卫生挑战。据预测，到2050年，全球高度近视人口比例将增至10%。这一趋势促使学界重新审视近视的本质属性——它正被定义为一种“慢性疾病”。其理由在于：近视具有进展性本质，高度近视可发展为病理性近视，引发不可逆的视力损伤；全球高患病率带来了重大公共卫生挑战；而早期干预已被证明能有效延缓进展。近视防控的终极目标，正是防止近视发生、减缓近视进展，从而避免高度近视及其伴随的视觉损伤。</p><p>	在发病机制层面，近视的发生是遗传与环境因素交互作用的结果。GWAS研究已累计发现284个近视易感基因，却只能解释不足10%的近视人群发病。吕帆教授团队近期通过大样本发现了全新的早发型高度近视致病基因BSG，为理解高度近视的遗传基础提供了新线索。值得注意的是，部分易感基因显著富集于核心功能模块，提示这些模块可能是遗传与环境因素互作的关键环节。</p><p class=\"ql-align-justify\">	基于温州百万学生近视队列研究，吕帆教授团队呈现了中国各年龄段近视与高度近视的患病率分布，且发现高度近视在各个年级持续增加。这一流调证据揭示了近视防控的严峻形势，尤其高度近视的累积效应值得高度警惕。</p><p class=\"ql-align-justify\"><img src=\"data:image/png;base64,\"></p><p class=\"ql-align-justify\">	吕教授深入阐述了高度近视与病理性近视的本质区别。病理性近视是主要致盲原因，其眼底改变包括后巩膜葡萄肿、视网膜下新生血管、视网膜萎缩变性与出血、视网膜脱离等。随着眼轴延长，眼底发生持续性萎缩变性，视功能严重受损。荟萃分析显示，近视性黄斑变性已成为中国、日本、丹麦和荷兰永久失明的主要原因。</p><p class=\"ql-align-justify\"><img src=\"data:image/png;base64,\"></p><p>	从正常眼底到病理性近视，存在一条可追溯的演进路径：正视或低中度近视表现为正常眼底；随着眼轴增长，出现豹纹状眼底；进入单纯高度近视阶段；进一步发展为弥漫性萎缩；最终进入斑片状萎缩、黄斑萎缩及其并发症阶段。这一连续谱系提示，关键问题在于识别具备何种特征的近视者将有高概率进入病理性阶段，从而实施精准干预。</p><p class=\"ql-align-justify\">为揭示单纯性高度近视阶段已存在的功能损伤，吕帆教授团队采用多种先进技术开展研究。微视野计检测发现，单纯性高度近视患者在无任何并发症出现时，就已发生视网膜光敏感度下降。自适应光学眼底照相机显示，高度近视眼与正视眼相比，视锥细胞密度降低、细胞间距增大，提示光感受器细胞已发生损伤和凋亡。OCTA研究进一步揭示，病理性近视脉络膜极度萎缩时，深层视网膜毛细血管会启动对外层视网膜的代偿供血。脉络膜血管指数（CVI）当眼轴超过阈值时显著下降，且与视力呈负相关，可能作为监测病理性近视进展的可靠生物学指标。</p><p class=\"ql-align-justify\"><img src=\"data:image/png;base64,\"></p><p>	基于上述研究证据，吕帆教授提出高度近视防控的核心策略：重点关注近视前期，延缓发病、降低发病率；低度近视阶段，控制进展、降低高度近视风险；高度近视阶段，减少不可逆的视力丧失和眼底并发症。</p><p class=\"ql-align-justify\">综上，吕帆教授的报告最终揭示：近视防控绝非单纯的度数管理，而是贯穿生命周期的慢性病系统工程。近视防控，任重而道远。</p><p><br></p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260515/47ac4d6a44784c9097b87ae627fa9ee5.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Holden BA, Fricke TR, Wilson DA, et al. Global Prevalence of Myopia and High Myopia and Temporal Trends from 2000 through 2050. <em>Ophthalmology</em>. 2016;123(5):1036-1042. doi:10.1016/j.ophtha.2016.01.006</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Goodman RA, Posner SF, Huang ES, Parekh AK, Koh HK. Defining and measuring chronic conditions: imperatives for research, policy, program, and practice. <em>Prev Chronic Dis</em>. 2013;10:E66. doi:10.5888/pcd10.120239</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Tedja MS, Wojciechowski R, Hysi PG, et al. Genome-wide association meta-analysis highlights light-induced signaling as a driver for refractive error. <em>Nat Genet</em>. 2018;50(6):834-848. doi:10.1038/s41588-018-0127-7</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Xu L, Zhuang Y, Zhang G, et al. Design, methodology, and baseline of whole city-million scale children and adolescents myopia survey (CAMS) in Wenzhou, China. <em>Eye Vis (Lond)</em>. 2021;8(1):31. doi:10.1186/s40662-021-00255-1</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Haarman AEG, Enthoven CA, Tideman JWL, Tedja MS, Verhoeven VJM, Klaver CCW. The Complications of Myopia: A Review and Meta-Analysis. <em>Invest Ophthalmol Vis Sci</em>. 2020;61(4):49. doi:10.1167/iovs.61.4.49</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Tideman JW, Snabel MC, Tedja MS, et al. Association of Axial Length With Risk of Uncorrectable Visual Impairment for Europeans With Myopia. <em>JAMA Ophthalmol</em>. 2016;134(12):1355-1363. doi:10.1001/jamaophthalmol.2016.4009</p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Haarman AEG, Enthoven CA, Tideman JWL, Tedja MS, Verhoeven VJM, Klaver CCW. The Complications of Myopia: A Review and Meta-Analysis. <em>Invest Ophthalmol Vis Sci</em>. 2020;61(4):49. doi:10.1167/iovs.61.4.49</p>', '教授，博士生导师，温州医科大学眼视光医学部主任', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-25/d5beba5162ce4d65954cd3ce8e7e6f12.png', 'ZH');
INSERT INTO `portal_speech` VALUES (16, 'MCLC 2026特邀嘉宾演讲集锦 第五期', 'Takahiro Hiraoka', 196, 1, NULL, '2026-04-26 10:09:26', NULL, '2026-06-25 17:55:32', 0, '日本角膜塑形镜相关近视控制与微生物性角膜炎', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260426/224875b3dc6f4ed082a47a66ae8575f9.png', 'Takahiro Hiraoka，副教授，筑波大学眼科医学研究所。\n\n', '<p>	Takahiro Hiraoka教授系统回顾了其团队在角膜塑形镜（OK镜）领域长达十余年的研究成果，从长期疗效、联合治疗、镜片沉积物风险到感染并发症的流行病学数据，全面呈现了OK镜在临床应用中卓越的控制效果与不容忽视的安全管理。</p><p>	关于OK镜的近视控制效果，Hiraoka教授展示了其团队2018年发表的十年观察性研究，该研究对比了104眼持续配戴OK镜与78眼配戴软性接触镜的患者，结果证实长期OK镜配戴能够持续有效地抑制眼轴增长。在联合治疗方面，多项研究显示OK镜联合0.01%阿托品可进一步增强眼轴控制效果。关于治疗区直径对眼轴增长的影响，研究表明较小的光学区（5mm）比较大光学区（6mm）设计能带来更好的控制效果。此外，OK镜的联合应用以及其在屈光参差治疗中的价值也在临床研究中得到验证。</p><p><img src=\"data:image/png;base64,\"></p><p>然而，Hiraoka教授警示，OK镜的安全相关问题必须引起高度重视。其团队对174片佩戴数年的OK镜片进行的沉积物分析显示，OK镜表面易沉积蛋白质和脂质，尤其是反转弧区域，这会使生物膜形成量增加6倍。此外这些沉积物会显著增加棘阿米巴的黏附量。针对顽固沉积物，Hiraoka教授推荐定期使用含次氯酸钠的强效清洁剂，其不仅能够有效清除沉积物、平滑镜片表面，还具备广谱消毒作用，对细菌、真菌、棘阿米巴乃至新冠病毒均有杀灭效果，在欧洲和中国已获批作为消毒剂使用。</p><p><img src=\"data:image/png;base64,\"></p><p>关于OK镜相关微生物角膜炎的发生率，Hiraoka教授引用了多项国际流行病学研究数据。美国2013年的研究显示其发生率为7.7/万人年，而俄罗斯2021年的研究显示其发生率为4.9-5.3/万人年，与日抛型软镜相当。Hiraoka教授团队2025年最新发表的多中心研究纳入了1438例OK镜配戴者，计算出的感染发生率为5.4/万人年，与俄罗斯的研究结果相近，证实近年来感染率呈现下降趋势。Hiraoka教授同时分享了四例典型的感染病例，病原体包括铜绿假单胞菌和棘阿米巴，所有病例最终均停用OK镜并转为日抛软镜。</p><p><img src=\"data:image/png;base64,\"></p><p>	综上，Takahiro Hiraoka教授的报告揭示：角膜塑形术的近视控制效果已获长期循证支持，但其临床价值的实现，必须以科学护理构筑的安全防线为前提。</p><p><br></p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/5b3df57ff29143a6ba239427859ee227.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Hiraoka T, Sekine Y, Okamoto F, Mihashi T, Oshika T. Safety and efficacy following 10-years of overnight orthokeratology for myopia control. <em>Ophthalmic Physiol Opt</em>. 2018;38(3):281-289. doi:10.1111/opo.12460</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Kinoshita N, Konno Y, Hamada N, Kanda Y, Shimmura-Tomita M, Kakehashi A. Additive effects of orthokeratology and atropine 0.01% ophthalmic solution in slowing axial elongation in children with myopia: first year results. <em>Jpn J Ophthalmol</em>. 2018;62(5):544-553. doi:10.1007/s10384-018-0608-3</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Guo B, Cheung SW, Kojima R, Cho P. One-year results of the Variation of Orthokeratology Lens Treatment Zone (VOLTZ) Study: a prospective randomised clinical trial. <em>Ophthalmic Physiol Opt</em>. 2021;41(4):702-714. doi:10.1111/opo.12834</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Hiraoka T, Yoshimitsu M, Santodomingo-Rubido J, Kondo H, Oshika T. A novel quantitative evaluation of deposits adhered to worn orthokeratology contact lenses. <em>Jpn J Ophthalmol</em>. 2021;65(6):855-863. doi:10.1007/s10384-021-00873-1</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Bullimore MA, Sinnott LT, Jones-Jordan LA. The risk of microbial keratitis with overnight corneal reshaping lenses. <em>Optom Vis Sci</em>. 2013;90(9):937-944. doi:10.1097/OPX.0b013e31829cac92</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Hiraoka T, Matsumura S, Hori Y, Kamiya K, Miyata K, Oshika T. Incidence of microbial keratitis associated with overnight orthokeratology: a multicenter collaborative study. <em>Jpn J Ophthalmol</em>. 2025;69(1):139-143. doi:10.1007/s10384-024-01137-4</p><p class=\"ql-align-center\">7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Xiong R, Wang W, Tang X, et al. Myopia Control Effect of Repeated Low-Level Red-Light Therapy Combined with Orthokeratology: A Multicenter Randomized Controlled Trial. <em>Ophthalmology</em>. 2024;131(11):1304-1313. doi:10.1016/j.ophtha.2024.05.015</p><p><br></p>', '副教授，筑波大学眼科医学研究所', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-25/4f2b6c54f43547a7a7b17f920dbd2d77.png', 'ZH');
INSERT INTO `portal_speech` VALUES (17, 'MCLC 2026特邀嘉宾演讲集锦 第四期', '周行涛', 197, 1, NULL, '2026-04-26 10:12:11', NULL, '2026-06-25 17:55:58', 0, 'AI赋能全周期眼健康', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260426/946d91ed24954b55a033acc2fc7e98c4.png', '周行涛，主任医师，教授，博士生导师，现任复旦大学附属眼耳鼻喉科医院院长、国家眼科专业质控中心主任、上海市眼视光学研究中心主任、上海激光与裸眼3D视觉健康工程技术研究中心主任。', '<p>	周行涛教授系统展示了其如何将人工智能技术深度融合于近视防治的全周期管理，从病因探索、早期筛查、风险预警到手术规划与疗效评估，构建起一套贯穿“筛-诊-治-防”的数智化创新体系。</p><p class=\"ql-align-justify\">	我国近视防控形势严峻，青少年近视不断攀升且呈现低龄化、重度化、发展快和程度深的趋势。周行涛教授团队联合多学科，通过覆盖超250万人的大队列研究，将近视防控的关口前移至全生命周期早期阶段，揭示妊娠期高血压疾病与子代高度屈光不正风险的显著关联性，提示预防高度近视应从孕期开始关注，这对于高度近视防治具有创新性且重要的指导意义。</p><p class=\"ql-align-justify\"><img src=\"data:image/png;base64,\"></p><p class=\"ql-align-justify\">	在早期筛查与风险预警领域，团队研发了多项AI工具以实现精准防控。通过构建AI全眼屈光模型，可在免散瞳条件下准确测算儿童生理性远视储备，ACC高达0.953；同时，集成多源数据建立的近视风险预测模型，即学校近视筛查AI复合一体机与云屈光档案系统，能提供个性化预警与防控建议。此外，团队利用AI影像技术实现儿童眼底豹纹密度自动定量分析，证实其与眼轴快速增长显著相关，为近视进展监测提供了新颖的无创生物标志物。</p><p class=\"ql-align-justify\"><img src=\"data:image/png;base64,\"></p><p>	在屈光手术的精准化方面，AI技术同样发挥了核心作用。针对ICL植入术，团队利用大数据和机器学习模型，对影响术后拱高和晶体尺寸选择的18个特征参数进行分析，建立的预测模型使ICL尺寸选择准确率超过82%。对于SMILE手术，团队创新性地开发了基于MatLab的自动化算法，能够客观、精确地测量术后有效光学区的大小和形态，解决了传统方法重复性差的临床难题。</p><p class=\"ql-align-justify\">团队还致力于构建完整的国产化“AI+眼科”临床应用生态。研发的AI角膜塑形镜验配平台可辅助OK镜验配，提升效率；国产数智化眼前节分析系统针对圆锥角膜构建早筛模型，其诊断灵敏度与特异度提升至98%以上；国产数智化眼前节分析系统——AI辅助ICL个性化设计平台成功实现专利转化与产业化。这些成果形成了“AI术前评估-手术规划-术后随访”的闭环服务，有力推动了国产眼科设备与耗材产业的升级。</p><p class=\"ql-align-justify\"><img src=\"data:image/png;base64,\"></p><p class=\"ql-align-justify\">	综上，周行涛教授团队通过将人工智能深度植入近视防治管理全周期的各个环节，从病因研究、早期筛查、手术规划到生态构建，不仅显著提升了诊疗的精准性与效率，更创新了近视全周期管理的模式。</p><p><br></p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/d551a253100542cb937e4ad3563942ab.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Li M, Huang C, Yang W, et al. Evaluation of Hypertensive Disorder of Pregnancy and High Refractive Error in Offspring During Childhood and Adolescence. <em>JAMA Netw Open</em>. 2023;6(4):e238694. Published 2023 Apr 3. doi:10.1001/jamanetworkopen</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Chen Z, Gu D, Wang B, et al. Significant myopic shift over time: Sixteen-year trends in overall refraction and age of myopia onset among Chinese children, with a focus on ages 4-6 years. <em>J Glob Health</em>. 2023;13:04144. Published 2023 Nov 9. doi:10.7189/jogh.13.04144</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wei R, Li J, Yang W, et al. ASSOCIATION OF TESSELLATION DENSITY WITH PROGRESSION OF AXIAL LENGTH AND REFRACTION IN CHILDREN: An Artificial Intelligence-Assisted 4-Year Study. <em>Retina</em>. 2024;44(3):527-536. doi:10.1097/IAE.0000000000003991</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wang Y, Wei R, Yang D, et al. Development and validation of a deep learning model to predict axial length from ultra-wide field images. <em>Eye (Lond)</em>. 2024;38(7):1296-1300. doi:10.1038/s41433-023-02885-2</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Shen Y, Wang L, Jian W, et al. Big-data and artificial-intelligence-assisted vault prediction and EVO-ICL size selection for myopia correction. <em>Br J Ophthalmol</em>. 2023;107(2):201-206. doi:10.1136/bjophthalmol-2021-319618</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Huang Y, Ding X, Han T, Fu D, Yu Z, Zhou X. Effective Optical Zone Following Small Incision Lenticule Extraction for Myopia Calculated With Two Novel Methods. <em>J Refract Surg</em>. 2022;38(7):414-421. doi:10.3928/1081597X-20220608-02</p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Yan YN, Wang YX, Xu L, Xu J, Wei WB, Jonas JB. Fundus Tessellation: Prevalence and Associated Factors: The Beijing Eye Study 2011. <em>Ophthalmology</em>. 2015;122(9):1873-1880. doi:10.1016/j.ophtha.2015.05.031</p><p>8.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Guo Y, Liu L, Zheng D, et al. Prevalence and Associations of Fundus Tessellation Among Junior Students From Greater Beijing. <em>Invest Ophthalmol Vis Sci</em>. 2019;60(12):4033-4040. doi:10.1167/iovs.19-27382</p>', '主任医师，教授，博士生导师，现任复旦大学附属眼耳鼻喉科医院院长', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-25/29e1ce4a92cd4503a5902411d56fdea4.png', 'ZH');
INSERT INTO `portal_speech` VALUES (18, 'MCLC 2026特邀嘉宾演讲集锦 第三期', 'Langis Michaud', 198, 1, NULL, '2026-04-26 10:18:40', NULL, '2026-06-25 17:56:37', 0, 'How to improve myopia control with optical devices : understanding the retinal response to visual signal', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260426/88c48d9d775d4329b5306b6f7b840282.png', 'Langis Michaud教授围绕“视网膜对视觉信号的应答”核心主题，系统阐述了视网膜调控眼球生长的底层机制，并基于该机制提出光学镜片优化近视防控效果的实践路径。', '<p>	Langis Michaud教授围绕“视网膜对视觉信号的应答”核心主题，系统阐述了视网膜调控眼球生长的底层机制，并基于该机制提出光学镜片优化近视防控效果的实践路径。</p><p class=\"ql-align-justify\">	眼球生长主要由视网膜调控，其通过解析视觉信号激活视网膜—巩膜生化通路以驱动正视化过程。该系统的功能健全是维持正视状态的关键，而近视的发生则与其部分功能缺失有关。黄斑区聚焦异常（类似形觉剥夺）、周边视网膜离焦，均会影响屈光发育。</p><p class=\"ql-align-justify\"><img src=\"data:image/png;base64,\"></p><p>	从视网膜功能分化来看，光感受器可通过响应光线波长、物体空间朝向与运动方向等不同视觉刺激实现功能特化，其将光能量传递至15种不同亚型的双极细胞后，完成视觉信息的特异性提取与编码，再通过两条核心通路完成信号传输：明暗通路主要负责图像处理，色觉通路则参与模糊信息解析，两者协同实现视网膜对图像信息的精准解析。</p><p>	视网膜对图像信息的解析主要依赖对比度、空间频率两大维度，其敏感通路可同时编码光增强与减弱信号，是感知物体与空间对比度、形状及边缘信息的关键。其中，双极细胞的“中心—周边拮抗”感受野结构是识别对比度与边缘信息的基础。</p><p>	在理解上述理论基础后，Langis Michaud教授重点讲解了视网膜信号应答异常与近视发生、进展的核心关联，明确两大关键机制：</p><p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;明通路（ON通路）与暗通路（OFF通路）对眼球生长具有相反的调控作用：抑制明通路或刺激暗通路会促进眼轴生长。近视在某种程度上可被视为明通路的功能缺陷状态。从遗传学基础来看，明/暗通路的病理性激活是驱动高度近视的关键，其根源与影响视色素基因的遗传突变（特定单倍型）相关，约25%的人群携带此类突变，高度近视患病风险为普通人群的3倍。</p><p class=\"ql-align-justify\">2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;色像差（包括纵向与横向色差）为视网膜提供了辨别离焦性质（正/负）的关键信号，进而指导发出“生长”或“停止生长”的指令。然而，近视眼对该信号的敏感性常减弱。此外，视网膜具备神经适应性，这可能是所有光学干预手段疗效随时间推移出现平台效应的重要原因。</p><p class=\"ql-align-justify\"><img src=\"data:image/png;base64,\"></p><p>	基于上述视网膜信号应答与近视调控的核心机制， Langis Michaud教授结合临床研究经验，提出光学镜片优化近视防控效果的具体策略，明确光学干预的核心原则——通过精准调控视网膜离焦状态、激活明通路功能，改善视网膜信号应答，进而抑制眼球异常生长，具体内容如下：</p><p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;透镜光学特性的应用原理：</p><p>a)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;透镜的屈光变化可改变目标物像大小，进而影响视网膜感受野应答：刺激局限于感受野中心区时，视网膜神经反应增强；刺激波及周边区时，因周边拮抗机制导致反应减弱；刺激超出周边区时，则无明显神经反应。</p><p>b)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;离焦梯度可干扰明/暗刺激识别过程，且对ON与OFF通路的影响存在差异，其可扩大ON通路感受野、缩小OFF通路感受野，解释了离焦对明、暗刺激感知的差异化效应。</p><p>c)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;值得注意的是，当物像尺寸与亮度不变时，ON与OFF通路无法可靠的区分正离焦与负离焦，但可精准传递离焦程度和物像放大率的变化信号，这也解释了为何正镜片相较于负镜片，更能产生积极的近视矫治效果——放大率是影响视网膜信号应答的关键因素，优于离焦符号的影响。</p><p>&nbsp;</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;光学镜片的临床应用规范：</p><p>a)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;避免使用单光镜片，单光镜片无法改善周边视网膜负球面像差及鼻侧视网膜垂直方向离焦，难以有效调控视网膜信号应答。</p><p>b)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;密切随访患者屈光状态，及时调整矫正方案，若中心视力持续模糊，易引发形觉剥夺，加速近视进展。</p><p>c)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;严禁近视欠矫的眼镜，屈光度变化超过0.25D时，需及时更换镜片，确保视网膜获得清晰视觉刺激，避免信号通路紊乱。</p><p>d)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;强调全天佩戴光学矫正镜片，确保离焦刺激持续作用于视网膜，维持稳定的信号调控效应。</p><p>e)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;微透镜镜片中优先选择正镜片，其可放大视觉信号尺寸，更易激活ON通路。</p><p>f)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;优选中心视远区设计的镜片，此类镜片可提供更高的正球面像差和更大的放大率，更符合视网膜调控需求。</p><p>g)&nbsp;&nbsp;阿托品可通过扩大瞳孔直径，增强离焦与对比度的剂量效应。</p><p class=\"ql-align-justify\">h)&nbsp;&nbsp;已近视患者或需要更高的剂量效应或不同的光学刺激，神经适应可发生在干预第1年后，此时需要及时调整策略。</p><p class=\"ql-align-justify\"><img src=\"data:image/png;base64,\"></p><p class=\"ql-align-justify\">综上，Langis Michaud教授的汇报表明近视的光学管理本质是向视网膜传递精确调控信号。通过深入理解视网膜的信号处理机制与像差的作用，并据此优化光学镜片的设计与应用策略，可在将来实现更精准、有效的近视控制。</p><p><br></p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/51490af85c254b149a82cbd8bc96d776.mp4', '<p><span style=\"color: black;\">1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wallman J, Winawer J. Homeostasis of eye growth and the question of myopia. </span><em style=\"color: black;\">Neuron</em><span style=\"color: black;\">. 2004;43(4):447-468. doi:10.1016/j.neuron.2004.08.008</span></p><p><span style=\"color: black;\">2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Brown DM, Mazade R, Clarkson-Townsend D, Hogan K, Datta Roy PM, Pardue MT. Candidate pathways for retina to scleral signaling in refractive eye growth. </span><em style=\"color: black;\">Exp Eye Res</em><span style=\"color: black;\">. 2022;219:109071. doi:10.1016/j.exer.2022.109071</span></p><p><span style=\"color: black;\">3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Summers JA, Schaeffel F, Marcos S, Wu H, Tkatchenko AV. Functional integration of eye tissues and refractive eye development: Mechanisms and pathways. </span><em style=\"color: black;\">Exp Eye Res</em><span style=\"color: black;\">. 2021;209:108693. doi:10.1016/j.exer.2021.108693</span></p><p><span style=\"color: black;\">4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Romashchenko D, Rosén R, Lundström L. Peripheral refraction and higher order aberrations. </span><em style=\"color: black;\">Clin Exp Optom</em><span style=\"color: black;\">. 2020;103(1):86-94. doi:10.1111/cxo.12943</span></p><p><span style=\"color: black;\">5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Lundström L, Gustafsson J, Unsbo P. Population distribution of wavefront aberrations in the peripheral human eye. </span><em style=\"color: black;\">J Opt Soc Am A Opt Image Sci Vis</em><span style=\"color: black;\">. 2009;26(10):2192-2198. doi:10.1364/JOSAA.26.002192</span></p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ichinose T, Habib S. ON and OFF Signaling Pathways in the Retina and the Visual System. <em>Front Ophthalmol (Lausanne)</em>. 2022;2:989002. doi:10.3389/fopht.2022.989002</p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Poudel S, Jin J, Rahimi-Nasrabadi H, et al. Contrast Sensitivity of ON and OFF Human Retinal Pathways in Myopia. <em>J Neurosci</em>. 2024;44(3):e1487232023. Published 2024 Jan 17. doi:10.1523/JNEUROSCI.1487-23.2023&nbsp;</p><p>8.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Neitz M, Neitz J. Intermixing the <em>OPN1LW</em> and <em>OPN1MW</em> Genes Disrupts the Exonic Splicing Code Causing an Array of Vision Disorders. <em>Genes (Basel)</em>. 2021;12(8):1180. Published 2021 Jul 29. doi:10.3390/genes12081180</p><p>9.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;https://www.youtube.com/watch?v=4jJS4MnkcWw</p><p>10.&nbsp;&nbsp;&nbsp;https://www.youtube.com/watch?v=4jJS4MnkcWw</p><p>11.&nbsp;&nbsp;&nbsp;Yang Y, Lee D, Gettinger K, et al. Mechanisms Underlying Myopia Progression from Visual Signaling to Metabolic Remodeling in Retina. <em>JMA J</em>. 2025;8(4):1031-1038. doi:10.31662/jmaj.2025-0268</p><p>12.&nbsp;&nbsp;&nbsp;Swiatczak B, Scholl HPN, Schaeffel F. Retinal \"sweet spot\" for myopia treatment. <em>Sci Rep</em>. 2024;14(1):26773. Published 2024 Nov 5. doi:10.1038/s41598-024-78300-x</p><p>13.&nbsp;&nbsp;&nbsp;Neitz J, Neitz M. Diffusion Optics Technology (DOT): A Myopia Control Spectacle Lens Based on Contrast Theory. <em>Transl Vis Sci Technol</em>. 2024;13(10):42. doi:10.1167/tvst.13.10.42</p><p>14.&nbsp;&nbsp;&nbsp;Zheleznyak L, Liu C, Winter S. Chromatic cues for the sign of defocus in the peripheral retina. <em>Biomed Opt Express</em>. 2024;15(9):5098-5114. Published 2024 Aug 8. doi:10.1364/BOE.537268</p><p>15.&nbsp;&nbsp;&nbsp;Gawne TJ, Norton TT. An opponent dual-detector spectral drive model of emmetropization. <em>Vision Res</em>. 2020;173:7-20. doi:10.1016/j.visres.2020.03.011</p><p>16.&nbsp;&nbsp;&nbsp;James Polans, Bart Jaeken, Ryan P McNabb, Lucia Hervella, Pablo Artal, Joseph A Izatt; Wide-field schematic model of the Human Eye with Asymmetrically Tilted and Decentered Lens. <em>Invest. Ophthalmol. Vis. Sci.</em> 2015;56(7 ):6019</p><p>17.&nbsp;&nbsp;&nbsp;Neitz J, Neitz M. Clarification on the understanding of contrast theory in relation to the article \"ON and OFF receptive field processing in the presence of optical scattering\": comment. <em>Biomed Opt Express</em>. 2024;15(2):789-792. doi:10.1364/BOE.504315</p><p class=\"ql-align-center\">18.&nbsp;&nbsp;&nbsp;Pons C, Mazade R, Jin J, Dul MW, Alonso JM. Optical defocus affects differently ON and OFF visual pathways. <em>iScience</em>. 2025;28(6):112500. Published 2025 Apr 22. doi:10.1016/j.isci.2025.112500</p><p class=\"ql-align-center\"><br></p><p><br></p>', '蒙特利尔大学接触镜科主任、美国眼视光学会资深会员', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-25/747fd2e789b9467aab617dcc6e4ff2dd.png', 'ZH');
INSERT INTO `portal_speech` VALUES (19, 'MCLC 2026特邀嘉宾演讲集锦 第十期', '杜嗣河', 191, 1, NULL, '2026-04-26 11:09:42', NULL, '2026-06-25 17:52:51', 0, 'Myopic defocus for myopia control - from present to future', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260426/6d56d783cc534f63b2b0717d65369cbe.png', '杜嗣河，博士。现任香港理工大学讲师、实验视光学讲座教授、香港理工大学实验视光学访问讲座教授、香港科技园视觉与眼科研究中心创始主任及高级顾问，致力于近视与青光眼的发病机制及病理机制研究。 ', '<p><strong>主旨报告内容回顾</strong></p><p>	杜嗣河教授系统回顾了近视性离焦作为近视控制手段的起源、临床证据及未来发展方向。</p><p>	近视性离焦控制近视的基本原理源于视觉引导眼轴生长的实验观察。当视网膜同时接收近视性离焦与远视性离焦两种竞争性信号时，眼球会选择性地响应抑制生长的近视性离焦信号。这一发现在灵长类动物模型中得到了验证，为后续光学干预策略奠定了理论基础。基于此原理，杜嗣河教授团队先后开发了离焦软性隐形接触镜（DISC）和多区正向离焦镜片（DIMS）。DISC 镜片可同时在视网膜前提供清晰的中心视野和持续的近视性离焦。DIMS镜片能够在矫正屈光不正的同时，在整个视野范围内提供持续的近视性离焦信号。两年随机对照试验显示，与配戴单光镜片组相比，DIMS组近视进展量减少0.44 ± 0.09 D，眼轴增长量减少0.34 ± 0.04 mm。六年随访数据显示，持续配戴DIMS镜片的儿童年均屈光度进展仅-0.15&nbsp;D，眼轴进展仅0.1&nbsp;mm。八年随访进一步证实，配戴时间越长，控制效果越显著。</p><p class=\"ql-align-center\"><img src=\"https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260426/90014ed24a1f4fe2916a2e4dd8b13f69.png\"></p><p>	DIMS的疗效在不同人群中得到验证。欧洲多项研究显示，DIMS可有效减缓儿童近视进展，且在10岁以上儿童中效果更佳。英国多中心观察性研究显示，白种人与亚洲儿童的眼轴控制效果相当。此外，相关研究证实COVID-19疫情期间，高强度近距离工作背景下，DIMS依然展现出稳定的控制效果。</p><p>	除DIMS外，其他基于离焦原理的光学设计同样积累了长期证据。双焦点软性接触镜（MiSight）六年研究数据显示，与单光镜片相比，持续治疗可减少眼轴增长0.52 mm，使眼球生长接近正视眼水平。高非球面微透镜（HAL）五年随访显示，近视进展较单光镜组减少1.75 D，眼轴增长减缓0.72 mm；六年数据进一步证实其疗效。欧洲CEME研究的一年结果表明，MyoCare镜片可显著减缓近视进展。</p><p>	为进一步提升疗效，杜嗣河教授指出联合治疗成为重要方向。欧洲研究显示，DIMS联合0.01%阿托品效果优于单用DIMS。中国人群研究同样证实，DIMS联合阿托品具有更强控制效应。</p><p>	杜嗣河教授表明离焦镜片正在不断优化。通过增加非聚焦光的体积（VoNFL）、提升微透镜的附加度与非球面性，H.A.L.T. MAX技术在新加坡儿童的交叉研究中显示出比H.A.L.T.更优的眼轴控制效果，且在低龄儿童（＜8.5岁）中表现更佳。新一代DIMS（DIMS TED）采用三重增强设计：更小的中心光学区、更高的离焦附加度及扩大的离焦区域，初步6个月中期分析显示，其在控制等效球镜与眼轴增长方面均显著优于标准DIMS。</p><p class=\"ql-align-center\"><img src=\"https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260426/b820b4c3595e452796f54780e43fe177.png\"></p><p>	最后，杜嗣河教授总结，基于近视性离焦的光学干预手段已证实有效且长期安全，联合药物或光疗可进一步增强效果，新一代离焦镜片正朝着更高剂量、更优设计方向演进。逆转眼轴增长虽仍属少数现象，但已初见端倪。未来目标可通过优化离焦剂量与联合策略，降低高度近视人群比例，为近视防控提供更强大的光学武器。</p><p class=\"ql-align-center\"><img src=\"https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260426/b0d25f4ef245421990fb58bc0d5da0cb.png\"></p><p><br></p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/321653bec35949c193a99aef4a0644ba.mp4', '<p>1.&nbsp;Lam CS, Tang WC, Tse DY, Tang YY, To CH. Defocus Incorporated Soft Contact (DISC) lens slows myopia progression in Hong Kong Chinese schoolchildren: a 2-year randomised clinical trial.&nbsp;<em>Br J Ophthalmol</em>. 2014;98(1):40-45. doi:10.1136/bjophthalmol-2013-303914</p><p>2.&nbsp;Lam CSY, Tang WC, Tse DY, et al. Defocus Incorporated Multiple Segments (DIMS) spectacle lenses slow myopia progression: a 2-year randomised clinical trial.&nbsp;<em>Br J Ophthalmol</em>. 2020;104(3):363-368. doi:10.1136/bjophthalmol-2018-313739</p><p>3.&nbsp;Choi KY, Chun RKM, Tang WC, To CH, Lam CS, Chan HH. Evaluation of an Optical Defocus Treatment for Myopia Progression Among Schoolchildren During the COVID-19 Pandemic.&nbsp;<em>JAMA Netw Open</em>. 2022;5(1):e2143781. doi:10.1001/jamanetworkopen.2021.43781</p><p>4.&nbsp;Li X, Huang Y, Liu C, et al. Myopia control efficacy of spectacle lenses with highly aspherical lenslets: results of a 5-year follow-up study.&nbsp;<em>Eye Vis (Lond)</em>. 2025;12(1):10. doi:10.1186/s40662-025-00427-3</p><p>5.&nbsp;Alvarez-Peregrina C, Sanchez-Tena MA, Villa-Collar C, et al. Clinical evaluation of MyoCare in Europe (CEME) for myopia management: One-year results.&nbsp;<em>Ophthalmic Physiol Opt</em>. 2025;45(4):1025-1035. doi:10.1111/opo.13517</p><p>6.&nbsp;Lee CY, Yang SF, Chang YL, Huang JY, Lian IB, Chang CK. The effect of defocus incorporated multiple segment spectacles\' lenses combined with different concentrations atropine for myopia control.&nbsp;<em>Sci Rep</em>. 2025;15(1):12356. doi:10.1038/s41598-025-91089-7</p><p>7.&nbsp;Yang Y, Liu S, Gao W, et al. Synergistic effect of defocus incorporated multiple segment glasses and repeated low level red light therapy against myopia progression.&nbsp;<em>Sci Rep</em>. 2025;15(1):3996. doi:10.1038/s41598-024-81363-5</p><p>8.&nbsp;Nallour Raveendran R, Ong WS, Wong YL, et al. Effect of Increased Power and Asphericity of Highly Aspherical Lenslets on Myopia Control Efficacy: A Contralateral Crossover Study.&nbsp;<em>Transl Vis Sci Technol</em>. 2025;14(11):9. doi:10.1167/tvst.14.11.9</p>', '杜嗣河，博士。现任香港理工大学讲师、实验视光学讲座教授、香港理工大学实验视光学访问讲座教授、香港科技园视觉与眼科研究中心创始主任及高级顾问，致力于近视与青光眼的发病机制及病理机制研究', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-25/d2b6aa4029984c5da6b5f9ee4dae2ac4.png', 'ZH');
INSERT INTO `portal_speech` VALUES (20, 'MCLC 2026特邀嘉宾演讲集锦 第十一期', '何鲜桂', 190, 1, NULL, '2026-04-26 11:17:26', NULL, '2026-06-25 17:52:09', 0, 'The Role of Axial Length in Children Myopia Management from Evidence to Practice', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260426/d69d8fd709df4a34a92ac4595874e0e1.jpeg', '何鲜桂教授系统阐述了眼轴长度在儿童近视防控管理中的应用价值，从横断面筛查到纵向动态管理，从研究证据到临床实践，为近视防控工作提供了可操作的路径指引。', '<p><strong>主旨报告内容回顾</strong></p><p>	何鲜桂教授系统阐述了眼轴长度在儿童近视防控管理中的应用价值，从横断面筛查到纵向动态管理，从研究证据到临床实践，为近视防控工作提供了可操作的路径指引。</p><p>	传统的横断面近视筛查主要依赖裸眼视力联合非睫状肌麻痹验光，该方法虽能快速判定近视状态，但无法准确测量真实屈光度，尤其对于远视或低中度近视儿童，散瞳前后验光差异可达50度以上。因此，要实现近视的纵向动态管理，需寻求睫状肌麻痹的替代指标。何鲜桂教授指出，眼轴长度正是这一理想指标。3岁后角膜基本稳定，屈光度变化主要来源于眼轴与晶状体的代偿。随着晶状体代偿能力随年龄增长逐渐减弱，容许的眼轴“安全”增长量亦应逐渐减小。</p><p class=\"ql-align-center\"><img src=\"https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260426/4f4a49ba469d4ed68ee1a94535663b30.png\"></p><p>	何鲜桂教授团队近年来围绕眼轴发表了一系列重要研究。团队建立了中国4-18岁儿童青少年的眼轴生长曲线，发现眼轴随年龄增长而增加，15岁后增速减慢。例如，18岁时第5百分位为22.79mm，第95百分位为24.97mm。通过案例展示，团队强调需要结合个体眼轴所处的百分位进行综合判断，而非仅凭单次测量值。此外，AL/CR（眼轴长度与角膜曲率半径之比）在横断面筛查中可作为近视风险的提示指标，超过特定截断值预示近视风险增高，但在3-5岁人群中性能有限。</p><p class=\"ql-align-center\"><img src=\"https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260426/4e9ce8becf65465180518c1eabeab85c.png\"></p><p class=\"ql-align-center\"><img src=\"https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260426/cd27ea9afb434fd48366294ff70cb28c.png\"></p><p>	眼轴增长与屈光度变化之间并非简单的1mm对应300度的固定关系。何鲜桂教授团队研究显示，ΔSE/ΔAL随年龄增长而增大，且近视人群大于非近视人群。更重要的是，长期随访中，眼轴增加1mm所需时间越长，对应的屈光度增长就越小。这一发现提示，在评估近视进展时，需充分考虑随访周期长度。</p><p>	在近视动态管理中，“安全眼轴增长”界值具有重要意义。何鲜桂教授团队提出，非进展性近视儿童的年眼轴增长阈值约为0.20mm/年（6-10岁），6岁以下可更高，10岁以上则更低。该界值已被《近视管理白皮书（2025）》和国家卫健委《近视防治指南（2024年版）》广泛引用和应用，作为判断进展性近视和评估防控效果的重要依据。临床应用中，每半年复查，眼轴年增长≤0.20mm可视为控制良好，反之则需调整干预方案。</p><p>	值得注意的是，近年来多项研究观察到接受近视干预的儿童出现眼轴回退现象(定义多为1年以上眼轴缩短超过0.05mm或0.1mm)，回退率约12%-59%。年龄、屈光度、眼轴长度等因素与回退比例及幅度相关，眼轴回退有潜力作为评价近视防控效果的预测指标。此外，既往眼轴变化可用于非近视儿童的近视风险分层与随访管理，其预测价值甚至优于基线眼轴或基线屈光度。</p><p>	在技术探索方面，周边眼轴测量成为新的研究方向。通过专用周边眼轴光学生物测量仪，可测量鼻、颞、上、下等方向0-30°范围内的周边眼轴长度，潜在应用于监测眼球形态变化、评估近视进展风险以及评估周边离焦镜片的防控效果。何鲜桂教授团队着力于积极推动眼轴测量的可及性，与厂家合作开发了首台自动化眼轴生物测量仪（AXL-800），成本低于4500美元，并牵头制定了《眼轴长度在近视防控管理中的应用专家共识》（2023），开展全国性调查。</p><p>	最后，何鲜桂教授强调，眼轴为近视动态管理提供了客观、便捷的指标，但应用时需注意个体差异，需结合多次随访或更多变量综合判断。未来研究方向包括覆盖更广年龄段的全国性大样本数据、建立更精确的预测模型和应用工具，以及寻找比眼轴更优的指标。</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/7ca149d307c947cd8e1dd1c9020f8d6a.mp4', '<p>1.&nbsp;Sankaridurg P, He X, Naduvilath T, et al. Comparison of noncycloplegic and cycloplegic autorefraction in categorizing refractive error data in children.&nbsp;<em>Acta Ophthalmol</em>. 2017;95(7):e633-e640. doi:10.1111/aos.13569</p><p>2.&nbsp;Chen J, Liu S, Zhu Z, et al. Axial length changes in progressive and non-progressive myopic children in China.&nbsp;<em>Graefes Arch Clin Exp Ophthalmol</em>. 2023;261(5):1493-1501. doi:10.1007/s00417-022-05901-5</p><p>3.&nbsp;Liu S, He X, Wang J, et al. Association between axial length elongation and spherical equivalent progression in Chinese children and adolescents.&nbsp;<em>Ophthalmic Physiol Opt</em>. 2022;42(5):1133-1140. doi:10.1111/opo.13023</p><p>4.&nbsp;He X, Sankaridurg P, Naduvilath T, et al. Normative data and percentile curves for axial length and axial length/corneal curvature in Chinese children and adolescents aged 4-18 years.&nbsp;<em>Br J Ophthalmol</em>. 2023;107(2):167-175. doi:10.1136/bjophthalmol-2021-319431</p><p>5.&nbsp;Xu S, Ruan Z, Wang Y, et al. Establishment of Myopia Occurrence Prediction Model in Children without Myopia Using Cycloplegic Refraction and Prior Axial Length Change.&nbsp;<em>Ophthalmology</em>. 2025;132(11):1260-1272. doi:10.1016/j.ophtha.2025.06.010</p><p>6.&nbsp;Hu Y, Ding X, Jiang J, et al. Long-Term Axial Length Shortening in Myopic Orthokeratology: Incident Probability, Time Course, and Influencing Factors.&nbsp;<em>Invest Ophthalmol Vis Sci</em>. 2023;64(15):37. doi:10.1167/iovs.64.15.37</p>', '主任医师，教授，上海交通大学和同济大学博导。上海市眼病防治中心近视防控学科带头人、国家卫健委和教育部综合防控近视专家、国际近视研究院亚太学术大使、WHO 2030全球屈光不正行动工作组成员、Ophthalmic Epidemiology 编委、《中国校医》杂志副主编。', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-25/ec4ccaf4325c47018ec554214a2dc630.png', 'ZH');
INSERT INTO `portal_speech` VALUES (22, 'Collection of MCLC talks 2026, Issue 11', 'He Xiangui', 190, 1, NULL, '2026-05-11 17:06:56', NULL, '2026-06-26 12:19:28', 0, 'The Role of Axial Length in Children Myopia Management from Evidence to Practice', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260511/fe10627517a144a3a6880c979a2226c5.jpeg', 'He Xiangui, a chief physician and professor, serves as a doctoral supervisor at both Shanghai Jiao Tong University and Tongji University. She is the leader of the myopia prevention and control discipline at the Shanghai Eye Disease Prevention and Treatment Center, an expert on comprehensive myopia prevention and control appointed by the National Health Commission and the Ministry of Education, an Asia-Pacific academic ambassador of the International Myopia Research Institute, a member of the WHO 2030 Global Action on Refractive Errors Task Force, an editorial board member of Ophthalmic Epidemiology, and the deputy editor-in-chief of the Journal of Chinese School Medicine.', '<p>Professor He Xiangui systematically elaborated on the application value of axial length in the prevention and control management of myopia in children, from cross-sectional screening to longitudinal dynamic management, and from research evidence to clinical practice, providing an operable path guidance for myopia prevention and control work.</p><p>Traditional cross-sectional myopia screening primarily relies on uncorrected visual acuity combined with non-cycloplegic refraction. Although this method can quickly determine the state of myopia, it cannot accurately measure the true refractive power, especially for hyperopic or low to moderate myopic children, where the difference in refraction before and after mydriasis can exceed 50 diopters. Therefore, to achieve longitudinal dynamic management of myopia, alternative indicators to cycloplegia are needed. Professor He Xiangui pointed out that axial length is the ideal indicator. After the age of 3, the cornea is basically stable, and changes in refractive power mainly come from the compensation of the axial length and lens. As the compensatory ability of the lens gradually decreases with age, the allowable \"safe\" increase in axial length should also gradually decrease.</p><p><img src=\"data:image/png;base64,\"></p><p>Professor He Xiangui\'s team has published a series of important studies on axial length in recent years. The team established an axial length growth curve for Chinese children and adolescents aged 4-18, finding that axial length increases with age, with the rate of increase slowing down after the age of 15. For example, at the age of 18, the 5th percentile is 22.79mm, and the 95th percentile is 24.97mm. Through case presentations, the team emphasized the need for comprehensive judgment based on the individual\'s axial length percentile, rather than relying solely on a single measurement value. In addition, AL/CR (Axial Length to Corneal Radius of Curvature ratio) can be used as an indicator of myopia risk in cross-sectional screening. Values exceeding a certain cutoff indicate an increased risk of myopia, but its performance is limited in the 3-5 year-old population.</p><p><img src=\"data:image/png;base64,\"></p><p><img src=\"data:image/png;base64,\"></p><p>The relationship between axial length growth and refractive power change is not a simple fixed relationship where 1mm corresponds to 300 degrees. Research by Professor He Xiangui\'s team shows that ΔSE/ΔAL increases with age, and it is greater in myopic individuals than in non-myopic individuals. More importantly, in long-term follow-up, the longer the time required for an increase of 1mm in axial length, the smaller the corresponding increase in refractive power. This finding suggests that the length of the follow-up period needs to be fully considered when evaluating the progression of myopia.</p><p>In the dynamic management of myopia, the threshold for \"safe axial growth\" holds significant importance. Professor He Xiangui\'s team proposed that the annual axial growth threshold for children with non-progressive myopia is approximately 0.20mm per year (for ages 6-10), which can be higher for children under 6 and lower for those over 10. This threshold has been widely cited and applied in the \"White Paper on Myopia Management (2025)\" and the \"Guidelines for the Prevention and Control of Myopia (2024 Edition)\" issued by the National Health Commission, serving as a crucial basis for determining progressive myopia and evaluating the effectiveness of prevention and control measures. In clinical practice, semi-annual follow-ups are conducted, and an annual axial growth of ≤0.20mm is considered well-controlled; otherwise, the intervention plan needs to be adjusted.</p><p>It is noteworthy that in recent years, multiple studies have observed a regression phenomenon in the axial length of children who underwent myopia intervention (often defined as an axial length reduction of more than 0.05mm or 0.1mm over a period of one year), with a regression rate ranging from approximately 12% to 59%. Factors such as age, refractive power, and axial length are correlated with the proportion and magnitude of regression. Axial regression has the potential to serve as a predictive indicator for evaluating the effectiveness of myopia prevention and control measures. Furthermore, past changes in axial length can be utilized for risk stratification and follow-up management of non-myopic children, and its predictive value may even surpass that of baseline axial length or baseline refractive power.</p><p>In terms of technological exploration, peripheral axial length measurement has emerged as a new research direction. With a dedicated peripheral axial length optical biometer, the peripheral axial length within a range of 0-30° in the nasal, temporal, superior, and inferior directions can be measured, with potential applications in monitoring changes in ocular morphology, assessing the risk of myopia progression, and evaluating the preventive and control effects of peripheral defocus lenses. Professor He Xiangui\'s team is committed to actively promoting the accessibility of axial length measurement. In collaboration with manufacturers, they have developed the first automated axial length biometer (AXL-800), with a cost of less than $4,500. They have also led the development of the \"Expert Consensus on the Application of Axial Length in Myopia Prevention and Control Management\" (2023) and conducted a nationwide survey.</p><p>Finally, Professor He Xiangui emphasized that the axial length provides an objective and convenient indicator for the dynamic management of myopia. However, individual differences should be taken into account during application, and multiple follow-ups or comprehensive judgments based on more variables are necessary. Future research directions include collecting nationwide large-sample data covering a wider age range, establishing more accurate prediction models and application tools, and searching for indicators superior to axial length.</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/5b3cb5094aea46f1a1fc95d6a78e6cdc.mp4', '<p>1. Sankaridurg P, He X, Naduvilath T, et al. Comparison of noncycloplegic and cycloplegic autorefraction in categorizing refractive error data in children. Acta Ophthalmol. 2017;95(7):e633-e640. doi:10.1111/aos.13569</p><p><br></p><p>2. Chen J, Liu S, Zhu Z, et al. Axial length changes in progressive and non-progressive myopic children in China. Graefes Arch Clin Exp Ophthalmol. 2023;261(5):1493-1501. doi:10.1007/s00417-022-05901-5</p><p><br></p><p>3. Liu S, He X, Wang J, et al. Association between axial length elongation and spherical equivalent progression in Chinese children and adolescents. Ophthalmic Physiol Opt. 2022;42(5):1133-1140. doi:10.1111/opo.13023</p><p><br></p><p>4. He X, Sankaridurg P, Naduvilath T, et al. Normative data and percentile curves for axial length and axial length/corneal curvature in Chinese children and adolescents aged 4-18 years. Br J Ophthalmol. 2023;107(2):167-175. doi:10.1136/bjophthalmol-2021-319431</p><p><br></p><p>5. Xu S, Ruan Z, Wang Y, et al. Establishment of Myopia Occurrence Prediction Model in Children without Myopia Using Cycloplegic Refraction and Prior Axial Length Change. Ophthalmology. 2025;132(11):1260-1272. doi:10.1016/j.ophtha.2025.06.010</p><p><br></p><p>6. Hu Y, Ding X, Jiang J, et al. Long-Term Axial Length Shortening in Myopic Orthokeratology: Incident Probability, Time Course, and Influencing Factors. Invest Ophthalmol Vis Sci. 2023;64(15):37. doi:10.1167/iovs.64.15.37</p>', 'Chief physician, professor, doctoral supervisor at Shanghai Jiao Tong University and Tongji University.', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-26/144566376e804dfa8044eb307e1045b8.png', 'EN');
INSERT INTO `portal_speech` VALUES (23, 'Collection of MCLC talks 2026, Issue 10', 'Du Sihe', 191, 1, NULL, '2026-05-11 17:20:20', NULL, '2026-06-26 12:19:51', 0, 'Myopic defocus for myopia control - from present to future', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260511/202d73433a9249d8b18026ff7122c5d8.png', 'Ph.D. Currently serving as a lecturer, chair professor of experimental optometry, visiting chair professor of experimental optometry at the Hong Kong Polytechnic University, founding director and senior consultant of the Vision and Ophthalmology Research Center at the Hong Kong Science and Technology Parks', '<p>Professor Du Sihe systematically reviewed the origin, clinical evidence, and future development direction of myopic defocus as a means of myopia control.</p><p>The basic principle of controlling myopia through myopic defocusing originates from experimental observations of visual guided axial growth. When the retina simultaneously receives two competing signals of myopic defocus and hyperopic defocus, the eyeball selectively responds to the growth inhibiting myopic defocus signal. This discovery has been validated in primate models, laying a theoretical foundation for subsequent optical intervention strategies. Based on this principle, Professor Du Sihe\'s team has successively developed defocused soft contact lenses (DISC) and multi zone forward defocusing lenses (DIMS). DISC lenses can provide a clear central field of view and sustained myopic defocus in front of the retina simultaneously. DIMS lenses can provide sustained myopic defocus signals throughout the entire field of view while correcting refractive errors. A two-year randomized controlled trial showed that compared with the group wearing monocular lenses, the DIMS group reduced myopia progression by 0.44 ± 0.09 D and axial growth by 0.34 ± 0.04 mm. Six year follow-up data showed that children who continued to wear DIMS lenses had an average annual refractive error progression of only -0.15 D and axial progression of only 0.1 mm. Eight year follow-up further confirmed that the longer the wearing time, the more significant the control effect.</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p>The efficacy of DIMS has been validated in different populations. Multiple studies in Europe have shown that DIMS can effectively slow down the progression of myopia in children, and the effect is better in children over 10 years old. A multicenter observational study in the UK shows that the axial control effect of Caucasian and Asian children is comparable. In addition, relevant studies have confirmed that during the COVID-19 pandemic, DIMS still demonstrated stable control effects in the context of high-intensity close range work.</p><p>In addition to DIMS, other optical designs based on defocus principles have also accumulated long-term evidence. Six year research data from MiSight, a bifocal soft contact lens, shows that continuous treatment can reduce axial growth by 0.52 mm compared to monocular lenses, bringing eye growth closer to the level of the emmetropic eye. Five year follow-up of high non spherical microlenses (HAL) showed that myopia progression was reduced by 1.75 D and axial growth was slowed down by 0.72 mm compared to the single lens group; six-year data further confirmed its efficacy. The one-year results of the European CEME study indicate that MyoCare lenses can significantly slow down the progression of myopia.</p><p>To further improve the therapeutic effect, Professor Du Sihe pointed out that combination therapy has become an important direction. European studies have shown that the combination of DIMS and 0.01% atropine is more effective than using DIMS alone. Chinese population studies have also confirmed that DIMS combined with atropine has a stronger control effect.</p><p>Professor Du Sihe stated that defocusing lenses are constantly being optimized. By increasing the volume of non focused light (VoNFL), enhancing the attachment and non sphericity of microlenses, H.A.L.T. MAX technology has shown better axial control effects than H.A.L.T. in a cross study of children in Singapore, and performs better in young children (&lt;8.5 years old). The new generation DIMS (DIMS TED) adopts a triple enhancement design: a smaller central optical zone, higher defocus attachment, and an expanded defocus area. Preliminary 6-month mid-term analysis shows that it is significantly better than the standard DIMS in controlling equivalent spherical lens and axial growth.</p><p><img src=\"data:image/png;base64,\"></p><p>Finally, Professor Du Sihe summarized that optical interventions based on myopic defocusing have been proven to be effective and safe in the long term. Combined medication or phototherapy can further enhance the effect, and the new generation of defocusing lenses is evolving towards higher doses and better design. Although reversing axial growth is still a rare phenomenon, it has begun to show signs. The future goal can be achieved by optimizing defocus dose and joint strategies to reduce the proportion of people with high myopia, providing a more powerful optical weapon for myopia prevention and control.</p><p><img src=\"data:image/png;base64,\"></p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/393fd6fb5ce74d10a6a139468b2d4a1a.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Lam CS, Tang WC, Tse DY, Tang YY, To CH. Defocus Incorporated Soft Contact (DISC) lens slows myopia progression in Hong Kong Chinese schoolchildren: a 2-year randomised clinical trial. <em>Br J Ophthalmol</em>. 2014;98(1):40-45. doi:10.1136/bjophthalmol-2013-303914</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Lam CSY, Tang WC, Tse DY, et al. Defocus Incorporated Multiple Segments (DIMS) spectacle lenses slow myopia progression: a 2-year randomised clinical trial. <em>Br J Ophthalmol</em>. 2020;104(3):363-368. doi:10.1136/bjophthalmol-2018-313739</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Choi KY, Chun RKM, Tang WC, To CH, Lam CS, Chan HH. Evaluation of an Optical Defocus Treatment for Myopia Progression Among Schoolchildren During the COVID-19 Pandemic. <em>JAMA Netw Open</em>. 2022;5(1):e2143781. doi:10.1001/jamanetworkopen.2021.43781</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Li X, Huang Y, Liu C, et al. Myopia control efficacy of spectacle lenses with highly aspherical lenslets: results of a 5-year follow-up study. <em>Eye Vis (Lond)</em>. 2025;12(1):10. doi:10.1186/s40662-025-00427-3</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Alvarez-Peregrina C, Sanchez-Tena MA, Villa-Collar C, et al. Clinical evaluation of MyoCare in Europe (CEME) for myopia management: One-year results. <em>Ophthalmic Physiol Opt</em>. 2025;45(4):1025-1035. doi:10.1111/opo.13517</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Lee CY, Yang SF, Chang YL, Huang JY, Lian IB, Chang CK. The effect of defocus incorporated multiple segment spectacles\' lenses combined with different concentrations atropine for myopia control. <em>Sci Rep</em>. 2025;15(1):12356. doi:10.1038/s41598-025-91089-7</p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Yang Y, Liu S, Gao W, et al. Synergistic effect of defocus incorporated multiple segment glasses and repeated low level red light therapy against myopia progression. <em>Sci Rep</em>. 2025;15(1):3996. doi:10.1038/s41598-024-81363-5</p><p>8.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Nallour Raveendran R, Ong WS, Wong YL, et al. Effect of Increased Power and Asphericity of Highly Aspherical Lenslets on Myopia Control Efficacy: A Contralateral Crossover Study. <em>Transl Vis Sci Technol</em>. 2025;14(11):9. doi:10.1167/tvst.14.11.9</p>', 'Du Sihe, PhD. He currently serves as a lecturer, chair professor of experimental optometry, visiting chair professor of experimental optometry at Hong Kong Polytechnic University, founding director and senior consultant of the Vision and Ophthalmology Research Center at Hong Kong Science Park, dedicated to researching the pathogenesis and pathological mechanisms of myopia and glaucoma', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-26/a217caa1f3f640f495f8eca261f8fd54.png', 'EN');
INSERT INTO `portal_speech` VALUES (24, 'Collection of MCLC talks 2026, Issue 9', 'Debarun Dutta', 192, 1, NULL, '2026-05-11 17:24:25', NULL, '2026-06-26 12:20:12', 0, 'Safety first: Antimicrobial strategies for CL-related infections: recent updates', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260511/e19b8693dc2a4f47b7353fa438f4db98.png', 'Debarun Dutta， PhD, currently serving as the Chair of the Academic Committee of the British Contact Lens Association (BCLA) and Senior Lecturer and Head of Contact Lens Education at Aston University\'s School of Optometry in the UK.', '<p>Professor Debarun Dutta systematically reviewed the infection risks, antibacterial strategies, and the impact of myopia control on the ocular surface of soft contact lenses and corneal reshaping lenses in clinical applications, focusing on the safety issues related to contact lens infections. This provides important guidance for clinical safety practice.</p><p>The incidence rate of contact lens associated keratitis is the core index to measure its safety. Epidemiological data based on multivariate analysis shows that the incidence of contact lens associated microbial keratitis is 13.9 cases per 10000 person years, ranging from 0.9 to 34.5 cases per 10000 person years. There is relatively limited data on overnight wearing of rigid lenses and orthokeratology lenses, and cases of severe microbial keratitis are not common. In terms of children wearing soft contact lenses, research shows that the incidence rate of microbial keratitis is 2.7 cases/10000 person years, and the incidence of symptomatic corneal infiltration is 42 cases/10000 person years. In general, the incidence of adverse events in children is equal to or lower than that in adults.</p><p>The issue of antibiotic resistance has added new challenges to the treatment of contact lens related infections. Data on hospitalized patients in China from 2013 to 2015 showed that approximately 27.45% of patients had antibiotic resistant infections or colonization of resistant bacteria, with single drug resistance accounting for 11.68% and multi drug resistance accounting for 15.77%. This severe background highlights the urgency of developing effective antibacterial strategies in the field of contact lenses.</p><p>Professor Dutta systematically introduced various antibacterial strategies on how to suppress microbial contamination and reduce lens related adverse events. Research has shown that factors affecting bacterial adhesion include lens material, surface characteristics, wearing style, and care plan. In recent years, positive progress has been made in the research and development of antibacterial contact lenses and lens boxes, but further validation is still needed for clinical applications. For corneal reshaping lenses, literature search shows that over 75% of relevant safety studies have been published in the past decade, while nearly half of infection related studies have focused on the past decade, but most of them are studies on refractive correction or myopia control effects, and there is a lack of significant breakthroughs in infection prevention and control. Between 2005 and 2008, there were 29 reports, most of which came from China.</p><p><img src=\"data:image/png;base64,\"></p><p>Professor Dutta pointed out that many early cases of Acanthamoeba keratitis occurred before the market for orthokeratology lenses was regulated, when improper procedures such as rinsing the lenses with tap water were involved. At present, the key to improving safety lies in continuously conducting training for doctors and optometrists, establishing communication networks and mentor guidance mechanisms, standardizing wearing procedures and requiring patients to demonstrate operations on site, supervising the use of recommended nursing solutions, strictly implementing mirror box cleaning and regular replacement, and establishing a 24-hour triage hotline. He emphasized that prohibiting the use of tap water and thoroughly washing and drying hands are the foundation for preventing infections.</p><p><img src=\"data:image/png;base64,\"></p><p>Professor Dutta presented a systematic review on the adverse effects of myopia control on the ocular surface. This review screened over 900 articles from PubMed, Scopus, and Web of Science, and ultimately included 109 clinical trial reports. 51 studies were analyzed, involving a total of 8113 patients. The results showed that corneal reshaping lenses had the greatest impact on the ocular surface, mainly manifested as a decrease in non-invasive tear film rupture time and an increase in the incidence of meibomian gland dysfunction; Soft contact lenses have a moderate impact on ocular surface parameters, mainly manifested as increased corneal staining and tear film instability; Atropine affects tear secretion and stability; Frame glasses have almost no impact. It should be noted that there are significant differences in research methods, and the proportion of commercial funding in research related to soft contact lenses is relatively high, which may introduce bias.</p><p>In summary, Professor Dutta\'s report ultimately points to a core conclusion: the improvement of safety related to contact lenses requires collaborative efforts from multiple dimensions such as antibacterial strategy development, standardized nursing processes, strengthened patient education, and regular follow-up monitoring. Against the backdrop of increasingly severe antibiotic resistance, the strengthening of safety awareness and the popularization of scientific nursing are prerequisites for ensuring the sustainable application of myopia control measures.</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/020d2d4c278a4dfca005cf71ab05f6cc.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Szczotka-Flynn LB, Shovlin JP, Schnider CM, et al. American Academy of Optometry Microbial Keratitis Think Tank. <em>Optom Vis Sci</em>. 2021;98(3):182-198. doi:10.1097/OPX.0000000000001664</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Bullimore MA, Richdale K. Incidence of Corneal Adverse Events in Children Wearing Soft Contact Lenses. <em>Eye Contact Lens</em>. 2023;49(5):204-211. doi:10.1097/ICL.0000000000000976</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Dutta D, Cole N, Willcox M. Factors influencing bacterial adhesion to contact lenses. <em>Mol Vis</em>. 2012;18:14-21.</p><p class=\"ql-align-center\">4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Khan SA, Lee CS. Recent progress and strategies to develop antimicrobial contact lenses and lens cases for different types of microbial keratitis. <em>Acta Biomater</em>. 2020;113:101-118. doi:10.1016/j.actbio.2020.06.039</p>', 'Doctor, currently serving as the Chairman of the Academic Committee of the British Contact Lens Association (BCLA)', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-26/2af43e1ab5584dd2bfc2ef649288a7b8.png', 'EN');
INSERT INTO `portal_speech` VALUES (25, 'Collection of MCLC talks 2026, Issue 8', 'Li Shiming', 193, 1, NULL, '2026-05-11 17:30:59', NULL, '2026-06-26 12:20:31', 0, 'Cry1 Deficiency Triggers Circadian Rhythm Disruption and Drives Myopia Pathogenesis', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260511/2310e3e81dbb4211a7c3568095c862e2.png', 'Li Shiming, Chief Physician, Professor, and Doctoral Supervisor of Ophthalmology at Beijing Tongren Hospital Affiliated to Capital Medical University, is the first National Outstanding Young Physician. He currently serves as the Director of the Medical Optometry Center, Deputy Director of the Department of Ophthalmology and Optometry, and Director of the Joint Teaching and Research Office of Clinical Epidemiology and Evidence Based Medicine. The main research focuses on the mechanisms and prevention measures of refractive errors such as myopia.', '<p>Professor Li Shiming systematically reported the series of research results of his team in the relationship between circadian rhythm and the pathogenesis of myopia, revealing the core role of the biological clock gene Cry1 in the occurrence of myopia.</p><p>Myopia has become a global public health challenge, and it is estimated that the global myopia population will reach 4.758 billion by 2050. Its etiology is influenced by both genetic and environmental factors, among which rhythm related factors such as sleep deprivation and nighttime light are increasingly receiving attention. Professor Li Shiming\'s team found based on the \"Anyang Children\'s Eye Disease Research\" that an increase in sleep time is significantly correlated with a decrease in myopia in children, and this is more pronounced in girls, suggesting that circadian rhythm disorders may be involved in the occurrence of myopia.</p><p><img src=\"data:image/png;base64,\"></p><p>Animal experiments further confirmed this hypothesis. Professor Li Shiming\'s team constructed an abnormal light dark cycle mouse model and found that the mice in the rhythm disorder group exhibited significant myopia drift and axial elongation, loose arrangement of scleral tissue, and reduced proportion of type I collagen fibers. Transcriptomic analysis enriched neurotransmitter signaling pathways such as dopamine and gamma aminobutyric acid, suggesting that rhythm disorders participate in myopia regulation by affecting the retinal neurotransmitter system.</p><p>Among numerous clock genes, Cry1 has attracted special attention from the team. Cry1 gene knockout mice exhibit spontaneous myopia, characterized by refractive drift towards myopia, axial elongation, thinning of sclera thickness, and changes in retinal function. Transcriptome analysis revealed that Cry1 deficiency is involved in pathways such as extracellular matrix remodeling, oxidative stress, and inflammatory activation.</p><p>Mechanism studies have elucidated (unpublished data) that CRY1 protein can bind to and inhibit adenylate cyclase, thereby reducing intracellular cAMP levels. Cry1 deficiency leads to an increase in cAMP content in the sclera, activating the PKA signaling pathway, thereby upregulating the expression of HIF-1 α and α - SMA, promoting fibroblast differentiation, and ultimately causing scleral remodeling and axial elongation. In human embryonic sclera fibroblasts, the expression of CRY1 decreases under low oxygen conditions, while upregulation of CRY1 expression can reverse this process.</p><p>Professor Li Shiming\'s research system has revealed the molecular mechanism by which Cry1 affects scleral remodeling and causes myopia through the cAMP pathway, opening up new targets for myopia prevention and control. Based on this, he proposed a \"rhythm optimization\" strategy: developing Cry1 agonists, optimizing the light environment (increasing outdoor light exposure during the day and reducing artificial light at night), and conducting rhythm gene screening and multidimensional evaluation to achieve individualized warning and precise intervention of myopia risk.</p><p><img src=\"data:image/png;base64,\"></p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/23ffe3596d594fc793d513887f36af81.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Li SM, Ran AR, Kang MT, et al. Effect of Text Messaging Parents of School-Aged Children on Outdoor Time to Control Myopia: A Randomized Clinical Trial. <em>JAMA Pediatr</em>. 2022;176(11):1077-1083. doi:10.1001/jamapediatrics.2022.3542</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wei SF, Li SM, Liu L, et al. Sleep Duration, Bedtime, and Myopia Progression in a 4-Year Follow-up of Chinese Children: The Anyang Childhood Eye Study. <em>Invest Ophthalmol Vis Sci</em>. 2020;61(3):37. doi:10.1167/iovs.61.3.37IF: 4.7 Q1</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Bai WL, Wang MJ, Gan JH, et al. Circadian rhythm disruption induces myopia in mice. <em>Exp Eye Res</em>. 2026;264:110823. doi:10.1016/j.exer.2025.110823</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Doorly R, Ong J, Waisberg E, et al. Applications of generative adversarial networks in the diagnosis, prognosis, and treatment of ophthalmic diseases. <em>Graefes Arch Clin Exp Ophthalmol</em>. 2025;263(8):2117-2134. doi:10.1007/s00417-025-06830-9</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Talamanca L, Gobet C, Naef F. Sex-dimorphic and age-dependent organization of 24-hour gene expression rhythms in humans. <em>Science</em>. 2023;379(6631):478-483. doi:10.1126/science.add0846</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Nickla DL, Totonelly K. Brief light exposure at night disrupts the circadian rhythms in eye growth and choroidal thickness in chicks. <em>Exp Eye Res</em>. 2016;146:189-195. doi:10.1016/j.exer.2016.03.003</p><p class=\"ql-align-center\">7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Allada R, Bass J. Circadian Mechanisms in Medicine. <em>N Engl J Med</em>. 2021;384(6):550-561. doi:10.1056/NEJMra1802337</p>', 'Chief Physician, Professor, and Doctoral Supervisor of Ophthalmology at Beijing Tongren Hospital, Capital Medical University', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-26/724035f0d0d546f89cd9413cf3f3a09e.png', 'EN');
INSERT INTO `portal_speech` VALUES (26, 'Collection of MCLC talks 2026, Issue 7', 'Pauline Kang', 194, 1, NULL, '2026-05-11 17:47:15', NULL, '2026-06-26 12:20:56', 0, 'The Influence of Visual Behaviour on Myopia Control Outcomes', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260511/ea453a61d6ac4f589c12c95681edeeed.png', 'Pauline Kang is an associate professor at the School of Optometry and Vision Sciences, University of New South Wales, Sydney. Her primary research focus is on the prevention and control of myopia in children, as well as the mechanisms underlying its onset and progression.', '<p>Professor Pauline Kang provides a systematic discussion on the impact of visual behavior on myopia control. She pointed out that the risk factors for myopia can be divided into two categories: fixed factors and modifiable factors, among which outdoor light exposure and close range work are the core modifiable factors and are becoming key targets for myopia prevention and control interventions.</p><p>Outdoor light exposure has been extensively studied and proven to have a protective effect on the occurrence of myopia, and may delay the progression of myopia. Professor Pauline Kang emphasized that it is the light itself rather than physical activity that plays a protective role, and its mechanism has not been fully elucidated. Currently, it is believed to be related to dopamine release and circadian rhythm regulation. In terms of measurement methods, subjective questionnaires are susceptible to bias, and objective tools such as wearable sensors are becoming new research standards. She introduced representative works such as ROAM research, Recess Outside Classroom Trial, and Shanghai STORM research, which confirmed the intervention value of outdoor exposure through objective light monitoring. Research suggests that the temporal characteristics, spectral composition, and intensity of light are key parameters that affect the effect. Based on existing evidence, she suggests that in clinical practice, children should be encouraged to have at least 2 hours of outdoor light exposure per day, which can be accumulated in stages and protected against ultraviolet radiation.</p><p><img src=\"data:image/png;base64,\"></p><p>Regarding the association between close work and myopia, Professor Pauline Kang pointed out that a higher level of education is associated with myopia, but the direct link between close work activities such as reading and writing and myopia remains controversial. Some studies suggest that prolonged duration and close visual distance may increase the risk. With the widespread use of digital devices, screen time in children\'s personal entertainment and school education has significantly increased, which may lead to closer visual distance and longer duration of close gaze, thereby altering visual behavior patterns. The behavioral and environmental changes during the COVID-19 pandemic have further exacerbated the progression of myopia.</p><p><img src=\"data:image/png;base64,\"></p><p>Professor Pauline Kang emphasized that accurate measurement of close range eye use behavior also relies on objective tools. She introduced the multi center MENOK study, which used wearable sensor Vivior to continuously record children\'s visual behavior. Preliminary results showed that there may be a positive correlation between close gaze duration and myopia progression, but longer follow-up periods are needed for verification. The study included myopic children who received various intervention plans, including myopia prevention and control lenses, contact lenses, low concentration atropine, and combination therapy, providing rich data for exploring the impact of different treatment backgrounds on visual behavior.</p><p><img src=\"data:image/png;base64,\"></p><p>In summary, Professor Pauline Kang pointed out that a deeper understanding of the impact mechanism of outdoor lighting and close range work on retinal regulatory signals will provide important basis for optimizing myopia control strategies. The application of objective monitoring technology and the promotion of multi center research are driving visual behavior research from empirical judgment to evidence-based practice, opening up new paths for clinical doctors to guide children\'s visual behavior and improve myopia control effectiveness.</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/71725a537ca2493fa15e50da012bbd54.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wu PC, Chen CT, Lin KK, et al. Myopia Prevention and Outdoor Light Intensity in a School-Based Cluster Randomized Trial. <em>Ophthalmology</em>. 2018;125(8):1239-1250. doi:10.1016/j.ophtha.2017.12.011</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Chen J, Wang J, Qi Z, et al. Smartwatch Measures of Outdoor Exposure and Myopia in Children. <em>JAMA Netw Open</em>. 2024;7(8):e2424595. doi:10.1001/jamanetworkopen.2024.24595</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Zong Z, Zhang Y, Qiao J, Tian Y, Xu S. The association between screen time exposure and myopia in children and adolescents: a meta-analysis. <em>BMC Public Health</em>. 2024;24(1):1625. Published 2024 Jun 18. doi:10.1186/s12889-024-19113-5</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ha A, Lee YJ, Lee M, Shim SR, Kim YK. Digital Screen Time and Myopia: A Systematic Review and Dose-Response Meta-Analysis. <em>JAMA Netw Open</em>. 2025;8(2):e2460026. doi:10.1001/jamanetworkopen.2024.60026</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Morgan IG, French AN, Ashby RS, et al. The epidemics of myopia: Aetiology and prevention. <em>Prog Retin Eye Res</em>. 2018;62:134-149. doi:10.1016/j.preteyeres.2017.09.004</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Bhandari KR, Ostrin LA. Validation of the Clouclip and utility in measuring viewing distance in adults. <em>Ophthalmic Physiol Opt</em>. 2020;40(6):801-814. doi:10.1111/opo.12735</p>', 'Associate Professor, School of Optometry and Vision Sciences, University of New South Wales, Sydney', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-26/9e46f105a6d04a449e64bdd3815bb949.png', 'EN');
INSERT INTO `portal_speech` VALUES (27, 'Collection of MCLC talks 2026, Issue 6', 'Lü Fan', 195, 1, NULL, '2026-05-11 18:01:13', NULL, '2026-06-26 12:21:14', 0, 'High Myopia and Myopia Control', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260511/448ef1c8dcfd49afb18eda704019c8ad.png', 'Lv Fan, Professor, Doctoral Supervisor, Director of the Ophthalmology and Optometry Department at Wenzhou Medical University, and Director of the National Clinical Medical Research Center for Eye Diseases.', '<p>Professor Lv Fan systematically explained the core propositions of high myopia research and its profound implications for clinical prevention and control from the perspective of global epidemiological trends.</p><p>Myopia has become a global public health challenge. It is predicted that by 2050, the proportion of people with high myopia worldwide will increase to 10%. This trend has prompted the academic community to re-examine the essential nature of myopia - it is being defined as a \'chronic disease\'. The reason is that myopia has a progressive nature, and high myopia can develop into pathological myopia, causing irreversible visual impairment; The high global prevalence of diseases poses significant public health challenges; Early intervention has been proven to effectively slow down progress. The ultimate goal of myopia prevention and control is to prevent the occurrence of myopia, slow down the progression of myopia, and thus avoid high myopia and its accompanying visual damage.</p><p>At the level of pathogenesis, the occurrence of myopia is the result of the interaction between genetic and environmental factors. GWAS research has identified 284 susceptibility genes for myopia, but can only explain less than 10% of the incidence of myopia in the population. Professor Lv Fan\'s team recently discovered a new early-onset high myopia pathogenic gene BSG through a large sample, providing new clues for understanding the genetic basis of high myopia. It is worth noting that some susceptible genes are significantly enriched in core functional modules, suggesting that these modules may be key links in the interaction between genetic and environmental factors.</p><p>Based on the Wenzhou Million Student Myopia Cohort Study, Professor Lv Fan\'s team presented the distribution of myopia and high myopia incidence rates in different age groups in China, and found that high myopia continues to increase in various grades. This first-class evidence reveals the severe situation of myopia prevention and control, especially the cumulative effect of high myopia, which deserves high vigilance.</p><p><img src=\"data:image/png;base64,\"></p><p>Professor Lv elaborated on the essential differences between high myopia and pathological myopia. Pathological myopia is the main cause of blindness, and its fundus changes include posterior staphyloma, subretinal neovascularization, retinal atrophy and hemorrhage, retinal detachment, etc. As the axial length of the eye increases, the fundus undergoes continuous atrophy and degeneration, resulting in severe impairment of visual function. Meta analysis shows that myopic macular degeneration has become the leading cause of permanent blindness in China, Japan, Denmark, and the Netherlands.</p><p><img src=\"data:image/png;base64,\"></p><p>There is a traceable evolutionary path from normal fundus to pathological myopia: orthorectified or low to moderate myopia manifests as normal fundus; As the axial length of the eye increases, leopard print like fundus appears; Entering the stage of pure high myopia; Further develop into diffuse atrophy; Eventually entering the stage of patchy atrophy, macular atrophy, and its complications. This continuous spectrum suggests that the key issue is to identify which characteristics of myopic individuals will have a high probability of entering the pathological stage, in order to implement precise interventions.</p><p>To reveal the existing functional damage in the stage of simple high myopia, Professor Lv Fan\'s team conducted research using various advanced technologies. Micro field testing has found that patients with simple high myopia have already experienced a decrease in retinal light sensitivity without any complications. The adaptive optics fundus camera shows that in high myopia, compared to emmetropia, the density of cone cells decreases and the distance between cells increases, indicating damage and apoptosis of photoreceptor cells. OCTA research further reveals that when the choroid is severely atrophied in pathological myopia, deep retinal capillaries initiate compensatory blood supply to the outer retina. The choroidal vascular index (CVI) significantly decreases when the ocular axis exceeds a threshold and is negatively correlated with visual acuity, which may serve as a reliable biological indicator for monitoring the progression of pathological myopia.</p><p><img src=\"data:image/png;base64,\"></p><p>Based on the above research evidence, Professor Lv Fan proposed the core strategies for the prevention and control of high myopia: focus on the prophase of myopia, delay the onset and reduce the incidence rate; Low myopia stage, controlling progression and reducing the risk of high myopia; Reduce irreversible vision loss and complications in the stage of high myopia.</p><p>In summary, Professor Lv Fan\'s report ultimately reveals that myopia prevention and control is not simply about degree management, but a chronic disease system engineering that runs through the life cycle. Prevention and control of myopia is a long and arduous task.</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/1127a76a68d84587a1886c180cb2d598.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Holden BA, Fricke TR, Wilson DA, et al. Global Prevalence of Myopia and High Myopia and Temporal Trends from 2000 through 2050. <em>Ophthalmology</em>. 2016;123(5):1036-1042. doi:10.1016/j.ophtha.2016.01.006</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Goodman RA, Posner SF, Huang ES, Parekh AK, Koh HK. Defining and measuring chronic conditions: imperatives for research, policy, program, and practice. <em>Prev Chronic Dis</em>. 2013;10:E66. doi:10.5888/pcd10.120239</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Tedja MS, Wojciechowski R, Hysi PG, et al. Genome-wide association meta-analysis highlights light-induced signaling as a driver for refractive error. <em>Nat Genet</em>. 2018;50(6):834-848. doi:10.1038/s41588-018-0127-7</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Xu L, Zhuang Y, Zhang G, et al. Design, methodology, and baseline of whole city-million scale children and adolescents myopia survey (CAMS) in Wenzhou, China. <em>Eye Vis (Lond)</em>. 2021;8(1):31. doi:10.1186/s40662-021-00255-1</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Haarman AEG, Enthoven CA, Tideman JWL, Tedja MS, Verhoeven VJM, Klaver CCW. The Complications of Myopia: A Review and Meta-Analysis. <em>Invest Ophthalmol Vis Sci</em>. 2020;61(4):49. doi:10.1167/iovs.61.4.49</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Tideman JW, Snabel MC, Tedja MS, et al. Association of Axial Length With Risk of Uncorrectable Visual Impairment for Europeans With Myopia. <em>JAMA Ophthalmol</em>. 2016;134(12):1355-1363. doi:10.1001/jamaophthalmol.2016.4009</p><p class=\"ql-align-center\">7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Haarman AEG, Enthoven CA, Tideman JWL, Tedja MS, Verhoeven VJM, Klaver CCW. The Complications of Myopia: A Review and Meta-Analysis. <em>Invest Ophthalmol Vis Sci</em>. 2020;61(4):49. doi:10.1167/iovs.61.4.49</p><p><br></p>', 'Professor, Doctoral Supervisor, Director of the Ophthalmology and Optometry Department at Wenzhou Medical University', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-26/cbf58c5a236844118396c53d2e36eb52.png', 'EN');
INSERT INTO `portal_speech` VALUES (28, 'Collection of MCLC talks 2026, Issue 5', 'Takahiro Hiraoka', 196, 1, NULL, '2026-05-11 18:04:30', NULL, '2026-06-26 12:21:40', 0, 'Myopia control and microbial keratitis associated with orthokeratology in Japan', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260511/d914ed2359934c36a02b1ae4b3237185.png', 'Professor Takahiro Hiraoka systematically reviewed the research achievements of his team in the field of orthokeratology lenses (OK lenses) over more than a decade, presenting comprehensive data on the excellent control effects and safety management that cannot be ignored in clinical applications, ranging from long-term efficacy, combined treatment, lens deposit risks to the epidemiology of infection complications.', '<p>Professor Takahiro Hiraoka systematically reviewed the research results of his team in the field of orthokeratology lenses (OK lenses) for more than ten years. From long-term efficacy, combination therapy, lens deposition risk to epidemiological data of infection complications, he comprehensively presented the excellent control effect and undeniable safety management of OK lenses in clinical applications.</p><p>Regarding the myopia control effect of OK lenses, Professor Hiraoka presented a ten-year observational study published by his team in 2018. The study compared 104 patients who continuously wore OK lenses with 78 patients who wore soft contact lenses, and the results confirmed that long-term OK lens wearing could effectively inhibit axial elongation. In terms of combination therapy, multiple studies have shown that OK lenses combined with 0.01% atropine can further enhance the effect of axial control. Research has shown that designing a smaller optical zone (5mm) can bring better control effects than designing a larger optical zone (6mm) regarding the impact of treatment zone diameter on axial growth. In addition, the combined application of OK lenses and their value in the treatment of anisometropia have also been validated in clinical studies.</p><p><img src=\"data:image/png;base64,\"></p><p>However, Professor Hiraoka warns that safety related issues with OK lenses must be given high attention. The sediment analysis conducted by the team on 174 OK lenses worn for several years showed that proteins and lipids are prone to deposit on the surface of the OK lenses, especially in the inverted arc area, which increases the amount of biofilm formation by six times. In addition, these sediments significantly increase the adhesion of Acanthamoeba. For stubborn sediment, Professor Hiraoka recommends regular use of powerful detergent containing sodium hypochlorite, which can not only effectively remove sediment and smooth lens surface, but also has a broad-spectrum disinfection effect, killing bacteria, fungi, acanthamoeba and even COVID-19. It has been approved for use as a disinfectant in Europe and China.</p><p><img src=\"data:image/png;base64,\"></p><p>Professor Hiraoka cited multiple international epidemiological research data regarding the incidence of OK lens related microbial keratitis. A study in the United States in 2013 showed an incidence rate of 7.7/10000 person years, while a study in Russia in 2021 showed an incidence rate of 4.9-5.3/10000 person years, which is comparable to the daily throwing soft mirror. The latest multicenter study published by Professor Hiraoka\'s team in 2025 included 1438 OK lens wearers and calculated an infection rate of 5.4/10000 person years, which is similar to the research results in Russia and confirms that the infection rate has shown a downward trend in recent years. Professor Hiraoka also shared four typical cases of infection, including pathogens such as Pseudomonas aeruginosa and Acanthamoeba. All cases ultimately stopped using OK lenses and switched to daily disposal of soft lenses.</p><p><img src=\"data:image/png;base64,\"></p><p>In summary, Professor Takahiro Hiraoka\'s report reveals that the myopia control effect of corneal reshaping surgery has received long-term evidence-based support, but the realization of its clinical value must be based on a safe defense line constructed by scientific nursing.</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/92866eb97af547c7aab4a9f6fddefdc9.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Hiraoka T, Sekine Y, Okamoto F, Mihashi T, Oshika T. Safety and efficacy following 10-years of overnight orthokeratology for myopia control. <em>Ophthalmic Physiol Opt</em>. 2018;38(3):281-289. doi:10.1111/opo.12460</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Kinoshita N, Konno Y, Hamada N, Kanda Y, Shimmura-Tomita M, Kakehashi A. Additive effects of orthokeratology and atropine 0.01% ophthalmic solution in slowing axial elongation in children with myopia: first year results. <em>Jpn J Ophthalmol</em>. 2018;62(5):544-553. doi:10.1007/s10384-018-0608-3</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Guo B, Cheung SW, Kojima R, Cho P. One-year results of the Variation of Orthokeratology Lens Treatment Zone (VOLTZ) Study: a prospective randomised clinical trial. <em>Ophthalmic Physiol Opt</em>. 2021;41(4):702-714. doi:10.1111/opo.12834</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Hiraoka T, Yoshimitsu M, Santodomingo-Rubido J, Kondo H, Oshika T. A novel quantitative evaluation of deposits adhered to worn orthokeratology contact lenses. <em>Jpn J Ophthalmol</em>. 2021;65(6):855-863. doi:10.1007/s10384-021-00873-1</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Bullimore MA, Sinnott LT, Jones-Jordan LA. The risk of microbial keratitis with overnight corneal reshaping lenses. <em>Optom Vis Sci</em>. 2013;90(9):937-944. doi:10.1097/OPX.0b013e31829cac92</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Hiraoka T, Matsumura S, Hori Y, Kamiya K, Miyata K, Oshika T. Incidence of microbial keratitis associated with overnight orthokeratology: a multicenter collaborative study. <em>Jpn J Ophthalmol</em>. 2025;69(1):139-143. doi:10.1007/s10384-024-01137-4</p><p class=\"ql-align-center\">7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Xiong R, Wang W, Tang X, et al. Myopia Control Effect of Repeated Low-Level Red-Light Therapy Combined with Orthokeratology: A Multicenter Randomized Controlled Trial. <em>Ophthalmology</em>. 2024;131(11):1304-1313. doi:10.1016/j.ophtha.2024.05.015</p>', 'Associate Professor, Institute of Ophthalmology, University of Tsukuba', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-26/466b29bbef51481692f1906abed05a01.png', 'EN');
INSERT INTO `portal_speech` VALUES (29, 'Collection of MCLC talks 2026, Issue 3', 'Langis Michaud', 198, 1, NULL, '2026-05-11 18:10:24', NULL, '2026-06-26 12:22:34', 0, 'How to improve myopia control with optical devices : understanding the retinal response to visual signal', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260511/541131c385b1477399bad119a8ba3856.png', 'Professor Langis Michaud\'s main research areas include myopia prevention and control, scleral contact lenses, corneal neuralgia, and anterior segment lesions such as keratoconus. The current director of the Contact Lens Department at the University of Montreal, a senior member of the American Society of Ophthalmology, the British Contact Lens Association, the Society for Scleral Education, the European Society of Ophthalmology, and the International Society for Orthokeratology and Myopia Control.', '<p>Professor Langis Michaud systematically elaborated on the underlying mechanism of retinal regulation of eye growth around the core theme of \"Retinal response to visual signals\", and proposed a practical path for optimizing the myopia prevention and control effect of optical lenses based on this mechanism.</p><p>Eye growth is mainly regulated by the retina, which activates the retina sclera biochemical pathway by analyzing visual signals to drive the process of emmetropization. The sound functioning of the system is key to maintaining a positive state, while the occurrence of myopia is related to partial functional deficiencies. Abnormal focusing in the macular area (similar to form deprivation) and peripheral retinal defocus can both affect refractive development.</p><p><img src=\"data:image/png;base64,\"></p><p>From the perspective of retinal functional differentiation, photoreceptors can achieve functional specialization by responding to different visual stimuli such as light wavelength, object spatial orientation, and motion direction. After transmitting light energy to 15 different subtypes of bipolar cells, they complete the specific extraction and encoding of visual information, and then transmit signals through two core pathways: the light dark pathway is mainly responsible for image processing, while the color vision pathway participates in fuzzy information analysis. The two work together to achieve accurate analysis of image information by the retina.</p><p>The analysis of image information by the retina mainly relies on two dimensions: contrast and spatial frequency. Its sensitive pathway can simultaneously encode light enhancement and attenuation signals, which is the key to perceiving object and spatial contrast, shape, and edge information. Among them, the \"center periphery antagonistic\" receptive field structure of bipolar cells is the basis for identifying contrast and edge information.</p><p>After understanding the theoretical basis mentioned above, Professor Langis Michaud focused on explaining the core correlation between abnormal retinal signal response and the occurrence and progression of myopia, clarifying two key mechanisms:</p><p>1. The bright pathway (ON pathway) and the dark pathway (OFF pathway) have opposite regulatory effects on eye growth: inhibiting the bright pathway or stimulating the dark pathway promotes axial growth. Myopia can be seen to some extent as a functional defect state of the optic pathway. From a genetic perspective, pathological activation of the light/dark pathway is the key driver of high myopia, and its root cause is related to genetic mutations (specific haplotypes) that affect the pigment gene. About 25% of the population carries such mutations, and the risk of high myopia is three times higher than that of the general population.</p><p>2. Chromatic aberration (including longitudinal and transverse chromatic aberration) provides a key signal for the retina to distinguish defocusing properties (positive/negative), which in turn guides the issuance of instructions to \"grow\" or \"stop growing\". However, the sensitivity of myopic eyes to this signal often weakens. In addition, the retina has neural adaptability, which may be an important reason for the plateau effect of all optical intervention methods over time.</p><p><img src=\"data:image/png;base64,\"></p><p>Based on the core mechanisms of retinal signal response and myopia regulation mentioned above, Professor Langis Michaud, combined with clinical research experience, proposes specific strategies for optimizing the myopia prevention and control effect of optical lenses, and clarifies the core principles of optical intervention - by accurately regulating the defocused state of the retina, activating the clear pathway function, improving retinal signal response, and thereby inhibiting abnormal eye growth. The specific content is as follows:</p><p>1. Application principle of lens optical characteristics:</p><p>a) The refractive changes of lenses can alter the size of the target object image, thereby affecting the retinal receptive field response: when stimuli are limited to the central area of the receptive field, the retinal nerve response is enhanced; When the stimulus affects the surrounding area, the response is weakened due to the antagonistic mechanism in the surrounding area; When the stimulation exceeds the peripheral area, there is no significant neural response.</p><p>b) The defocus gradient can interfere with the recognition process of light/dark stimuli and has different effects on the ON and OFF pathways. It can expand the receptive field of the ON pathway and reduce the receptive field of the OFF pathway, explaining the differential effect of defocus on the perception of light and dark stimuli.</p><p>c) It is worth noting that when the size and brightness of the object image remain unchanged, the ON and OFF pathways cannot reliably distinguish between positive and negative defocus, but can accurately transmit signals of changes in defocus degree and object image magnification. This also explains why positive lenses are more effective in correcting myopia compared to negative lenses - magnification is a key factor affecting retinal signal response, better than the influence of defocus sign.</p><p><br></p><p>2. Clinical application standards for optical lenses:</p><p>a) Avoid using monocular lenses, as monocular lenses cannot improve negative spherical aberration of the peripheral retina and vertical defocus of the nasal retina, making it difficult to effectively regulate retinal signal response.</p><p>b) Closely monitor the patient\'s refractive status and adjust the correction plan in a timely manner. If the central vision remains blurry, it can easily lead to form deprivation and accelerate the progression of myopia.</p><p>c) It is strictly prohibited to wear glasses with myopia and undercorrection. When the refractive error changes by more than 0.25D, the lenses should be replaced in a timely manner to ensure that the retina receives clear visual stimulation and avoid signal pathway disorders.</p><p>d) Emphasize wearing optical corrective lenses throughout the day to ensure sustained defocusing stimulation on the retina and maintain stable signal regulation effects.</p><p>e) Positive lenses are preferred among micro lens lenses, as they can amplify the size of visual signals and more easily activate the ON pathway.</p><p>f) Preferred lenses with central far field design can provide higher spherical aberration and larger magnification, which better meets the needs of retinal regulation.</p><p>g) Atropine can enhance the dose effect of defocus and contrast by enlarging the pupil diameter.</p><p>h) For myopic patients who require higher dose effects or different optical stimuli, neural adaptation can occur after the first year of intervention, and strategies need to be adjusted in a timely manner.</p><p><img src=\"data:image/png;base64,\"></p><p>In summary, Professor Langis Michaud\'s report indicates that the optical management of myopia essentially involves transmitting precise regulatory signals to the retina. By deeply understanding the signal processing mechanism of the retina and the role of aberrations, and optimizing the design and application strategies of optical lenses based on this, more accurate and effective myopia control can be achieved in the future.</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/aad45eed0dfb4ee49cf0850f3f63a3a9.mp4', '<p><span style=\"color: black;\">1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wallman J, Winawer J. Homeostasis of eye growth and the question of myopia. </span><em style=\"color: black;\">Neuron</em><span style=\"color: black;\">. 2004;43(4):447-468. doi:10.1016/j.neuron.2004.08.008</span></p><p><span style=\"color: black;\">2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Brown DM, Mazade R, Clarkson-Townsend D, Hogan K, Datta Roy PM, Pardue MT. Candidate pathways for retina to scleral signaling in refractive eye growth. </span><em style=\"color: black;\">Exp Eye Res</em><span style=\"color: black;\">. 2022;219:109071. doi:10.1016/j.exer.2022.109071</span></p><p><span style=\"color: black;\">3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Summers JA, Schaeffel F, Marcos S, Wu H, Tkatchenko AV. Functional integration of eye tissues and refractive eye development: Mechanisms and pathways. </span><em style=\"color: black;\">Exp Eye Res</em><span style=\"color: black;\">. 2021;209:108693. doi:10.1016/j.exer.2021.108693</span></p><p><span style=\"color: black;\">4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Romashchenko D, Rosén R, Lundström L. Peripheral refraction and higher order aberrations. </span><em style=\"color: black;\">Clin Exp Optom</em><span style=\"color: black;\">. 2020;103(1):86-94. doi:10.1111/cxo.12943</span></p><p><span style=\"color: black;\">5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Lundström L, Gustafsson J, Unsbo P. Population distribution of wavefront aberrations in the peripheral human eye. </span><em style=\"color: black;\">J Opt Soc Am A Opt Image Sci Vis</em><span style=\"color: black;\">. 2009;26(10):2192-2198. doi:10.1364/JOSAA.26.002192</span></p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ichinose T, Habib S. ON and OFF Signaling Pathways in the Retina and the Visual System. <em>Front Ophthalmol (Lausanne)</em>. 2022;2:989002. doi:10.3389/fopht.2022.989002</p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Poudel S, Jin J, Rahimi-Nasrabadi H, et al. Contrast Sensitivity of ON and OFF Human Retinal Pathways in Myopia. <em>J Neurosci</em>. 2024;44(3):e1487232023. Published 2024 Jan 17. doi:10.1523/JNEUROSCI.1487-23.2023&nbsp;</p><p>8.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Neitz M, Neitz J. Intermixing the <em>OPN1LW</em> and <em>OPN1MW</em> Genes Disrupts the Exonic Splicing Code Causing an Array of Vision Disorders. <em>Genes (Basel)</em>. 2021;12(8):1180. Published 2021 Jul 29. doi:10.3390/genes12081180</p><p>9.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;https://www.youtube.com/watch?v=4jJS4MnkcWw</p><p>10.&nbsp;&nbsp;&nbsp;https://www.youtube.com/watch?v=4jJS4MnkcWw</p><p>11.&nbsp;&nbsp;&nbsp;Yang Y, Lee D, Gettinger K, et al. Mechanisms Underlying Myopia Progression from Visual Signaling to Metabolic Remodeling in Retina. <em>JMA J</em>. 2025;8(4):1031-1038. doi:10.31662/jmaj.2025-0268</p><p>12.&nbsp;&nbsp;&nbsp;Swiatczak B, Scholl HPN, Schaeffel F. Retinal \"sweet spot\" for myopia treatment. <em>Sci Rep</em>. 2024;14(1):26773. Published 2024 Nov 5. doi:10.1038/s41598-024-78300-x</p><p>13.&nbsp;&nbsp;&nbsp;Neitz J, Neitz M. Diffusion Optics Technology (DOT): A Myopia Control Spectacle Lens Based on Contrast Theory. <em>Transl Vis Sci Technol</em>. 2024;13(10):42. doi:10.1167/tvst.13.10.42</p><p>14.&nbsp;&nbsp;&nbsp;Zheleznyak L, Liu C, Winter S. Chromatic cues for the sign of defocus in the peripheral retina. <em>Biomed Opt Express</em>. 2024;15(9):5098-5114. Published 2024 Aug 8. doi:10.1364/BOE.537268</p><p>15.&nbsp;&nbsp;&nbsp;Gawne TJ, Norton TT. An opponent dual-detector spectral drive model of emmetropization. <em>Vision Res</em>. 2020;173:7-20. doi:10.1016/j.visres.2020.03.011</p><p>16.&nbsp;&nbsp;&nbsp;James Polans, Bart Jaeken, Ryan P McNabb, Lucia Hervella, Pablo Artal, Joseph A Izatt; Wide-field schematic model of the Human Eye with Asymmetrically Tilted and Decentered Lens. <em>Invest. Ophthalmol. Vis. Sci.</em> 2015;56(7 ):6019</p><p>17.&nbsp;&nbsp;&nbsp;Neitz J, Neitz M. Clarification on the understanding of contrast theory in relation to the article \"ON and OFF receptive field processing in the presence of optical scattering\": comment. <em>Biomed Opt Express</em>. 2024;15(2):789-792. doi:10.1364/BOE.504315</p><p class=\"ql-align-center\">18.&nbsp;&nbsp;&nbsp;Pons C, Mazade R, Jin J, Dul MW, Alonso JM. Optical defocus affects differently ON and OFF visual pathways. <em>iScience</em>. 2025;28(6):112500. Published 2025 Apr 22. doi:10.1016/j.isci.2025.112500</p><p><br></p>', 'Head of the Contact Lens Department at the University of Montreal, and a Fellow of the American Academy of Ophthalmology and Optometry', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-26/1d56da07e5fc4f1a9a8dc598e56e7aee.png', 'EN');
INSERT INTO `portal_speech` VALUES (30, 'Collection of MCLC talks 2026, Issue 4', 'Zhou Xingtao', 197, 1, NULL, '2026-05-11 18:21:39', NULL, '2026-06-26 12:21:58', 0, ' AI-empowered Full-life Cycle Eye Health', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260511/7f2e1c80271d4ea287d6e6a893b0c08a.png', 'Zhou Xingtao, Chief Physician, Professor, Doctoral Supervisor, currently serves as the President of the Eye, Ear, Nose and Throat Hospital affiliated with Fudan University, Director of the National Ophthalmology Professional Quality Control Center, Director of the Shanghai Eye and Vision Optics Research Center, and Director of the Shanghai Laser and Naked Eye 3D Visual Health Engineering Technology Research Center.', '<p>Professor Zhou Xingtao systematically demonstrated how he deeply integrates artificial intelligence technology into the full cycle management of myopia prevention and treatment, from cause exploration, early screening, risk warning to surgical planning and efficacy evaluation, constructing a set of intelligent innovation systems that run through \"screening diagnosis treatment prevention\".</p><p>The situation of myopia prevention and control in our country is severe, and the incidence of myopia among teenagers is constantly increasing, showing a trend of younger age, severity, faster development, and deeper severity. Professor Zhou Xingtao\'s team, in collaboration with multiple disciplines, has advanced the prevention and control of myopia to the early stages of the entire life cycle through a large cohort study covering over 2.5 million people. They have revealed a significant correlation between gestational hypertension and the risk of high refractive errors in offspring, suggesting that prevention of high myopia should start from pregnancy. This has innovative and important guiding significance for the prevention and treatment of high myopia.</p><p><img src=\"data:image/png;base64,\"></p><p>In the field of early screening and risk warning, the team has developed multiple AI tools to achieve precise prevention and control. By constructing an AI whole eye refractive model, it is possible to accurately calculate the physiological hyperopia reserve of children without dilated pupils, with an ACC of up to 0.953; At the same time, the myopia risk prediction model established by integrating multi-source data, namely the school myopia screening AI composite machine and cloud refractive file system, can provide personalized warning and prevention and control suggestions. In addition, the team utilized AI imaging technology to achieve automatic quantitative analysis of leopard print density in children\'s fundus, confirming its significant correlation with rapid axial growth, providing a novel non-invasive biomarker for monitoring myopia progression.</p><p><img src=\"data:image/png;base64,\"></p><p>AI technology also plays a core role in the precision of refractive surgery. For ICL implantation surgery, the team utilized big data and machine learning models to analyze 18 feature parameters that affect postoperative arch height and crystal size selection. The established prediction model achieved an accuracy rate of over 82% in ICL size selection. For SMILE surgery, the team innovatively developed an automated algorithm based on MatLab, which can objectively and accurately measure the size and shape of the effective optical zone after surgery, solving the clinical problem of poor repeatability in traditional methods.</p><p>The team is also committed to building a complete domestic \"AI+Ophthalmology\" clinical application ecosystem. The AI corneal reshaping mirror fitting platform developed can assist in OK mirror fitting and improve efficiency; The domestically produced intelligent anterior segment analysis system constructs an early screening model for keratoconus, with diagnostic sensitivity and specificity improved to over 98%; The domestically produced intelligent front-end analysis system - AI assisted ICL personalized design platform has successfully achieved patent conversion and industrialization. These achievements have formed a closed-loop service of \"AI preoperative evaluation surgical planning postoperative follow-up\", which has effectively promoted the upgrading of the domestic ophthalmic equipment and consumables industry.</p><p><img src=\"data:image/png;base64,\"></p><p>In summary, Professor Zhou Xingtao\'s team has deeply integrated artificial intelligence into various aspects of myopia prevention and management throughout the entire cycle, from cause research, early screening, surgical planning to ecological construction. This not only significantly improves the accuracy and efficiency of diagnosis and treatment, but also innovates the model of myopia full cycle management.</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/a74f93e8ccc34f3694251e620668228c.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Li M, Huang C, Yang W, et al. Evaluation of Hypertensive Disorder of Pregnancy and High Refractive Error in Offspring During Childhood and Adolescence. <em>JAMA Netw Open</em>. 2023;6(4):e238694. Published 2023 Apr 3. doi:10.1001/jamanetworkopen</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Chen Z, Gu D, Wang B, et al. Significant myopic shift over time: Sixteen-year trends in overall refraction and age of myopia onset among Chinese children, with a focus on ages 4-6 years. <em>J Glob Health</em>. 2023;13:04144. Published 2023 Nov 9. doi:10.7189/jogh.13.04144</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wei R, Li J, Yang W, et al. ASSOCIATION OF TESSELLATION DENSITY WITH PROGRESSION OF AXIAL LENGTH AND REFRACTION IN CHILDREN: An Artificial Intelligence-Assisted 4-Year Study. <em>Retina</em>. 2024;44(3):527-536. doi:10.1097/IAE.0000000000003991</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wang Y, Wei R, Yang D, et al. Development and validation of a deep learning model to predict axial length from ultra-wide field images. <em>Eye (Lond)</em>. 2024;38(7):1296-1300. doi:10.1038/s41433-023-02885-2</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Shen Y, Wang L, Jian W, et al. Big-data and artificial-intelligence-assisted vault prediction and EVO-ICL size selection for myopia correction. <em>Br J Ophthalmol</em>. 2023;107(2):201-206. doi:10.1136/bjophthalmol-2021-319618</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Huang Y, Ding X, Han T, Fu D, Yu Z, Zhou X. Effective Optical Zone Following Small Incision Lenticule Extraction for Myopia Calculated With Two Novel Methods. <em>J Refract Surg</em>. 2022;38(7):414-421. doi:10.3928/1081597X-20220608-02</p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Yan YN, Wang YX, Xu L, Xu J, Wei WB, Jonas JB. Fundus Tessellation: Prevalence and Associated Factors: The Beijing Eye Study 2011. <em>Ophthalmology</em>. 2015;122(9):1873-1880. doi:10.1016/j.ophtha.2015.05.031</p><p class=\"ql-align-center\">8.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Guo Y, Liu L, Zheng D, et al. Prevalence and Associations of Fundus Tessellation Among Junior Students From Greater Beijing. <em>Invest Ophthalmol Vis Sci</em>. 2019;60(12):4033-4040. doi:10.1167/iovs.19-27382</p>', 'Chief Physician, Professor, Doctoral Supervisor, currently serving as the President of the Eye, Ear, Nose and Throat Hospital affiliated to Fudan University', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-26/e8068cb607c841979374a3f041b1eec6.png', 'EN');
INSERT INTO `portal_speech` VALUES (31, 'MCLC 2026特邀嘉宾演讲集锦 第十二期', '董彦会', 189, 1, NULL, '2026-05-15 07:50:47', NULL, '2026-06-25 17:51:40', 0, '以近视防控为核心的儿童青少年多病共防及群体干预策略', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260515/c9560ecf8b974a37ad349f17b8c4ecdf.png', '董彦会，研究员、博士生导师。现任北京大学儿童青少年卫生研究所副所长、中国疾控中心儿少学校卫生中心副主任、国家疾病预防控制标准委员会学校卫生专业委员会委员兼秘书长、北京预防医学会儿少青专业委员会委员兼秘书长。研究方向为儿童慢性病和常见病的环境和致病机制研究，儿童传染病流行病学研究', '<p>	董彦会教授从公共卫生视角出发，系统阐述了以近视防控为核心、推动儿童青少年多病共防的策略思路与群体干预路径。他指出，儿童青少年健康已上升为全球五大关键优先健康领域之一，与全民健康覆盖、精神健康、气候变化与健康、健康研究并列，凸显了这一人群健康议题的战略重要性。</p><p><img src=\"data:image/png;base64,\"></p><p><br></p><p>	当前中国儿童青少年面临多重健康问题的交织挑战。董彦会教授团队的研究成果显示，近视、肥胖、脊柱弯曲、心理健康等问题在儿童青少年群体中呈现高发与共发趋势，单一疾病的防控策略难以应对复杂的健康现实。因此，从“多病共防”的视角出发，寻找不同健康问题之间的共性影响因素，制定整合式干预策略，成为提升儿童青少年整体健康水平的关键路径。</p><p>	在影响因素层面，董彦会教授团队从个体、家庭、学校三个维度系统分析了儿童青少年健康的相关因素。研究发现，身体活动、户外时间、用眼行为、饮食习惯、睡眠质量等因素不仅与近视相关，也同时影响肥胖、体质健康等多种健康结局。这为以近视为突破口、带动多重健康问题协同干预提供了科学依据。</p><p>	基于上述发现，董彦会教授团队开发了针对儿童常见病多病共防的干预新技术。此外，团队积极推动以近视防控为核心的多部门合作平台建设，整合教育、卫生、体育等资源，探索群体层面的综合干预方案，并积极推动中国儿童多病共防实施策略和政策的出台。《Lancet》于2024年发表的柳叶刀青少年特邀重大报告（第二版）中，团队的研究成果与策略创新被纳入，为全球儿童青少年健康政策制定提供了中国经验。</p><p>	最后，董彦会教授总结，儿童青少年多病共防任重道远。以近视防控为切入点，针对共性影响因素实施群体干预，不仅有助于控制近视的高发态势，更能同步改善肥胖、体质下降等多重健康问题。未来需要进一步深化跨部门协作、推广循证干预策略、完善监测与评价体系，为儿童青少年健康成长构建更加坚实的公共卫生防线。</p><p><img src=\"data:image/png;base64,\"></p>', '', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Dong Y, Wang L, Burgner DP, et al. Infectious diseases in children and adolescents in China: analysis of national surveillance data from 2008 to 2017.&nbsp;<em>BMJ</em>. 2020;369:m1043. Published 2020 Apr 2. doi:10.1136/bmj.m1043</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Dong Y, Jan C, Ma Y, et al. Economic development and the nutritional status of Chinese school-aged children and adolescents from 1995 to 2014: an analysis of five successive national surveys.&nbsp;<em>Lancet Diabetes Endocrinol</em>. 2019;7(4):288-299. doi:10.1016/S2213-8587(19)30075-0</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Dong Y, Chen M, Chen L, et al. Individual-, Family-, and School-Level Ecological Correlates With Physical Fitness Among Chinese School-Aged Children and Adolescents: A National Cross-Sectional Survey in 2014.&nbsp;<em>Front Nutr</em>. 2021;8:684286. Published 2021 Aug 25. doi:10.3389/fnut.2021.684286</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Chen TJ, Dong B, Dong Y, et al. Matching actions to needs: shifting policy responses to the changing health needs of Chinese children and adolescents.&nbsp;<em>Lancet</em>. 2024;403(10438):1808-1820. doi:10.1016/S0140-6736(23)02894-5I</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Chen L, Wang L, Xing Y, et al. Disparity in spectrum of infectious diseases between in-school and out-of-school children, adolescents, and youths in China: findings from a successive national surveillance from 2013 to 2021.&nbsp;<em>Lancet Reg Health West Pac</em>. 2023;38:100811. Published 2023 Jun 7. doi:10.1016/j.lanwpc.2023.100811</p>', '研究员、博士生导师', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-25/2ad477202b104422bb1ddefba0f0c360.png', 'ZH');
INSERT INTO `portal_speech` VALUES (32, 'Collection of MCLC talks 2026, Issue 12', 'Dong Yanhui', 189, 1, NULL, '2026-05-15 09:38:31', NULL, '2026-06-26 12:17:26', 0, 'Co-prevention of Multi-Disease and Population-based Intervention Strategies for Children and Adolescents Centered on Myopia Prevention and Control', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260515/69d211d62b8c4d8a82c0f45eab1a132e.png', 'He/She currently serves as the Deputy Director of the Institute of Child and Adolescent Health at Peking University, the Deputy Director of the School Health Center for Children and Adolescents at the Chinese Center for Disease Control and Prevention, a member and Secretary-General of the School Health Specialty Committee of the National Disease Prevention and Control Standards Committee, and a member and Secretary-General of the Children, Adolescents, and Youth Specialty Committee of the Beijing Preventive Medicine Association. His/Her research interests lie in the study of environmental and pathogenic mechanisms of chronic and common diseases in children, as well as the epidemiology of infectious diseases in children', '<p>Professor Dong Yanhui, from the perspective of public health, systematically expounded on the strategic thinking and group intervention pathways centered on myopia prevention and control, promoting the prevention of multiple diseases among children and adolescents. He pointed out that the health of children and adolescents has risen to one of the five key priority health areas globally, alongside universal health coverage, mental health, climate change and health, and health research, highlighting the strategic importance of this population\'s health issue.</p><p><img src=\"data:image/png;base64,\"></p><p>    Currently, Chinese children and adolescents are facing intertwined challenges posed by multiple health issues. Research findings from Professor Dong Yanhui\'s team indicate that issues such as myopia, obesity, spinal curvature, and mental health problems are prevalent and co-occur among children and adolescents. Preventive and control strategies focusing on a single disease are insufficient to address the complex health realities. Therefore, from the perspective of \"preventing multiple diseases simultaneously\", identifying common influencing factors across different health issues and developing integrated intervention strategies have become key pathways to enhancing the overall health level of children and adolescents.</p><p>At the level of influencing factors, Professor Dong Yanhui\'s team systematically analyzed the relevant factors affecting the health of children and adolescents from three dimensions: individual, family, and school. The study found that factors such as physical activity, outdoor time, eye behavior, dietary habits, and sleep quality are not only related to myopia, but also affect multiple health outcomes such as obesity and physical health. This provides a scientific basis for taking myopia as a breakthrough point to drive collaborative intervention for multiple health issues.</p><p>Based on the aforementioned findings, Professor Dong Yanhui\'s team has developed new intervention technologies aimed at the prevention of multiple common childhood diseases. Furthermore, the team actively promotes the construction of a multi-sector cooperation platform centered on myopia prevention and control, integrating resources from education, health, and sports to explore comprehensive intervention programs at the population level. They also actively advocate for the introduction of implementation strategies and policies for the prevention of multiple common childhood diseases in China. The research achievements and strategic innovations of the team were included in the Lancet Special Report on Adolescents (Second Edition) published in 2024, providing Chinese experience for the formulation of global health policies for children and adolescents.</p><p>Finally, Professor Dong Yanhui summarized that the prevention of multiple diseases in children and adolescents is a long and arduous task. Taking myopia prevention and control as a starting point, implementing group interventions targeting common influencing factors will not only help control the high incidence of myopia but also simultaneously improve multiple health issues such as obesity and physical decline. In the future, it is necessary to further deepen cross-departmental collaboration, promote evidence-based intervention strategies, and improve monitoring and evaluation systems to build a more solid public health defense line for the healthy growth of children and adolescents.</p><p><img src=\"data:image/png;base64,\"></p>', '', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Dong Y, Wang L, Burgner DP, et al. Infectious diseases in children and adolescents in China: analysis of national surveillance data from 2008 to 2017.&nbsp;<em>BMJ</em>. 2020;369:m1043. Published 2020 Apr 2. doi:10.1136/bmj.m1043</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Dong Y, Jan C, Ma Y, et al. Economic development and the nutritional status of Chinese school-aged children and adolescents from 1995 to 2014: an analysis of five successive national surveys.&nbsp;<em>Lancet Diabetes Endocrinol</em>. 2019;7(4):288-299. doi:10.1016/S2213-8587(19)30075-0</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Dong Y, Chen M, Chen L, et al. Individual-, Family-, and School-Level Ecological Correlates With Physical Fitness Among Chinese School-Aged Children and Adolescents: A National Cross-Sectional Survey in 2014.&nbsp;<em>Front Nutr</em>. 2021;8:684286. Published 2021 Aug 25. doi:10.3389/fnut.2021.684286</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Chen TJ, Dong B, Dong Y, et al. Matching actions to needs: shifting policy responses to the changing health needs of Chinese children and adolescents.&nbsp;<em>Lancet</em>. 2024;403(10438):1808-1820. doi:10.1016/S0140-6736(23)02894-5I</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Chen L, Wang L, Xing Y, et al. Disparity in spectrum of infectious diseases between in-school and out-of-school children, adolescents, and youths in China: findings from a successive national surveillance from 2013 to 2021.&nbsp;<em>Lancet Reg Health West Pac</em>. 2023;38:100811. Published 2023 Jun 7. doi:10.1016/j.lanwpc.2023.100811</p>', 'Researcher, doctoral supervisor', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-26/226d1677bce248bcb6ffcf72313d3d46.png', 'EN');
INSERT INTO `portal_speech` VALUES (33, 'MCLC 2026特邀嘉宾演讲集锦 第一期', 'James Wolffsohn', 200, 1, NULL, '2026-05-19 02:07:50', NULL, '2026-06-25 15:14:06', 0, '近视预测计算器', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260519/3216851b03a34ed48fff969de1f7461c.png', 'James Wolffsohn教授现任英国伯明翰阿斯顿大学视光学与听力学学院院长，同时担任泪膜与眼表学会（TFOS）主任。其研究涵盖眼科仪器研发与评估、近视防控、接触镜、人工晶体、老视及泪膜等多个前沿领域，是国际眼视光领域的重要领军人物。', '<p>	在本次MCLC大会上，Wolffsohn教授以其深厚的循证医学理念，系统阐述了近视预测计算器这一前沿工具的科学基础与临床价值。</p><p>Wolffsohn教授首先回顾了“循证实践”在眼科临床中的核心地位，它强调在个体化诊疗中，结合最佳科研证据、医师专业经验与患者意愿，做出审慎、科学的医疗决策。证据等级体系（循证医学金字塔）为此提供了清晰的评估框架。</p><p><img src=\"data:image/png;base64,\"></p><p>	随着近视问题在全球范围内日益严峻，基于循证理念的国际近视研究所（IMI）自2015年成立以来，持续推动相关指南与白皮书的更新与普及。其在线白皮书平台（<a href=\"https://myopiainstitute.org/imi-white-papers-clinical-summaries/\" rel=\"noopener noreferrer\" target=\"_blank\">https://myopiainstitute.org/imi-white-papers-clinical-summaries/</a>）提供多语言版本，已成为全球眼科工作者获取权威近视防控资源的重要窗口。</p><p><img src=\"data:image/png;base64,\"></p><p>	一个关键问题常被提出：使用近视干预措施后，若眼轴仍在增长，这属于正常生理发育，还是干预效果不足？Wolffsohn教授指出，理解人眼从远视向正视发展的自然过程，是正确评估干预效果的基础。</p><p>	他强调，解答这一问题的前提，是精确预测近视的发展轨迹。多项研究已明确儿童近视的高风险指标，例如6岁儿童若屈光度 ≤ +0.75 D且&gt;-0.50 D，即具有显著近视倾向。年龄、基线屈光度、父母近视史、高AC/A比、眼轴过长及周边屈光状态等，均为重要预测因素。如父母一方近视，风险增加约1.4倍；双方近视，风险升至约2.3倍；6岁儿童若眼轴长度&gt;23.07mm且至少一方父母近视，其16岁前发生近视的风险可增加6.3倍。</p><p>	为整合这些循证参数，Wolffsohn教授重点介绍了布莱恩·霍顿视觉研究院（BHVI）发布的第二代在线近视计算器（https://bhvi.org/）。该工具能基于个体数据，模拟不同防控手段的长期效果。例如：一名6岁、屈光度为-0.50D的女孩，若无干预，至17岁时屈光度可能达-6.16D；若采用低浓度阿托品干预，则预计可降至-3.87D，延缓进展约37%。此外，该平台还可评估眼轴增长趋势及相关风险因素，为临床决策与患者教育提供直观、个性化的参考。</p><p><img src=\"data:image/png;base64,\"></p><p>	此外，教授也简要列举了其他国际上可用的近视预测与管理在线工具，如Myopia care（https://www.myopiacare.org/），CooperVision（https://coopervision.com/），Myopia Management and Orthokeratology Society（<a href=\"https://www.okmm.md/en/myopia-calculator/%EF%BC%89%EF%BC%8COcumetra%EF%BC%88https:/ocumetra.com/%EF%BC%89%EF%BC%8CPreMO%E5%8F%8AMyopiaProfile\" rel=\"noopener noreferrer\" target=\"_blank\">https://www.okmm.md/en/myopia-calculator/），Ocumetra（https://ocumetra.com/），PreMO及MyopiaProfile</a>（https://www.myopiaprofile.com/）等平台，为从业者提供了多样化的辅助评估选择。</p><p>综上，Wolffsohn教授的分享系统梳理了近视预测的循证依据，并引入实用化的在线计算工具，将科研数据转化为临床助力，为推进近视精准防控提供了重要思路与路径。</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/97b5021232ff4de4ad19ffdc353bfed2.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Flitcroft DI, He M, Jonas JB, et al. IMI - Defining and Classifying Myopia: A Proposed Set of Standards for Clinical and Epidemiologic Studies. <em>Invest Ophthalmol Vis Sci</em>. 2019;60(3):M20-M30. doi:10.1167/iovs.18-25957&nbsp;</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Zadnik K, Sinnott LT, Cotter SA, et al. Prediction of Juvenile-Onset Myopia. <em>JAMA Ophthalmol</em>. 2015;133(6):683-689. doi:10.1001/jamaophthalmol.2015.0471&nbsp;</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;McCullough SJ, O\'Donoghue L, Saunders KJ. Six Year Refractive Change among White Children and Young Adults: Evidence for Significant Increase in Myopia among White UK Children. <em>PLoS One</em>. 2016;11(1):e0146332. doi:10.1371/journal.pone.0146332</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;在线白皮书平台：<a href=\"https://myopiainstitute.org/imi-white-papers-clinical-summaries/\" rel=\"noopener noreferrer\" target=\"_blank\">https://myopiainstitute.org/imi-white-papers-clinical-summaries/</a></p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;BHVI：https://bhvi.org/</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Myopia care：<a href=\"https://www.myopiacare.org/\" rel=\"noopener noreferrer\" target=\"_blank\">https://www.myopiacare.org/</a></p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;CooperVision：<a href=\"https://coopervision.com/\" rel=\"noopener noreferrer\" target=\"_blank\">https://coopervision.com/</a></p><p>8.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Myopia Management and Orthokeratology Society：https://www.okmm.md/en/myopia-calculator/&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p><p>9.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ocumetra：https://ocumetra.com</p><p>10.&nbsp;&nbsp;MyopiaProfile：https://www.myopiaprofile.com/</p>', '英国伯明翰阿斯顿大学视光学与听力学学院院长，同时担任泪膜与眼表学会（TFOS）主任', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-25/adcd5edd15a54631b7bec326d70bee82.png', 'ZH');
INSERT INTO `portal_speech` VALUES (34, 'MCLC 2026特邀嘉宾演讲集锦 第二期', '陈志', 199, 1, NULL, '2026-05-19 02:13:12', NULL, '2026-06-25 15:13:26', 0, '点扩散光学设计（DOT）眼镜用于中国儿童近视控制的多中心随机对照试验——2年结果', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/20260519/9ea4f85cc5094f3cab04d4214d3db940.png', '陈志，副主任医师，副教授，硕士生导师，现任复旦大学附属眼耳鼻喉科医院接触镜和近视防控中心主任。', '<p>	陈志教授报告了一项关于点扩散光学设计（DOT）镜片用于中国儿童近视控制的多中心随机对照试验（RCT）的2年研究成果。</p><p>	近视已成为全球重大公共卫生挑战。2025年IMI近视管理白皮书指出，特殊光学镜片已广泛应用于儿童青少年近视防控，其疗效得到广泛验证。研究显示，视网膜对比度信号升高与近视进展相关，而DOT镜片通过特殊点扩散光学设计调节视网膜对比度，模拟更自然的视觉信号，从而抑制眼轴增长。该设计已在北美CYPRESS研究中证实有效——这项覆盖美国和加拿大14个中心、纳入256名6-10岁近视儿童的4年前瞻性RCT表明，DOT镜片能显著延缓近视进展与眼轴增长，且安全性良好。</p><p>	然而陈志教授指出，亚洲人与白种人的眼球发育轨迹存在差异，DOT镜片在亚洲儿童中的防控效果尚未明确，因此在中国人群中进行疗效评估尤为必要。</p><p><img src=\"data:image/png;base64,\"></p><p>	为此，复旦大学附属眼耳鼻喉科医院携手爱尔眼科医院、天津市眼科医院、四川大学华西医院及中山大学中山眼科中心，共同开展了一项前瞻性、随机、对照、观察者单盲的多中心临床试验。研究覆盖中国东、南、西、北及中部五大区域，共纳入191名6-13岁儿童，按2：1比例随机分配至DOT组与单光镜片（SVL）组，随访24个月。主要终点为2年眼轴变化量，次要终点为6、12、18、24个月时的等效球镜变化量与眼轴变化量。</p><p><img src=\"data:image/png;base64,\"></p><p>	结果显示，两组基线特征无显著差异，具备可比性。陈志教授已在2024年国际近视眼大会（IMC）上汇报了该研究的12个月结果：DOT镜片可使绝对眼轴增长量每年减少0.26mm。分层分析显示，6-7岁、8-10岁、11-13岁各年龄段儿童均能从DOT配戴中获益。2年数据进一步表明，其控制效果未随时间减弱。</p><p><img src=\"data:image/png;base64,\"></p><p>	此外，他表示，DOT镜片的防控效果与DIMS、HAL等设计相当甚至略优，且其所纳入的儿童年龄更小、防控难度更高。配戴初期儿童可能需要数天适应，但一周后其适应性与普通单光镜片无异。</p><p>	综上，陈志教授的研究表明在中国人群中，DOT镜片相较于标准单光镜片可显著减缓眼轴增长和近视进展，该结果与北美的研究一致，支持视网膜对比度信号降低可以减缓儿童近视进展的假说，为国内近视光学防控提供了新的循证选择。</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/a7ee59b3e57c4a068f43cb6a4a909999.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Rappon J, Chung C, Young G, et al. Control of myopia using diffusion optics spectacle lenses: 12-month results of a randomised controlled, efficacy and safety study (CYPRESS). <em>Br J Ophthalmol</em>. 2023;107(11):1709-1715. doi:10.1136/bjo-2021-321005</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Hariton E, Locascio JJ. Randomised controlled trials - the gold standard for effectiveness research: Study design: randomised controlled trials. <em>BJOG</em>. 2018;125(13):1716. doi:10.1111/1471-0528.15199 </p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Saw SM, Chua WH, Gazzard G, Koh D, Tan DT, Stone RA. Eye growth changes in myopic children in Singapore. <em>Br J Ophthalmol</em>. 2005;89(11):1489-1494. doi:10.1136/bjo.2005.071118</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Rappon J, Chung C, Young G, et al. Control of myopia using diffusion optics spectacle lenses: 12-month results of a randomised controlled, efficacy and safety study (CYPRESS). <em>Br J Ophthalmol</em>. 2023;107(11):1709-1715. doi:10.1136/bjo-2021-321005 </p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Laughton D, Hill JS, McParland M, et al. Control of myopia using diffusion optics spectacle lenses: 4-year results of a multicentre randomised controlled, efficacy and safety study (CYPRESS). <em>BMJ Open Ophthalmol</em>. 2024;9(1):e001790. doi:10.1136/bmjophth-2024-001790 </p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Hariton E, Locascio JJ. Randomised controlled trials - the gold standard for effectiveness research: Study design: randomised controlled trials. <em>BJOG</em>. 2018;125(13):1716. doi:10.1111/1471-0528.15199 </p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Neitz M, Wagner-Schuman M, Rowlan JS, Kuchenbecker JA, Neitz J. Insight from <em>OPN1LW</em> Gene Haplotypes into the Cause and Prevention of Myopia. <em>Genes (Basel)</em>. 2022;13(6):942. doi:10.3390/genes13060942</p><p>8.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Bao J, Huang Y, Li X, et al. Spectacle Lenses With Aspherical Lenslets for Myopia Control vs Single-Vision Spectacle Lenses: A Randomized Clinical Trial. <em>JAMA Ophthalmol</em>. 2022;140(5):472-478. doi:10.1001/jamaophthalmol.2022.0401 </p><p>9.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Lam CSY, Tang WC, Tse DY, et al. Defocus Incorporated Multiple Segments (DIMS) spectacle lenses slow myopia progression: a 2-year randomised clinical trial. <em>Br J Ophthalmol</em>. 2020;104(3):363-368. doi:10.1136/bjophthalmol-2018-313739</p><p>10.&nbsp;&nbsp;McCullough SJ, O\'Donoghue L, Saunders KJ. Six Year Refractive Change among White Children and Young Adults: Evidence for Significant Increase in Myopia among White UK Children. <em>PLoS One</em>. 2016;11(1):e0146332. doi:10.1371/journal.pone.0146332</p>', '副主任医师，副教授，硕士生导师，现任复旦大学附属眼耳鼻喉科医院接触镜和近视防控中心主任。', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-25/acfa13d7afc843729b0bbeeb890819fe.png', 'ZH');
INSERT INTO `portal_speech` VALUES (35, 'Collection of MCLC talks 2026, Issue 2', 'Chen Zhi', 199, 1, NULL, '2026-05-19 15:23:53', NULL, '2026-06-26 12:23:14', 0, 'Multicenter RCT of spectacles with diffusion optics technology (DOT) for myopia control in Chinese children — 2 year results', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/9e74a22a4ad14e1cbf780942d8e69c20.png', 'Chen Zhi, Deputy Chief Physician, Associate Professor, Master\'s Supervisor, currently serves as the Director of the Contact Lens and Myopia Prevention and Control Center at Fudan University Affiliated Eye, Ear, Nose and Throat Hospital.', '<p>Professor Chen Zhi reported the results of a 2-year multicenter randomized controlled trial (RCT) on the use of point diffusion optical design (DOT) lenses for myopia control in Chinese children.</p><p>Myopia has become a major global public health challenge. The 2025 IMI Myopia Management White Paper states that special optical lenses have been widely used for myopia prevention and control in children and adolescents, and their efficacy has been widely verified. Research has shown that an increase in retinal contrast signal is associated with the progression of myopia, and DOT lenses adjust retinal contrast through a special point diffusion optical design, simulating a more natural visual signal and thereby suppressing axial growth. This design has been proven effective in the North American CYPRESS study - a 4-year prospective RCT covering 14 centers in the United States and Canada, including 256 myopic children aged 6-10 years, showed that DOT lenses can significantly delay myopia progression and axial growth, and have good safety.</p><p>However, Professor Chen Zhi pointed out that there are differences in eye development trajectories between Asians and Caucasians, and the prevention and control effect of DOT lenses in Asian children is not yet clear. Therefore, it is particularly necessary to conduct efficacy evaluation in the Chinese population.</p><p><img src=\"data:image/png;base64,\"></p><p>To this end, Fudan University Affiliated Eye, Ear, Nose and Throat Hospital, in collaboration with Aier Eye Hospital, Tianjin Eye Hospital, West China Hospital of Sichuan University, and Zhongshan Eye Center of Sun Yat sen University, conducted a prospective, randomized, controlled, single blinded multicenter clinical trial. The study covers five major regions in eastern, southern, western, northern, and central China. A total of 191 children aged 6-13 were randomly assigned to the DOT group and the single lens (SVL) group in a 2:1 ratio, and followed up for 24 months. The primary endpoint is the 2-year axial change, and the secondary endpoints are the equivalent spherical lens change and axial change at 6, 12, 18, and 24 months.</p><p><img src=\"data:image/png;base64,\"></p><p>The results showed that there was no significant difference in baseline characteristics between the two groups, indicating comparability. Professor Chen Zhi has reported the 12-month results of this study at the 2024 International Myopia Conference (IMC): DOT lenses can reduce absolute axial growth by 0.26mm per year. Stratified analysis shows that children aged 6-7, 8-10, and 11-13 can benefit from wearing DOT lenses. The 2-year data further indicates that its control effect has not weakened over time.</p><p><img src=\"data:image/png;base64,\"></p><p>In addition, he stated that the prevention and control effect of DOT lenses is comparable or even slightly better than that of DIMS, HAL and other designs, and the children included in them are younger and the difficulty of prevention and control is higher. Children may need several days to adapt to wearing them in the early stages, but after one week, their adaptability is no different from that of ordinary single lens lenses.</p><p>In summary, Professor Chen Zhi\'s research shows that in the Chinese population, DOT lenses can significantly slow down axial growth and myopia progression compared to standard single lens lenses. This result is consistent with research in North America and supports the hypothesis that reduced retinal contrast signals can slow down myopia progression in children, providing a new evidence-based choice for optical prevention and control of myopia in China.</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/140476b9580c4e4aafa7d1102040c75b.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Rappon J, Chung C, Young G, et al. Control of myopia using diffusion optics spectacle lenses: 12-month results of a randomised controlled, efficacy and safety study (CYPRESS). <em>Br J Ophthalmol</em>. 2023;107(11):1709-1715. doi:10.1136/bjo-2021-321005</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Hariton E, Locascio JJ. Randomised controlled trials - the gold standard for effectiveness research: Study design: randomised controlled trials. <em>BJOG</em>. 2018;125(13):1716. doi:10.1111/1471-0528.15199 </p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Saw SM, Chua WH, Gazzard G, Koh D, Tan DT, Stone RA. Eye growth changes in myopic children in Singapore. <em>Br J Ophthalmol</em>. 2005;89(11):1489-1494. doi:10.1136/bjo.2005.071118</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Rappon J, Chung C, Young G, et al. Control of myopia using diffusion optics spectacle lenses: 12-month results of a randomised controlled, efficacy and safety study (CYPRESS). <em>Br J Ophthalmol</em>. 2023;107(11):1709-1715. doi:10.1136/bjo-2021-321005 </p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Laughton D, Hill JS, McParland M, et al. Control of myopia using diffusion optics spectacle lenses: 4-year results of a multicentre randomised controlled, efficacy and safety study (CYPRESS). <em>BMJ Open Ophthalmol</em>. 2024;9(1):e001790. doi:10.1136/bmjophth-2024-001790 </p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Hariton E, Locascio JJ. Randomised controlled trials - the gold standard for effectiveness research: Study design: randomised controlled trials. <em>BJOG</em>. 2018;125(13):1716. doi:10.1111/1471-0528.15199 </p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Neitz M, Wagner-Schuman M, Rowlan JS, Kuchenbecker JA, Neitz J. Insight from <em>OPN1LW</em> Gene Haplotypes into the Cause and Prevention of Myopia. <em>Genes (Basel)</em>. 2022;13(6):942. doi:10.3390/genes13060942</p><p>8.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Bao J, Huang Y, Li X, et al. Spectacle Lenses With Aspherical Lenslets for Myopia Control vs Single-Vision Spectacle Lenses: A Randomized Clinical Trial. <em>JAMA Ophthalmol</em>. 2022;140(5):472-478. doi:10.1001/jamaophthalmol.2022.0401 </p><p>9.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Lam CSY, Tang WC, Tse DY, et al. Defocus Incorporated Multiple Segments (DIMS) spectacle lenses slow myopia progression: a 2-year randomised clinical trial. <em>Br J Ophthalmol</em>. 2020;104(3):363-368. doi:10.1136/bjophthalmol-2018-313739</p><p>10.&nbsp;&nbsp;McCullough SJ, O\'Donoghue L, Saunders KJ. Six Year Refractive Change among White Children and Young Adults: Evidence for Significant Increase in Myopia among White UK Children. <em>PLoS One</em>. 2016;11(1):e0146332. doi:10.1371/journal.pone.0146332</p>', 'Deputy Chief Physician, Associate Professor, Master\'s Supervisor', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-26/8390aa757a2c4c2d8363f54c5bbd3b4b.png', 'EN');
INSERT INTO `portal_speech` VALUES (36, 'Collection of MCLC talks 2026, Issue 1', 'James Wolffsohn', 200, 1, NULL, '2026-05-19 15:31:25', NULL, '2026-06-26 12:23:39', 0, 'Myopia Calculators', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/0ca6ae0172834c5cbe952267fbee7e0a.png', 'Professor James Wolffsohn is currently the Dean of the School of Optometry and Audiology at Aston University in Birmingham, UK, and also serves as the Director of the Tear Film and Ocular Surface Society (TFOS). His research covers multiple cutting-edge fields such as ophthalmic instrument development and evaluation, myopia prevention and control, contact lenses, artificial lenses, presbyopia, and tear film, making him an important leader in the international field of optometry.', '<p>At the MCLC conference, Professor Wolffsohn, with his profound evidence-based medicine philosophy, systematically elaborated on the scientific basis and clinical value of the myopia prediction calculator, a cutting-edge tool.</p><p>Professor Wolffsohn first reviewed the core position of \"evidence-based practice\" in ophthalmic clinical practice, emphasizing the use of the best scientific research evidence, physician professional experience, and patient willingness in individualized diagnosis and treatment to make prudent and scientific medical decisions. The Evidence Level System (Evidence Based Medicine Pyramid) provides a clear evaluation framework for this.</p><p><img src=\"data:image/png;base64,\"></p><p>With the increasingly severe myopia problem worldwide, the International Myopia Institute (IMI) based on evidence-based principles has been continuously promoting the updating and popularization of relevant guidelines and white papers since its establishment in 2015. Its online white paper platform（ https://myopiainstitute.org/imi-white-papers-clinical-summaries/ ）Providing multilingual versions has become an important window for global ophthalmologists to access authoritative myopia prevention and control resources.</p><p><img src=\"data:image/png;base64,\"></p><p>A key question is often raised: if the axial length of the eye continues to grow after using myopia intervention measures, is this considered normal physiological development or is the intervention effect insufficient? Professor Wolffsohn pointed out that understanding the natural process of human eye development from farsightedness to orthodoxy is the basis for correctly evaluating the effectiveness of interventions.</p><p>He emphasized that the prerequisite for answering this question is to accurately predict the development trajectory of myopia. Multiple studies have identified high-risk indicators for myopia in children, such as a 6-year-old child with a refractive error of ≤+0.75 D and&gt;-0.50 D, indicating a significant tendency towards myopia. Age, baseline refractive error, parental history of myopia, high AC/A ratio, axial length, and peripheral refractive status are all important predictive factors. If one parent is nearsighted, the risk increases by about 1.4 times; Both parties have myopia, and the risk increases by about 2.3 times; If the axial length of a 6-year-old child is greater than 23.07mm and at least one parent is myopic, the risk of developing myopia before the age of 16 can increase by 6.3 times.</p><p>To integrate these evidence-based parameters, Professor Wolffsohn highlighted the second-generation online myopia calculator released by the Brian Horton Institute of Vision (BHVI)（ https://bhvi.org/ ）. This tool can simulate the long-term effects of different prevention and control measures based on individual data. For example, a 6-year-old girl with a refractive error of -0.50D may have a refractive error of -6.16D by the age of 17 without intervention; if low concentration atropine intervention is used, it is expected to decrease to -3.87D, delaying progression by about 37%. In addition, the platform can also evaluate the trend of axial growth and related risk factors, providing intuitive and personalized references for clinical decision-making and patient education.</p><p><img src=\"data:image/png;base64,\"></p><p>In addition, the professor also briefly listed other internationally available online tools for myopia prediction and management, such as Myopia care（ https://www.myopiacare.org/ ）， CooperVision（ https://coopervision.com/ ）， Myopia Management and Orthokeratology Society（ https://www.okmm.md/en/myopia-calculator/ ）， Ocumetra（ https://ocumetra.com/ ）PreMO and MyopiaProfile（ https://www.myopiaprofile.com/ ）The platform provides practitioners with diverse auxiliary evaluation options.</p><p>In summary, Professor Wolffsohn\'s sharing system has sorted out the evidence-based basis for myopia prediction and introduced practical online computing tools to transform scientific research data into clinical assistance, providing important ideas and paths for promoting precise prevention and control of myopia.</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/386cb233f0b44911bd4859780bc83272.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Flitcroft DI, He M, Jonas JB, et al. IMI - Defining and Classifying Myopia: A Proposed Set of Standards for Clinical and Epidemiologic Studies. <em>Invest Ophthalmol Vis Sci</em>. 2019;60(3):M20-M30. doi:10.1167/iovs.18-25957&nbsp;</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Zadnik K, Sinnott LT, Cotter SA, et al. Prediction of Juvenile-Onset Myopia. <em>JAMA Ophthalmol</em>. 2015;133(6):683-689. doi:10.1001/jamaophthalmol.2015.0471&nbsp;</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;McCullough SJ, O\'Donoghue L, Saunders KJ. Six Year Refractive Change among White Children and Young Adults: Evidence for Significant Increase in Myopia among White UK Children. <em>PLoS One</em>. 2016;11(1):e0146332. doi:10.1371/journal.pone.0146332</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;在线白皮书平台：<a href=\"https://myopiainstitute.org/imi-white-papers-clinical-summaries/\" rel=\"noopener noreferrer\" target=\"_blank\">https://myopiainstitute.org/imi-white-papers-clinical-summaries/</a></p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;BHVI：https://bhvi.org/</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Myopia care：<a href=\"https://www.myopiacare.org/\" rel=\"noopener noreferrer\" target=\"_blank\">https://www.myopiacare.org/</a></p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;CooperVision：<a href=\"https://coopervision.com/\" rel=\"noopener noreferrer\" target=\"_blank\">https://coopervision.com/</a></p><p>8.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Myopia Management and Orthokeratology Society：https://www.okmm.md/en/myopia-calculator/&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p><p>9.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ocumetra：https://ocumetra.com</p><p>10.&nbsp;&nbsp;MyopiaProfile：https://www.myopiaprofile.com/</p>', 'He currently serves as the Dean of the School of Optometry and Audiology at Aston University, Birmingham, UK, and concurrently holds the position of Director of the Tear Film and Ocular Surface Society (TFOS)', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-26/a90541544b13402e8556795161a2ea75.png', 'EN');
INSERT INTO `portal_speech` VALUES (37, '333', '111', 0, 1, NULL, '2026-05-19 16:52:21', NULL, '2026-05-19 16:52:34', 1, '444', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/1478092ed5e94f51980305672f59f37f.png', '5555', '<p>66666</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/1d0c9d3135874163b1e7795eb490eb4e.mp4', '<p>7777777777</p>', '222', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/4c86bdd4f2404fc38e93e1b6987f1bc1.png', 'ZH');
INSERT INTO `portal_speech` VALUES (38, '333', '111', 0, 1, NULL, '2026-05-19 16:52:24', NULL, '2026-05-19 17:13:21', 1, '444', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/1478092ed5e94f51980305672f59f37f.png', '5555', '<p>66666</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/1d0c9d3135874163b1e7795eb490eb4e.mp4', '<p>7777777777</p>', '222', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-05-19/4c86bdd4f2404fc38e93e1b6987f1bc1.png', 'ZH');
INSERT INTO `portal_speech` VALUES (39, 'MCLC 2026特邀嘉宾演讲集锦 第十三期', 'Steve Vincent', 188, 1, NULL, '2026-06-03 04:13:07', NULL, '2026-06-25 17:50:55', 0, '巩膜镜配戴过程中的泪液交换', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-03/1d55dcc376754cf0b1e1616663f9ea51.png', 'Steve Vincent，教授，澳大利亚昆士兰科技大学视觉与眼科研究中心主任，美国视光学学会、英国接触镜协会、巩膜镜教育学会、澳大利亚视光学院及高等教育学会会士，四川大学华西医学中心访问教授，《Contact Lens and Anterior Eye》期刊副主编。研究方向聚焦视觉光学、近视与特殊接触镜领域。', '<p>	Steve Vincent教授系统探讨了巩膜镜配戴过程中泪液交换的机制与临床意义，并展示了其团队通过改良镜片设计促进泪液交换、减轻角膜水肿的最新研究成果。</p><p>	巩膜镜配戴面临的核心挑战之一是角膜氧供。角膜所需氧气主要来源于空气，充足的氧供对于维持角膜代谢、透明度、伤口愈合及防御功能至关重要。然而，巩膜镜本身具有一定厚度和有限的透氧性（Dk值要求100以上），镜片与角膜之间的镜下液体层同样存在氧气传输屏障。因此，泪液中溶解氧成为角膜供氧的重要补充。当角膜缺氧时，角膜基质和上皮层可出现组织水肿、透明度下降影响视力、长期基质软化、角膜新生血管以及潜在的角膜移植失败等一系列并发症。</p><p><img src=\"data:image/png;base64,\"></p><p>	为精准评估巩膜镜诱导的角膜水肿，Steve Vincent教授团队开展了一系列临床研究。他们入选健康成人配戴低、中、高厚度镜下液体层的巩膜镜90分钟，定量检测中央到周边的角膜水肿程度。结果显示，角膜水肿度呈现从中央向周边加重的趋势。与Kim等（2020）的理论模型对比后发现，周边角膜水肿的增加可能与周边角膜依赖角巩膜缘的代谢支持有关。</p><p>	基于上述发现，团队进一步探索巩膜镜片改良设计对泪液交换及周边水肿的影响。他们在薄镜下液体层巩膜镜上设置一个直径为0.3mm的角巩膜缘区开窗，配戴90分钟后发现，单个开窗即可显著减轻周边角膜水肿。这一结果与上世纪60年代Richard Hill在兔眼PMMA镜片中的观察一致，提示开窗可能通过局部增强泪液交换、促进氧气进入或二氧化碳排出等机制发挥作用，但其确切机制仍需深入研究。</p><p>	为了更直接地量化泪液交换，Steve Vincent教授团队采用ESP（基于电解质示踪剂）技术。该技术能够客观测量巩膜镜配戴过程中镜下液体层内的泪液更新速率。利用ESP，团队进一步评估了不同着陆区设计对泪液交换的影响。在一项针对健康成人的交叉试验中（受试者的平均巩膜环曲度为193µm），团队比较了两种着陆区设计：传统的球形着陆区与环曲面着陆区。结果显示，对于部分配戴者，环曲面着陆区能有效增加泪液交换。此外，团队还在环曲面着陆区的基础上，分别增加了切迹和凹槽两种结构。结果显示，这些改良设计同样可以改变泪液交换，但可能会增加镜下液体层内碎屑积聚的可能性。</p><p>	最后，Steve Vincent教授总结指出，短期的健康角膜数据显示，单个周边开窗可减轻巩膜镜诱导的周边角膜水肿；ESP技术可用于量化泪液交换；着陆区的环曲面、切迹或凹槽等改良设计能够改变泪液交换。这些发现为巩膜镜的个性化验配和优化角膜氧供提供了新思路，但需开展更长期的临床研究以验证其对角膜健康的影响。未来巩膜镜的设计将不仅关注镜片的光学性能和稳定性，泪液动态管理将成为提升配戴安全性的重要维度。</p><p><img src=\"data:image/png;base64,\"></p><p><br></p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-03/5fb94d7d8bb54ba1a7ee696400aea28d.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Iqbal A, Fisher D, Alonso-Caneiro D, Collins MJ, Vincent SJ. Central and peripheral scleral lens-induced corneal oedema. <em>Ophthalmic Physiol Opt</em>. 2024;44(4):792-800. doi:10.1111/opo.13221</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Fisher D, Collins MJ, Vincent SJ. Contact lens fenestrations and channels in relation to tear exchange and corneal oedema. <em>Clin Exp Optom</em>. 2025;108(5):530-543. doi:10.1080/08164622.2024.2426823</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Iqbal A, Fisher D, Alonso-Caneiro D, Collins MJ, Vincent SJ. Quantifying tear exchange during rigid contact lens wear using corneoscleral profilometry: A proof of concept study. <em>Ophthalmic Physiol Opt</em>. 2025;45(3):598-606. doi:10.1111/opo.13450</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Iqbal A, Fisher D, Alonso-Caneiro D, Collins MJ, Vincent SJ. Scleral lens landing zone toricity and tear exchange. <em>Cont Lens Anterior Eye</em>. 2026;49(1):102571. doi:10.1016/j.clae.2025.102571</p>', '教授，澳大利亚昆士兰科技大学视觉与眼科研究中心主任', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-25/a5c4396457e04fa4afeff82aa37ad999.png', 'ZH');
INSERT INTO `portal_speech` VALUES (40, 'MCLC 2026特邀嘉宾演讲集锦 第十四期', '周翔天', 187, 1, NULL, '2026-06-03 04:17:49', NULL, '2026-06-25 17:50:15', 0, '脉络膜血流在近视发病和防控中的作用', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-03/5b2dfef81f6047cd817fc65b9b9a8ccf.png', '周翔天，教授。上海交通大学医学院附属第九人民医院视觉健康全国重点实验室副主任，中华医学会眼科分会青年委员会副主任委员、中华眼科学会视觉生理学组副组长、中华眼科学会专家会员，亚太眼科学院及ARVO会士，兼任《IOVS》《BJO》《Experimental Eye Research》《Eye & Contact Lens》《中华眼科杂志》等期刊编委，长期从事近视发病机制与临床防控研究。', '<p>	周翔天教授系统阐述了脉络膜血流在屈光发育和近视发生中的核心作用，并基于“巩膜缺氧学说”提出一系列近视精准预测与干预的新策略。</p><p>近视是关系到国家和民族未来的大问题，必须高度重视，不能任其发展。然而，近视的发病机制未明，导致防控缺乏明确的抓手。70年代认为长期近距离工作导致晶状体变凸，诱导近视发生。90年代到至今则逐步过渡到眼球发育是一个自稳态过程，眼球发育受视觉输入调控，根据焦点位置调整自身生长速度，使物象落在视网膜上。异常视觉输入破坏自稳态发育导致近视。因此，从光学机制深入生物学机制，寻找可量化、可干预的关键环节，是突破近视防控瓶颈的必经之路。</p><p><img src=\"data:image/png;base64,\"></p><p>	周翔天教授团队的研究从巩膜入手。他们发现，巩膜细胞外基质重塑是近视形成的最终共同通路，而巩膜缺氧正是触发这一重塑过程的始动因素。那么，巩膜为什么会缺氧？团队将目光投向了紧邻巩膜的脉络膜。脉络膜是眼球内血流量最大的组织，不仅为视网膜和巩膜提供营养和氧气，还参与调节眼内微环境和信号转导。一系列动物实验揭示了脉络膜血流与近视之间的关系。在动物近视模型中，近视诱导早期脉络膜变薄，血流灌注显著减少。当近视诱导停止、眼睛进入恢复期时，脉络膜血流随之恢复至正常水平。这一动态变化提示，脉络膜血流减少可能是近视发生的早期事件。为进一步验证因果关系，团队采用药物干预直接调控脉络膜血流：使用血管扩张剂增加脉络膜血流，可显著抑制巩膜缺氧和近视形成；反之，使用血管收缩剂减少脉络膜血流，则能诱导近视形成。他们发现近距离工作同样导致脉络膜血流减少诱导巩膜缺氧。此外，周翔天教授受邀在眼科最权威综述性杂志Progress in Retinal and Eye Research撰文，提出视网膜多巴胺通过激活D1和D2受体形成内稳态、维持正常屈光发育。近视诱导时多巴胺减少，由于多巴胺对D2受体亲和力大于D1受体，首先减少对D1受体的激活，破坏了内稳态平衡，导致近视</p><p>	基于上述发现，周翔天教授团队正式提出“巩膜缺氧学说”：近距离工作等诱导近视的视觉信息可通过破坏视网膜多巴胺内稳态，引起脉络膜血流减少使巩膜缺氧，导致巩膜细胞外基质重塑，最终形成近视。这回答了近视自稳态发育异常学说重存在的关键问题，组织病理的改变机制；病理改变和近视之间的因果关系，以及组织间的信号传导途径。</p><p><img src=\"data:image/png;base64,\"></p><p>	脉络膜血流的改变不仅是近视发生的驱动因素，更可作为近视进展与干预疗效的快速预测指标。在动物模型中，脉络膜厚度和血流的早期变化量可精准预测后续的近视诱导量。在临床儿童队列中，基线脉络膜厚度和血流参数的减少与两年内快速近视进展呈显著相关；加入脉络膜指标后，传统屈光参数的预测模型性能大幅提升。在角膜塑形镜治疗中，配戴前的脉络膜血管指数（CVI）可有效预测一年后的眼轴控制效果，帮助临床医生筛选更适合该疗法的患者。此外，病理性近视患者的脉络膜厚度和血流显著减少，提示其可作为早期预警和进展监测的生物标志物。</p><p>	基于脉络膜血流调控，周翔天教授团队积极探索安全、易得的干预新方案。其中，口服鱼油（ω-3多不饱和脂肪酸） 的研究取得了令人鼓舞的进展。在豚鼠近视模型中，ω-3补充剂可有效抑制脉络膜厚度和血流的减少，延缓近视进展。在健康志愿者中，短期近距离工作会导致脉络膜血流显著下降，而预先口服ω-3则可明显改善这一血流下降。基于此，团队已启动随机双盲安慰剂对照临床试验，系统评估ω-3控制儿童近视发生发展的有效性与安全性。</p><p><img src=\"data:image/png;base64,\"></p><p>	综上，周翔天教授团队的研究不仅阐明了脉络膜血流减少导致近视的完整分子通路，更为近视的精准预测与个体化干预提供了可量化的生物学标志物。以脉络膜血流为靶点的防控策略，正在推动近视管理迈向精准防控的新时代。</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-03/f9be3e2d20844606bf17bd8c4853eb0f.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wu H, Chen W, Zhao F, et al. Scleral hypoxia is a target for myopia control. <em>Proc Natl Acad Sci U S A</em>. 2018;115(30):E7091-E7100. doi:10.1073/pnas.1721443115</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Zhou X, Ye C, Wang X, Zhou W, Reinach P, Qu J. Choroidal blood perfusion as a potential \"rapid predictive index\" for myopia development and progression. <em>Eye Vis (Lond)</em>. 2021;8(1):1. doi:10.1186/s40662-020-00224-0</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wu H, Liu M, Wang Y, et al. Short-term choroidal changes as early indicators for future myopic shift in primary school children: results of a 2-year cohort study. <em>Br J Ophthalmol</em>. 2025;109(2):273-280. doi:10.1136/bjo-2024-325871</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Zhang S, Zhang G, Zhou X, et al. Changes in Choroidal Thickness and Choroidal Blood Perfusion in Guinea Pig Myopia. <em>Invest Ophthalmol Vis Sci</em>. 2019;60(8):3074-3083. doi:10.1167/iovs.18-26397</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wu H, Zhang G, Shen M, et al. Assessment of Choroidal Vascularity and Choriocapillaris Blood Perfusion in Anisomyopic Adults by SS-OCT/OCTA. <em>Invest Ophthalmol Vis Sci</em>. 2021;62(1):8. doi:10.1167/iovs.62.1.8</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Pan M, Zhao F, Xie B, et al. Dietary ω-3 polyunsaturated fatty acids are protective for myopia. <em>Proc Natl Acad Sci U S A</em>. 2021;118(43):e2104689118. doi:10.1073/pnas.2104689118</p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Zhou X, Pardue MT, Iuvone PM, Qu J. Dopamine signaling and myopia development: What are the key challenges. <em>Prog Retin Eye Res</em>. 2017;61:60-71. doi:10.1016/j.preteyeres.2017.06.003</p><p>8.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Liu M, Wang Y, Li H, et al. Differences in choroidal responses to near work between myopic children and young adults. <em>Eye Vis (Lond)</em>. 2024;11(1):12. doi:10.1186/s40662-024-00382-5</p>', '教授，上海交通大学医学院附属第九人民医院视觉健康全国重点实验室副主任', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-25/992ab19a89a44ebda6b2978c8ed403e1.png', 'ZH');
INSERT INTO `portal_speech` VALUES (41, 'MCLC 2026特邀嘉宾演讲集锦 第十五期', 'Randy Kojima', 186, 1, NULL, '2026-06-03 04:26:36', NULL, '2026-06-25 17:49:40', 0, '角膜塑形镜患者的近视控制信号测量', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-03/fe1b1acf1fff4524b3074dfe475ccee8.png', 'Randy Kojima，加拿大温哥华KATT设计集团研发总监，太平洋大学视光学院客座助理临床教授。发表大量接触镜相关主题的学术论文及会议壁报，并为多部教科书章节担任撰稿作者。在全球范围内开展学术讲座，致力于与世界各国眼科同仁分享其专业见解、方法与研究成果。', '<p>	Randy Kojima教授围绕角膜塑形镜近视控制效果的预测指标展开报告，重点介绍了“近视离焦剂量（MDD）”这一量化工具，并探讨了如何通过角膜地形图参数提前评估控制效果，为OK镜的个性化验配提供了可操作的技术路径。</p><p>	角膜塑形术的近视控制效果已得到广泛验证，但临床中仍面临一个核心问题：在治疗开始前或早期，我们能否预测患者最终的控制效果？传统的做法是关注长期生物测量结果，每6至12个月随访眼轴长度，但这种方法无法提前优化镜片设计。Kojima教授提出，MDD可用于评估OK镜诱导的离焦信号强度，从而预测其对眼轴增长的抑制效果。</p><p><img src=\"data:image/png;base64,\"></p><p>	研究团队采用回顾性分析方法，比较了接受不同后光学区直径（BOZD，5.0mm与6.0mm）OK镜配戴的儿童，提取配戴后的角膜地形图参数，包括平坦子午线MDD、陡峭子午线MDD、圆周MDD以及体积MDD（三维离焦剂量，单位为D mm²），同时还分析了前表面高阶像差（球差、水平与垂直彗差）。结果显示，6.0mm光学区组与5.0mm光学区组在拟合圆周MDD上存在约1.00D的组间差异。基于此，Kojima教授提出了具体的离焦剂量建议：对于6.0mm BOZD的OK镜，应在5mm瞳孔边缘平均诱导约4.50D的相对角膜屈光力偏移（CPS）；对于5.0mm BOZD的镜片，则应诱导约3.50D。在体积MDD方面，6.0mm和5.0mm镜片应分别诱导约59.0 D mm²和46.0 D mm²的体积，以达到最佳的延缓效果。这一发现为镜片设计提供了量化目标。Kojima教授建议，临床中应争取实现体积MDD ≥ 46 D mm²、拟合圆周MDD ≥ 3.50 Dp，以获得理想的近视控制效果。</p><p><img src=\"data:image/png;base64,\"></p><p>	综上，Kojima教授指出，角膜塑形镜的近视控制效果并非随机变量，而是可以通过地形图参数进行预测和优化。通过在治疗早期评估MDD及相关像差指标，临床医生可以判断当前镜片设计是否产生足够的离焦信号，必要时调整光学区直径或镜片参数，从而提升患者的长期控制获益。</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-03/fce24ad34066440e8199ae1febd8442c.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Guo B, Cheung SW, Kojima R, Cho P. One-year results of the Variation of Orthokeratology Lens Treatment Zone (VOLTZ) Study: a prospective randomised clinical trial. <em>Ophthalmic Physiol Opt</em>. 2021;41(4):702-714. doi:10.1111/opo.12834</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Tan Q, Kojima R, Cho P, Vincent SJ. Association between axial elongation and corneal topography in children undergoing orthokeratology with different back optic zone diameters. <em>Eye Vis (Lond)</em>. 2025;12(1):3. Published 2025 Jan 3. doi:10.1186/s40662-024-00418-w</p>', '加拿大温哥华KATT设计集团研发总监，太平洋大学视光学院客座助理临床教授', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-25/15152cedea5e48978a3c38d82be39bc9.png', 'ZH');
INSERT INTO `portal_speech` VALUES (42, 'Collection of MCLC talks 2026, Issue 13', 'Steve Vincent', 188, 1, NULL, '2026-06-03 06:34:34', NULL, '2026-06-26 12:16:24', 0, 'Tear exchange during scleral lens wear', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-03/672f3ca431124600a1342f2722ba028a.png', 'Steve Vincent， Professor, Director of the Center for Vision and Ophthalmology at Queensland University of Technology in Australia, Fellow of the American Society of Optometry, British Contact Lens Association, Scleral Endoscopy Education Society, Australian Institute of Optometry, and Higher Education Society, Visiting Professor at West China Medical Center, Sichuan University, and Associate Editor in Chief of the journal Contact Lens and Prior Eye. My research focuses on the fields of visual optics, myopia, and special contact lenses.', '<p>Professor Steve Vincent systematically explored the mechanism and clinical significance of tear exchange during the wearing of scleral lenses, and presented the latest research results of his team in promoting tear exchange and reducing corneal edema through improved lens design.</p><p>One of the core challenges faced by wearing scleral lenses is corneal oxygen supply. The oxygen required by the cornea mainly comes from the air, and sufficient oxygen supply is crucial for maintaining corneal metabolism, transparency, wound healing, and defense function. However, the scleral lens itself has a certain thickness and limited oxygen permeability (Dk value requirement of 100 or above), and there is also an oxygen transport barrier in the liquid layer under the lens between the lens and the cornea. Therefore, dissolved oxygen in tears becomes an important supplement to corneal oxygen supply. When corneal hypoxia occurs, a series of complications such as tissue edema, decreased transparency affecting vision, long-term stromal softening, corneal neovascularization, and potential corneal transplant failure may occur in the corneal stroma and epithelial layer.</p><p><img src=\"data:image/png;base64,\"></p><p>To accurately evaluate corneal edema induced by scleral endoscopy, Professor Steve Vincent\'s team conducted a series of clinical studies. They were selected as healthy adults to wear low, medium, and high thickness liquid layer scleral lenses for 90 minutes to quantitatively detect the degree of corneal edema from the center to the periphery. The results showed that corneal edema tended to worsen from the center to the periphery. After comparing with the theoretical model of Kim et al. (2020), it was found that the increase in peripheral corneal edema may be related to the metabolic support of the peripheral cornea dependent on the corneal limbus.</p><p>Based on the above findings, the team further explored the effects of improved design of scleral lenses on tear exchange and peripheral edema. They set up a 0.3mm diameter window at the edge of the cornea and sclera on a thin liquid layer scleral lens. After wearing it for 90 minutes, they found that a single window could significantly reduce peripheral corneal edema. This result is consistent with Richard Hill\'s observations in PMMA lenses of rabbit eyes in the 1960s, suggesting that fenestration may play a role by locally enhancing tear exchange, promoting oxygen entry or carbon dioxide excretion, but its exact mechanism still needs further investigation.</p><p>In order to quantify tear exchange more directly, Professor Steve Vincent\'s team used ESP (electrolyte tracer based) technology. This technology can objectively measure the tear replacement rate in the liquid layer under the scleral lens during the wearing process. Using ESP, the team further evaluated the impact of different landing zone designs on tear exchange. In a crossover trial targeting healthy adults (with an average scleral curvature of 193 µ m), the team compared two landing zone designs: a traditional spherical landing zone and a curved landing zone. The results showed that for some wearers, the annular landing zone can effectively increase tear exchange. In addition, the team has added two types of structures, namely notches and grooves, on the basis of the landing area of the circular surface. The results showed that these improved designs can also alter tear exchange, but may increase the likelihood of debris accumulation within the liquid layer under the microscope.</p><p>Finally, Professor Steve Vincent summarized that short-term healthy corneal data shows that a single peripheral window can alleviate scleral lens induced peripheral corneal edema; ESP technology can be used to quantify tear exchange; Improved designs such as circular surfaces, notches, or grooves in the landing zone can alter tear exchange. These findings provide new ideas for personalized testing and optimization of corneal oxygen supply for scleral lenses, but more long-term clinical studies are needed to verify their impact on corneal health. In the future, the design of scleral lenses will not only focus on the optical performance and stability of the lenses, but also on the dynamic management of tears, which will become an important dimension to improve wearing safety.</p><p><br></p><p><img src=\"data:image/png;base64,\"></p><p><br></p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-03/4ee070d4b88141b2b0a90df77e556a60.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Iqbal A, Fisher D, Alonso-Caneiro D, Collins MJ, Vincent SJ. Central and peripheral scleral lens-induced corneal oedema. <em>Ophthalmic Physiol Opt</em>. 2024;44(4):792-800. doi:10.1111/opo.13221</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Fisher D, Collins MJ, Vincent SJ. Contact lens fenestrations and channels in relation to tear exchange and corneal oedema. <em>Clin Exp Optom</em>. 2025;108(5):530-543. doi:10.1080/08164622.2024.2426823</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Iqbal A, Fisher D, Alonso-Caneiro D, Collins MJ, Vincent SJ. Quantifying tear exchange during rigid contact lens wear using corneoscleral profilometry: A proof of concept study. <em>Ophthalmic Physiol Opt</em>. 2025;45(3):598-606. doi:10.1111/opo.13450</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Iqbal A, Fisher D, Alonso-Caneiro D, Collins MJ, Vincent SJ. Scleral lens landing zone toricity and tear exchange. <em>Cont Lens Anterior Eye</em>. 2026;49(1):102571. doi:10.1016/j.clae.2025.102571</p>', 'Professor, Director of the Centre for Vision and Ophthalmology at Queensland University of Technology, Australia', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-26/048fcc5577f34c238e1d0822f89a086a.png', 'EN');
INSERT INTO `portal_speech` VALUES (43, 'Collection of MCLC talks 2026, Issue 14', 'Zhou Xiangtian', 187, 1, NULL, '2026-06-03 06:39:46', NULL, '2026-06-26 12:15:46', 0, 'The role of choroidal blood flow in the pathogenesis', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-03/100c112997634a62a36709a21a3214aa.png', 'Zhou Xiangtian, Professor. Vice Director of the National Key Laboratory of Visual Health at the Ninth People\'s Hospital Affiliated to Shanghai Jiao Tong University School of Medicine, Vice Chairman of the Youth Committee of the Ophthalmology Branch of the Chinese Medical Association, Deputy Leader of the Visual Physiology Group of the Chinese Ophthalmology Society, Expert Member of the Chinese Ophthalmology Society, Fellow of the Asia Pacific College of Ophthalmology and ARVO, concurrently serving as an editorial board member of journals such as IOVS, BJO, Experimental Eye Research, Eye&Contact Lens, and Chinese Journal of Ophthalmology. Engaged in long-term research on the pathogenesis and clinical prevention and control of myopia.', '<p>Professor Zhou Xiangtian systematically elucidated the core role of choroidal blood flow in refractive development and myopia occurrence, and proposed a series of new strategies for accurate prediction and intervention of myopia based on the \"scleral hypoxia theory\".</p><p>Myopia is a major issue related to the future of the country and the nation, which must be highly valued and cannot be allowed to develop unchecked. However, the pathogenesis of myopia is unclear, leading to a lack of clear measures for prevention and control. In the 1970s, it was believed that long-term close work caused the lens to become convex and induced myopia. From the 1990s to the present, there has been a gradual transition to eye development as a self stabilizing process. Eye development is regulated by visual input and adjusts its growth rate based on the focal position, allowing the object to land on the retina. Abnormal visual input disrupts homeostatic development and leads to myopia. Therefore, delving into the biological mechanisms through optical mechanisms and finding quantifiable and modifiable key links is a necessary path to break through the bottleneck of myopia prevention and control.</p><p><img src=\"data:image/png;base64,\"></p><p>Professor Zhou Xiangtian\'s team\'s research starts from the sclera. They found that extracellular matrix remodeling of the sclera is the ultimate common pathway for myopia formation, and scleral hypoxia is the initiating factor that triggers this remodeling process. So, why does the sclera lack oxygen? The team turned their attention to the choroid adjacent to the sclera. The choroid is the tissue with the highest blood flow in the eyeball, providing nutrition and oxygen to the retina and sclera, as well as regulating the intraocular microenvironment and signal transduction. A series of animal experiments revealed the relationship between choroidal blood flow and myopia. In animal myopia models, myopia induces early choroidal thinning and significantly reduces blood flow perfusion. When myopia induction stops and the eye enters the recovery period, choroidal blood flow returns to normal levels. This dynamic change suggests that reduced choroidal blood flow may be an early event in the occurrence of myopia. To further verify the causal relationship, the team used drug intervention to directly regulate choroidal blood flow: using vasodilators to increase choroidal blood flow can significantly inhibit scleral hypoxia and myopia formation; On the contrary, using vasoconstrictors to reduce choroidal blood flow can induce myopia formation. They found that close range work also led to reduced choroidal blood flow and induced scleral hypoxia. In addition, Professor Zhou Xiangtian was invited to write an article in Progress in Retinal and Eye Research, the most authoritative review journal in ophthalmology, proposing that retinal dopamine forms an internal homeostasis and maintains normal refractive development by activating D1 and D2 receptors. When myopia is induced, dopamine decreases. Due to dopamine\'s greater affinity for D2 receptors than D1 receptors, the activation of D1 receptors is first reduced, disrupting the homeostasis and leading to myopia</p><p>Based on the above findings, Professor Zhou Xiangtian\'s team officially proposed the \"Scleral Hypoxia Theory\": visual information that induces myopia through close range work can disrupt the dopamine homeostasis in the retina, causing a decrease in choroidal blood flow and scleral hypoxia, leading to remodeling of the extracellular matrix of the sclera and ultimately forming myopia. This answers the key question of the existence of the theory of abnormal development of self steady state in myopia, and the mechanism of histopathological changes; The causal relationship between pathological changes and myopia, as well as the signal transduction pathways between tissues.</p><p><img src=\"data:image/png;base64,\"></p><p>The changes in choroidal blood flow are not only driving factors for the occurrence of myopia, but also serve as rapid predictive indicators for myopia progression and intervention efficacy. In animal models, early changes in choroidal thickness and blood flow can accurately predict subsequent myopia induction. In clinical pediatric cohorts, a significant correlation was observed between baseline choroidal thickness and reduced blood flow parameters and rapid progression of myopia within two years; After adding choroidal indices, the performance of traditional refractive parameter prediction models has significantly improved. In corneal reshaping therapy, the choroidal vascular index (CVI) before wearing can effectively predict the axial control effect one year later, helping clinicians screen patients who are more suitable for this therapy. In addition, the choroidal thickness and blood flow of patients with pathological myopia are significantly reduced, suggesting that they can serve as biomarkers for early warning and progression monitoring.</p><p>Based on choroidal blood flow regulation, Professor Zhou Xiangtian\'s team actively explores safe and easily accessible intervention strategies. Among them, research on oral fish oil (omega-3 polyunsaturated fatty acids) has made encouraging progress. In the guinea pig myopia model, omega-3 supplements can effectively inhibit the reduction of choroidal thickness and blood flow, delaying the progression of myopia. In healthy volunteers, short-term close range work can lead to a significant decrease in choroidal blood flow, while pre oral administration of omega-3 can significantly improve this blood flow decrease. Based on this, the team has initiated a randomized double-blind placebo-controlled clinical trial to systematically evaluate the effectiveness and safety of omega-3 in controlling the occurrence and development of myopia in children.</p><p><img src=\"data:image/png;base64,\"></p><p>In summary, Professor Zhou Xiangtian\'s team\'s research not only elucidates the complete molecular pathway of choroidal blood flow reduction leading to myopia, but also provides quantifiable biological markers for accurate prediction and personalized intervention of myopia. The prevention and control strategy targeting choroidal blood flow is driving myopia management towards a new era of precise prevention and control.</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-03/a84b4a8eb62740229ba1fdf8a238eaf4.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wu H, Chen W, Zhao F, et al. Scleral hypoxia is a target for myopia control. <em>Proc Natl Acad Sci U S A</em>. 2018;115(30):E7091-E7100. doi:10.1073/pnas.1721443115</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Zhou X, Ye C, Wang X, Zhou W, Reinach P, Qu J. Choroidal blood perfusion as a potential \"rapid predictive index\" for myopia development and progression. <em>Eye Vis (Lond)</em>. 2021;8(1):1. doi:10.1186/s40662-020-00224-0</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wu H, Liu M, Wang Y, et al. Short-term choroidal changes as early indicators for future myopic shift in primary school children: results of a 2-year cohort study. <em>Br J Ophthalmol</em>. 2025;109(2):273-280. doi:10.1136/bjo-2024-325871</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Zhang S, Zhang G, Zhou X, et al. Changes in Choroidal Thickness and Choroidal Blood Perfusion in Guinea Pig Myopia. <em>Invest Ophthalmol Vis Sci</em>. 2019;60(8):3074-3083. doi:10.1167/iovs.18-26397</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wu H, Zhang G, Shen M, et al. Assessment of Choroidal Vascularity and Choriocapillaris Blood Perfusion in Anisomyopic Adults by SS-OCT/OCTA. <em>Invest Ophthalmol Vis Sci</em>. 2021;62(1):8. doi:10.1167/iovs.62.1.8</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Pan M, Zhao F, Xie B, et al. Dietary ω-3 polyunsaturated fatty acids are protective for myopia. <em>Proc Natl Acad Sci U S A</em>. 2021;118(43):e2104689118. doi:10.1073/pnas.2104689118</p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Zhou X, Pardue MT, Iuvone PM, Qu J. Dopamine signaling and myopia development: What are the key challenges. <em>Prog Retin Eye Res</em>. 2017;61:60-71. doi:10.1016/j.preteyeres.2017.06.003</p><p>8.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Liu M, Wang Y, Li H, et al. Differences in choroidal responses to near work between myopic children and young adults. <em>Eye Vis (Lond)</em>. 2024;11(1):12. doi:10.1186/s40662-024-00382-5</p>', 'Professor. Deputy Director of the National Key Laboratory of Visual Health at the Ninth People\'s Hospital Affiliated to Shanghai Jiao Tong University School of Medicine', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-26/87b5deb56bb040779bec90c05d82c46f.png', 'EN');
INSERT INTO `portal_speech` VALUES (44, 'Collection of MCLC talks 2026, Issue 15', 'Randy Kojima', 186, 1, NULL, '2026-06-03 06:43:15', NULL, '2026-06-26 12:15:32', 0, 'Measuring Myopia Control Signal Strength in Orthokeratology', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-03/363bbbf1e0e64a088d6a9942709bb10a.png', 'Randy Kojima， Director of Research and Development at KATT Design Group in Vancouver, Canada, and Visiting Assistant Clinical Professor at the School of Optometry at Pacific University. Published numerous academic papers and conference posters on contact lens related topics, and served as a contributing author for multiple textbook chapters. Conducting academic lectures globally, dedicated to sharing professional insights, methods, and research results with colleagues in ophthalmology from around the world.', '<p>Professor Randy Kojima presented a report on the predictive indicators of myopia control effect of orthokeratology lenses, focusing on the quantitative tool of \"Myopia Defocus Dose (MDD)\", and explored how to evaluate the control effect in advance through corneal topography parameters, providing an operable technical path for personalized laboratory matching of OK lenses.</p><p>The myopia control effect of corneal reshaping surgery has been widely validated, but there is still a core issue in clinical practice: can we predict the final control effect of patients before or in the early stages of treatment? The traditional approach is to focus on long-term biometric results and follow up on axial length every 6 to 12 months, but this method cannot optimize lens design in advance. Professor Kojima proposed that MDD can be used to evaluate the defocus signal intensity induced by OK lenses, thereby predicting its inhibitory effect on axial growth.</p><p><img src=\"data:image/png;base64,\"></p><p>The research team used a retrospective analysis method to compare children who received OK lenses with different back zone diameters (BOZD, 5.0mm and 6.0mm) and extracted corneal topography parameters after fitting, including flat meridian MDD, steep meridian MDD, circumferential MDD, and volume MDD (three-dimensional defocus dose, in D mm ²). At the same time, high-order aberrations on the anterior surface (spherical aberration, horizontal and vertical coma) were also analyzed. The results showed that there was an intergroup difference of approximately 1.00D in the fitting circumference MDD between the 6.0mm optical zone group and the 5.0mm optical zone group. Based on this, Professor Kojima proposed specific defocusing dose recommendations: for a 6.0mm BOZD OK lens, an average relative corneal power deviation (CPS) of about 4.50D should be induced at the 5mm pupil edge; For a 5.0mm BOZD lens, approximately 3.50D should be induced. In terms of volume MDD, 6.0mm and 5.0mm lenses should induce volumes of approximately 59.0 D mm ² and 46.0 D mm ², respectively, to achieve the best retardation effect. This discovery provides quantitative targets for lens design. Professor Kojima suggests that in clinical practice, efforts should be made to achieve a volume MDD of ≥ 46 D mm ² and a fitted circumference MDD of ≥ 3.50 Dp to achieve ideal myopia control effects.</p><p><img src=\"data:image/png;base64,\"></p><p>In summary, Professor Kojima pointed out that the myopia control effect of corneal reshaping lenses is not a random variable, but can be predicted and optimized through topographic map parameters. By evaluating MDD and related aberration indicators in the early stages of treatment, clinical doctors can determine whether the current lens design produces sufficient defocus signal and adjust the optical zone diameter or lens parameters if necessary, thereby improving the long-term control benefits for patients.</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-03/8c76ad81230644c4ad7339ac89a7e309.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Guo B, Cheung SW, Kojima R, Cho P. One-year results of the Variation of Orthokeratology Lens Treatment Zone (VOLTZ) Study: a prospective randomised clinical trial. <em>Ophthalmic Physiol Opt</em>. 2021;41(4):702-714. doi:10.1111/opo.12834</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Tan Q, Kojima R, Cho P, Vincent SJ. Association between axial elongation and corneal topography in children undergoing orthokeratology with different back optic zone diameters. <em>Eye Vis (Lond)</em>. 2025;12(1):3. Published 2025 Jan 3. doi:10.1186/s40662-024-00418-w</p>', 'Director of Research and Development at KATT Design Group in Vancouver, Canada, and Visiting Assistant Clinical Professor at the School of Optometry, Pacific University', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-06-26/12faf45e7f8f4ebea7a7cf9da38f837f.png', 'EN');
INSERT INTO `portal_speech` VALUES (45, 'MCLC 2026特邀嘉宾演讲集锦 第十六期', '邹海东', 185, 1, NULL, '2026-08-04 10:26:47', NULL, '2026-08-04 10:31:05', 0, 'A Sustainable Systematic Approach to Myopia Care The Shanghai Mode （明眸上海近视防控新进展）', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-08-04/813a327c19b9498e9c0f2226d27abd46.png', '邹海东，主任医师，同济大学附属眼科医院（筹）/上海市眼病防治中心/上海市眼科医院院长，上海市第一人民医院副院长。国家科技部重点研发计划项目首席专家，中华预防医学会眼科分会副主任委员、上海市医学会视光学会主任委员。长期从事眼科临床及眼病公共卫生学研究，聚焦近视等眼病的筛查防控、大数据与人工智能应用。', '<p><strong>主旨报告内容回顾</strong></p><p>	邹海东教授从公共卫生慢病管理的视角出发，系统阐述了近视防控的三级预防策略，并分享了上海在近视筛查、动态监测、预测干预及科普宣教等方面的系列创新成果，为大规模人群近视防控提供了可复制、可推广的上海方案。</p><p class=\"ql-align-center\"><img src=\"data:image/png;base64,\" height=\"259\" width=\"466\"></p><p>	近视防控的首要任务是实现精准筛查与动态管理。邹海东教授团队主导的SCALE研究（百万儿童屈光档案项目）自2008年启动至今，已累计建档312万人。团队首创非散瞳验光联合裸眼视力筛检近视法，受试者工作特征曲线下面积（AUC）高达0.985，该方法自2020年起已在全国推广应用近2亿人次。在此基础上，团队推进结构化电子病历建设，促进医防数据高效融合。他们建立了3-14岁儿童的远视储备正常值范围，实现了从横断面定性筛查向动态量化管理的转变。并积极寻找睫状肌麻痹的替代指标——眼轴长度，为大规模近视管理提供了客观、便捷的工具。</p><p>	在筛查建档的同时，团队关注近视早期的眼底改变。研究发现，在9-12岁低度近视儿童中，豹纹状眼底1级及以上比例已达52.4%，提示近视相关眼底病变在低龄阶段即已启动。基于眼底图像和非散瞳参数（性别、年龄、眼轴长度），团队构建了近视发生与进展的预测模型DeepMyopia，可实现个体危险分层，从而在大规模人群中实施针对性干预指导。进一步的模拟随机对照试验评估了DeepMyopia辅助近视干预的有效性：与非散瞳参数模型辅助干预相比，DeepMyopia表现出更优效果，调整后相对近视发生率降低17.8%，且与基于散瞳数据的辅助干预模型效果相当，展现出人工智能赋能近视管理的巨大潜力。</p><p class=\"ql-align-center\"><img src=\"data:image/png;base64,\" height=\"259\" width=\"466\"></p><p>	如何从群体层面降低近视发生率？邹海东教授团队开展了STORM研究（上海户外时间减少近视学校干预试验），这是一项为期5年、纳入6295名儿童的随机对照学校户外干预试验。结果显示，与对照组相比，两个干预组（每日额外40分钟和80分钟户外活动）的2年近视发生率差异无统计学意义，但两组合并分析显示，近视发生率绝对下降3.9%，相对下降16.5%。团队进一步研发智能腕表，实时客观采集户外时间与光照暴露量，基于腕表大数据获得了五项新证据：①光照强度越大、户外时长越长，近视预防效果越好；②单次有效户外光暴露模式为持续时间≥15分钟且光照强度＞2000 lux；③户外光暴露在近视前期预防效果有限，需增加暴露时长；④户外活动推广可同时提升学习成绩；⑤体力活动强度本身也是近视预防的独立影响因素。这些证据为科学制定户外干预方案提供了量化依据。</p><p>	针对高度近视这一重点人群，邹海东教授团队建立了SCALE-HM研究（高度近视登记队列），自2018年至今已纳入3000余例患者并持续扩充。该专病队列旨在长期观察高度近视的自然病程、临床特征、危险因素及遗传机制，探索并发症高危人群的预测指标体系与预警值，并加强日常眼健康管理与早期干预。上海地区3-18岁高度近视人群中，14岁高度近视率达17.7%，视盘周萎缩弧常见，弥漫性萎缩较少见。</p><p>	在三级防控实践与研究体系基础上，邹海东教授团队近五年发表相关论文100余篇，并积极推进新时期群体整合型防控干预策略。2024年，团队率先在1.5万名小学生中开展真实世界研究，创建了“目”浴阳光科普品牌，建立了综合防控近视标准化展示馆，打造了可复制的学校/家庭近视防控、近视自助筛查、干预手段及趣味宣教样板间。通过联合共建、牵头全国研究及“沪眼星光”人才培养计划，持续推动近视防控事业的可持续发展。</p><p>	综上，邹海东教授的报告系统呈现了从筛查建档、动态监测、风险预测到群体干预、高度近视管理及科普宣教的全链条实践，展现了公共卫生视角下近视三级预防体系的完整架构。这些创新举措不仅显著提升了上海近视防控工作的精准性与覆盖面，也为全国乃至全球的近视防控提供了宝贵的上海经验。</p>', '', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;He X, Deng J, Xu X, et al. Design and Pilot data of the high myopia registration study: Shanghai Child and Adolescent Large-scale Eye Study (SCALE-HM). <em>Acta Ophthalmol</em>. 2021;99(4):e489-e500. doi:10.1111/aos.14617</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Qi Z, Li T, Chen J, et al. A deep learning system for myopia onset prediction and intervention effectiveness evaluation in children. <em>NPJ Digit Med</em>. 2024;7(1):206. Published 2024 Aug 7. doi:10.1038/s41746-024-01204-7</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wang J, Sankaridurg P, Naduvilath T, et al. Time outdoors positively associates with academic performance: a school-based study with objective monitoring of outdoor time. <em>BMC Public Health</em>. 2023;23(1):645. Published 2023 Apr 4. doi:10.1186/s12889-023-15532-y</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Chen J, Wang J, Qi Z, et al. Smartwatch Measures of Outdoor Exposure and Myopia in Children. <em>JAMA Netw Open</em>. 2024;7(8):e2424595. Published 2024 Aug 1. doi:10.1001/jamanetworkopen.2024.24595</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Cheng T, Deng J, Xiong S, et al. Crystalline Lens Power and Associated Factors in Highly Myopic Children and Adolescents Aged 4 to 19 Years. <em>Am J Ophthalmol</em>. 2021;223:169-177. doi:10.1016/j.ajo.2020.07.007</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Deng J, Xu X, Pan CW, et al. Myopic maculopathy among Chinese children with high myopia and its association with choroidal and retinal changes: the SCALE-HM study. <em>Br J Ophthalmol</em>. 2024;108(5):720-728. Published 2024 May 21. doi:10.1136/bjo-2022-321839</p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Xu Y, Deng J, Zhang B, et al. Higher-order aberrations and their association with axial elongation in highly myopic children and adolescents. <em>Br J Ophthalmol</em>. 2023;107(6):862-868. doi:10.1136/bjophthalmol-2021-319769</p>', '主任医师，同济大学附属眼科医院（筹）/上海市眼病防治中心/上海市眼科医院院长，上海市第一人民医院副院长。', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-08-04/1f49df6c72d34edba8cec1508d2c9d4c.png', 'ZH');
INSERT INTO `portal_speech` VALUES (46, 'MCLC 2026特邀嘉宾演讲集锦 第十七期', '杨晓', 184, 1, NULL, '2026-08-04 10:46:12', NULL, '2026-08-07 18:27:08', 0, 'Clinical-question-driven myopia prevention and control research （以临床问题为导向的近视防控干预研究）', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-08-04/503aeb9223ca453cbca4f9343780a2ee.png', '中山大学中山眼科中心教授、主任医师、博士生导师，屈光与青少年近视防控科主任，眼病防治全国重点实验室PI。现任中华医学会眼科学分会眼视光学组副组长、中国女医师协会眼科学分会视光学组副组长、中国医疗保健国际交流促进会总会理事，国际近视防控与角膜塑形学会（IAOMC）中国首批专家委员。长期从事儿童青少年视觉健康防治工作，擅长屈光不正问题的个体化综合诊疗。', '<p>	杨晓教授在本次大会上围绕“以临床问题为导向”的核心理念，系统展示了其团队在近视精准防控领域的系列研究成果，覆盖风险预测、行为干预、光学优化及药物方案优化等多个关键环节。</p><p>	精准识别高风险人群是近视防控的第一步。杨晓教授团队建立了基于学校群体的前瞻性队列研究，开发了在线近视预测工具，提出了“近视前期”的新定义，为临床提供了可量化的风险评估手段。一个值得关注的新发现是，每日使用智能手表超过1小时的儿童，近视进展显著加快，近视前期与已近视者中尤为明显，提示智能穿戴设备的使用风险同样不容忽视。在早期疗效预测方面，团队建立了基于第一个月眼轴变化的预测模型，可在治疗早期识别疗效不佳者，实现“即时止损、及时调整”。</p><p class=\"ql-align-center\"><img src=\"data:image/png;base64,\" height=\"250\" width=\"466\"></p><p>	针对大规模人群的行为干预，杨晓教授团队设计了一种基于移动平台的家庭健康教育方案，以学校为单位、微信为载体，每周推送户外活动、用眼习惯、读写姿势等视力相关健康行为内容，有效降低了儿童近视风险。该研究证实了移动平台行为干预的经济高效性，为群体防控提供了可操作的路径。</p><p>	针对光学干预手段，杨晓教授团队在多个方向进行了创新探索。杨晓教授团队通过数字化设计优化OK镜配适参数，提高镜片与角膜间泪液层厚度的匹配性，从而提升离焦量。自主研发的非对称多点离焦框架镜（AMDT）基于眼动仪测算设计，在保证控制效果的同时兼顾了良好的视觉适应性。在联合治疗方面，OK镜联合低浓度阿托品的随机对照试验（ZOC-ACO研究）证实联合治疗优于单一治疗，且疗效与年龄相关——OK镜在低龄组疗效较好，阿托品在高龄组疗效更优。</p><p class=\"ql-align-center\"><img src=\"data:image/png;base64,\" height=\"268\" width=\"465\"></p><p>	在药物干预方面，杨晓教授团队比较了0.01%阿托品不同给药频次的效果，发现每日2次较每晚1次能更有效地延缓眼轴增长与近视进展，为临床用药方案的优化提供了循证依据。</p><p>综上，杨晓教授的报告呈现了一条从精准预测、行为干预到光学与药物治疗的完整研究路径，以临床问题为驱动，以高质量证据为支撑，推动近视防控从“一刀切”走向精准化、个体化的新时代。</p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/videos/2026-08-04/e0a7595deeb7406689068d7f427d7453.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Xu S, Ruan Z, Wang Y, et al. Establishment of Myopia Occurrence Prediction Model in Children without Myopia Using Cycloplegic Refraction and Prior Axial Length Change. <em>Ophthalmology</em>. 2025;132(11):1260-1272. doi:10.1016/j.ophtha.2025.06.010</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Li Q, Guo L, Zhang J, et al. Effect of School-Based Family Health Education via Social Media on Children\'s Myopia and Parents\' Awareness: A Randomized Clinical Trial. <em>JAMA Ophthalmol</em>. 2021;139(11):1165-1172. doi:10.1001/jamaophthalmol.2021.3695</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wang M, Ma R, Kuang L, et al. Myopia Control Efficacy of Asymmetric Multipoint Defocus Technique Spectacle Lenses: One-Year Double-Masked Randomized Controlled Trial. <em>Ophthalmology</em>. 2025;132(9):972-979. doi:10.1016/j.ophtha.2025.04.022</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Xu S, Li Z, Zhao W, et al. Effect of atropine, orthokeratology and combined treatments for myopia control: a 2-year stratified randomised clinical trial. <em>Br J Ophthalmol</em>. 2023;107(12):1812-1817. Published 2023 Nov 22. doi:10.1136/bjo-2022-321272</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Hu Y, Ding X, Jiang J, et al. Long-Term Axial Length Shortening in Myopic Orthokeratology: Incident Probability, Time Course, and Influencing Factors. <em>Invest Ophthalmol Vis Sci</em>. 2023;64(15):37. doi:10.1167/iovs.64.15.37</p>', '杨晓，中山大学中山眼科中心教授、主任医师、博士生导师', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-08-07/0467b45d162c4db69e9b3b68765b96d9.jpg', 'ZH');
INSERT INTO `portal_speech` VALUES (47, 'Collection of MCLC talks 2026, Issue 17', 'Yang Xiao', 184, 1, NULL, '2026-08-04 11:38:30', NULL, '2026-08-07 18:18:22', 0, 'Clinical-question-driven myopia prevention and control research （以临床问题为导向的近视防控干预研究）', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-08-04/3b58f379162e46d58b38579a4b2fafc9.png', 'Professor, Chief Physician, Doctoral Supervisor, Director of the Department of Refraction and Adolescent Myopia Prevention & Control, Zhongshan Ophthalmic Center, Sun Yat-sen University; Principal Investigator, State Key Laboratory of Ophthalmic Disease Prevention and Treatment.\nShe currently serves as Vice Chair of the Optometry Group, Chinese Ophthalmological Society, Chinese Medical Association; Vice Chair of the Optometry Group, Ophthalmology Branch, Chinese Medical Women’s Association; Director of China International Exchange and Promotive Association for Medical and Health Care; and one of the first Chinese expert members of the International Academy of Orthokeratology and Myopia Control (IAOMC).\nHer research focuses on the prevention and management of visual health in children and adolescents, with expertise in individualized comprehensive diagnosis and treatment of refractive errors.', '<p>Centered on the core philosophy of <span style=\"background-color: rgba(0, 0, 0, 0);\">clinical problem-oriented research</span>, Professor Yang systematically presented a series of research achievements by her team in the field of precision myopia prevention and control, covering critical segments including risk prediction, behavioral intervention, optimization of optical strategies and pharmaceutical regimens.</p><p>Precise identification of high-risk populations constitutes the first step of myopia management. Based on a school-based prospective cohort study, Professor Yang’s team developed an online myopia prediction tool and proposed a new definition of <span style=\"background-color: rgba(0, 0, 0, 0);\">pre-myopia</span>, providing quantifiable risk assessment approaches for clinical practice. One notable new finding revealed that children spending more than one hour daily on smartwatches exhibited significantly accelerated myopia progression, especially among pre-myopic and myopic children, indicating that the risks associated with wearable smart devices should not be overlooked. In terms of early therapeutic response prediction, the team established a prediction model based on axial length changes within the first month of treatment, enabling early identification of poor responders to achieve timely adjustment of intervention strategies.</p><p class=\"ql-align-center\"><img src=\"data:image/png;base64,\" height=\"250\" width=\"466\"></p><p><br></p><p>For population-based behavioral interventions, Professor Yang’s team designed a mobile-platform-based family health education program. Taking schools as units and WeChat as the carrier, the program delivers weekly health guidance on outdoor activities, eye-use habits and reading-writing postures, effectively reducing children’s myopia risk. The study verified the cost-effectiveness of mobile health behavioral interventions and offered an operable pathway for population-wide myopia prevention.</p><p>Innovative explorations have also been carried out in optical interventions. Through digital optimization of orthokeratology (OK) lens fitting parameters, the team improved the matching of tear film thickness between the lens and cornea to enhance peripheral defocus magnitude. The self-developed <span style=\"background-color: rgba(0, 0, 0, 0);\">Asymmetric Multipoint Defocus Technique (AMDT)</span> spectacle lenses were designed based on eye-tracking measurements, balancing satisfactory myopia control efficacy and good visual tolerance. Regarding combined therapy, the randomized controlled trial (ZOC-ACO Study) evaluating orthokeratology combined with low-concentration atropine confirmed that combination therapy outperforms monotherapy, and treatment efficacy is age-dependent: orthokeratology achieves better outcomes in younger children, while atropine works more favorably in older children.</p><p><img src=\"data:image/png;base64,\"></p><p>In pharmacological intervention, the team compared the efficacy of different administration frequencies of 0.01% atropine. The results demonstrated that twice-daily administration exerted stronger effects in slowing axial elongation and myopia progression than once-nightly dosing, providing evidence-based references for optimizing clinical medication protocols.</p><p>In summary, Professor Yang’s presentation outlined a complete research pipeline spanning precise risk prediction, behavioral intervention, optical therapy and pharmacological treatment. Driven by clinical questions and supported by high-quality clinical evidence, this work advances myopia management from a one-size-fits-all model toward an era of precision and individualized care.</p><p><br></p>', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/videos/2026-08-04/c1da51a939ad4e06ad8d59e2d27c6a5d.mp4', '<p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Xu S, Ruan Z, Wang Y, et al. Establishment of Myopia Occurrence Prediction Model in Children without Myopia Using Cycloplegic Refraction and Prior Axial Length Change. <em>Ophthalmology</em>. 2025;132(11):1260-1272. doi:10.1016/j.ophtha.2025.06.010</p><p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Li Q, Guo L, Zhang J, et al. Effect of School-Based Family Health Education via Social Media on Children\'s Myopia and Parents\' Awareness: A Randomized Clinical Trial. <em>JAMA Ophthalmol</em>. 2021;139(11):1165-1172. doi:10.1001/jamaophthalmol.2021.3695</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Wang M, Ma R, Kuang L, et al. Myopia Control Efficacy of Asymmetric Multipoint Defocus Technique Spectacle Lenses: One-Year Double-Masked Randomized Controlled Trial. <em>Ophthalmology</em>. 2025;132(9):972-979. doi:10.1016/j.ophtha.2025.04.022</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Xu S, Li Z, Zhao W, et al. Effect of atropine, orthokeratology and combined treatments for myopia control: a 2-year stratified randomised clinical trial. <em>Br J Ophthalmol</em>. 2023;107(12):1812-1817. Published 2023 Nov 22. doi:10.1136/bjo-2022-321272</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Hu Y, Ding X, Jiang J, et al. Long-Term Axial Length Shortening in Myopic Orthokeratology: Incident Probability, Time Course, and Influencing Factors. <em>Invest Ophthalmol Vis Sci</em>. 2023;64(15):37. doi:10.1167/iovs.64.15.37</p>', 'Professor, Chief Physician, Doctoral Supervisor, Director of the Department of Refraction and Adolescent Myopia Prevention & Control, Zhongshan Ophthalmic Center, Sun Yat-sen University; Principal Investigator, State Key Laboratory of Ophthalmic Disease Prevention and Treatment.', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-08-07/cdbdde0e5a034d54849595141b17754a.jpg', 'EN');
INSERT INTO `portal_speech` VALUES (48, 'Collection of MCLC talks 2026, Issue 16', 'Zou Haidong', 185, 1, NULL, '2026-08-04 11:43:52', NULL, '2026-08-07 18:18:11', 0, 'A Sustainable Systematic Approach to Myopia Care The Shanghai Mode （明眸上海近视防控新进展）', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-08-04/25e5eb60a0964b1591fdb0762aeb4e34.png', 'Chief Physician, President of Tongji University Affiliated Ophthalmic Hospital (In Preparation) / Shanghai Eye Disease Prevention & Treatment Center / Shanghai Eye Hospital; Vice President of Shanghai General Hospital.\nHe serves as the Chief Scientist for the National Key R&D Program, Vice Chair of the Ophthalmology Branch, Chinese Preventive Medicine Association, and Chair of the Shanghai Society of Optometry.\nHis clinical and research interests lie in ophthalmic public health, focusing on screening and prevention of myopia, big data applications and artificial intelligence in eye healthcare.', '<p>From the perspective of chronic disease management in public health, Professor Zou systematically elaborated on the three-tier prevention strategy for myopia and shared a series of innovative outcomes from Shanghai’s practice in myopia screening, dynamic monitoring, risk prediction, intervention and science popularization, forming a replicable and scalable <span style=\"background-color: rgba(0, 0, 0, 0);\">Shanghai Model</span> for population-wide myopia prevention and control.</p><p><img src=\"data:image/png;base64,\"></p><p>Accurate screening and dynamic management are the top priorities of myopia control. Led by Professor Zou, the <span style=\"background-color: rgba(0, 0, 0, 0);\">SCALE Study (Million Children Refractive Archive Project)</span> was launched in 2008, with more than 3.12 million children enrolled to date. The team pioneered a screening algorithm combining non-cycloplegic refraction and uncorrected visual acuity to detect myopia, achieving an Area Under the Curve (AUC) of 0.985. This method has been deployed nationwide for nearly 200 million screening sessions since 2020. On this basis, the team promoted structured electronic medical records to facilitate integrated medical and preventive healthcare data. They established normal reference ranges of hyperopia reserve for children aged 3–14 years, transforming screening from cross-sectional qualitative assessment to dynamic quantitative management. The team also explored axial length as a potential alternative indicator to cycloplegic refraction, providing an objective and convenient tool for large-scale myopia management.</p><p>Beyond screening and archive building, the team investigated early fundus changes associated with myopia. Research indicated that the prevalence of <span style=\"background-color: rgba(0, 0, 0, 0);\">tessellated fundus Grade 1 or above</span> reached 52.4% among children aged 9–12 with low myopia, suggesting that myopia-related fundus lesions initiate at an early age. Based on fundus images and non-cycloplegic parameters (gender, age, axial length), the team constructed <span style=\"background-color: rgba(0, 0, 0, 0);\">DeepMyopia</span>, a prediction model for myopia onset and progression to enable individual risk stratification and targeted intervention in large populations. Further simulated randomized controlled trials evaluated the performance of DeepMyopia-assisted intervention: compared with interventions guided only by non-cycloplegic parameters, the DeepMyopia strategy reduced adjusted relative myopia incidence by 17.8%, and achieved efficacy comparable to models built on cycloplegic data, demonstrating great potential of artificial intelligence in myopia management.</p><p class=\"ql-align-center\"><img src=\"data:image/png;base64,\" height=\"259\" width=\"466\"></p><p><br></p><p>How to reduce myopia incidence at the population level? Professor Zou’s team conducted the <span style=\"background-color: rgba(0, 0, 0, 0);\">STORM Study (Shanghai Trial of Outdoor Time Reduction for Myopia Prevention in Schools)</span>, a 5-year randomized controlled school-based outdoor intervention trial enrolling 6,295 children. The results showed no statistically significant difference in 2-year myopia incidence between the control group and two intervention groups (additional 40 mins and 80 mins of daily outdoor activity). However, pooled analysis of the two intervention groups revealed an absolute reduction of 3.9% and relative reduction of 16.5% in myopia incidence. The team further developed smart wristbands to objectively monitor outdoor duration and light exposure in real time. Big data from wearable devices yielded five new evidence-based conclusions: ① Higher light intensity and longer outdoor duration lead to better myopia prevention effects; ② Effective single outdoor light exposure requires ≥15 consecutive minutes with illuminance &gt;2000 lux; ③ Outdoor light exposure offers limited preventive effects for pre-myopia, requiring extended exposure duration; ④ Promotion of outdoor activities can simultaneously improve academic performance; ⑤ Physical activity intensity serves as an independent protective factor against myopia. These findings provide quantitative evidence for designing scientific outdoor intervention protocols.</p><p>Targeting high myopia, the team launched the <span style=\"background-color: rgba(0, 0, 0, 0);\">SCALE-HM Study (High Myopia Cohort Registry)</span> in 2018, which has recruited over 3,000 patients and continues to expand. This specialized cohort aims to observe the natural history, clinical characteristics, risk factors and genetic mechanisms of high myopia in the long run, explore predictive indicators and warning thresholds for patients at high risk of complications, and strengthen routine eye health management and early intervention. Among children and adolescents aged 3–18 years in Shanghai, the prevalence of high myopia reached 17.7% at age 14. Peripapillary atrophy arcs are common, while diffuse atrophy is relatively rare.</p><p>Building upon the three-tier prevention framework and research system, Professor Zou’s team has published more than 100 relevant papers in the past five years and advanced an integrated population-based intervention strategy for myopia prevention in the new era. In 2024, the team carried out a real-world study covering 15,000 primary school students. They created the public education brand <em style=\"background-color: rgba(0, 0, 0, 0);\">Embrace Sunshine</em>, built a standardized exhibition hall for comprehensive myopia prevention, and established replicable demonstration modules covering school-family joint prevention, self-service myopia screening, intervention options and interactive science education. Through joint research partnerships, leading national multicenter studies and the <em style=\"background-color: rgba(0, 0, 0, 0);\">Shanghai Bright Eyes Talent Program</em>, the team sustains the long-term development of myopia prevention and control.</p><p>In conclusion, Professor Zou’s presentation systematically demonstrated a full-chain practice covering screening and archiving, dynamic monitoring, risk prediction, population-based intervention, high myopia management and public education, outlining a complete three-tier public health framework for myopia prevention. These innovative practices have greatly improved the precision and coverage of myopia services in Shanghai, and offered valuable Shanghai experience for myopia prevention nationwide and globally.</p><p><br></p>', '', '<p>1.	He X, Deng J, Xu X, et al. Design and Pilot data of the high myopia registration study: Shanghai Child and Adolescent Large-scale Eye Study (SCALE-HM). Acta Ophthalmol. 2021;99(4):e489-e500. doi:10.1111/aos.14617</p><p>2.	Qi Z, Li T, Chen J, et al. A deep learning system for myopia onset prediction and intervention effectiveness evaluation in children. NPJ Digit Med. 2024;7(1):206. Published 2024 Aug 7. doi:10.1038/s41746-024-01204-7</p><p>3.	Wang J, Sankaridurg P, Naduvilath T, et al. Time outdoors positively associates with academic performance: a school-based study with objective monitoring of outdoor time. BMC Public Health. 2023;23(1):645. Published 2023 Apr 4. doi:10.1186/s12889-023-15532-y</p><p>4.	Chen J, Wang J, Qi Z, et al. Smartwatch Measures of Outdoor Exposure and Myopia in Children. JAMA Netw Open. 2024;7(8):e2424595. Published 2024 Aug 1. doi:10.1001/jamanetworkopen.2024.24595</p><p>5.	Cheng T, Deng J, Xiong S, et al. Crystalline Lens Power and Associated Factors in Highly Myopic Children and Adolescents Aged 4 to 19 Years. Am J Ophthalmol. 2021;223:169-177. doi:10.1016/j.ajo.2020.07.007</p><p>6.	Deng J, Xu X, Pan CW, et al. Myopic maculopathy among Chinese children with high myopia and its association with choroidal and retinal changes: the SCALE-HM study. Br J Ophthalmol. 2024;108(5):720-728. Published 2024 May 21. doi:10.1136/bjo-2022-321839</p><p>7.	Xu Y, Deng J, Zhang B, et al. Higher-order aberrations and their association with axial elongation in highly myopic children and adolescents. Br J Ophthalmol. 2023;107(6):862-868. doi:10.1136/bjophthalmol-2021-319769</p>', 'Chief Physician, President of Tongji University Affiliated Ophthalmic Hospital (In Preparation) / Shanghai Eye Disease Prevention & Treatment Center / Shanghai Eye Hospital; Vice President of Shanghai General Hospital.', 'https://paper-submission-prod.oss-cn-shanghai.aliyuncs.com/speakers/avatars/2026-08-07/6ed673215abc412fa0f802251670ec36.jpg', 'EN');
