INSERT INTO `sys_email_template` VALUES (3, '论文审核', '<h3>尊敬的{{name1}}专家，您收到来自MCLC的论文投稿评审邀请</h3><p><a href=\"{{论文稿件}}\" rel=\"noopener noreferrer\" target=\"_blank\">查看论文稿件</a></p><p><a href=\"{{审批论文稿件}}\" rel=\"noopener noreferrer\" target=\"_blank\">审批论文稿件</a></p>', '专家审核模板', 1, 1, '', '2026-05-22 09:56:27', '2026-07-24 13:51:54', 0);
INSERT INTO `sys_email_template` VALUES (4, '论文审核通过模板', '<p>论文投稿审核通过通知！！！</p><p>尊敬的{{name1}}：</p><p>您的论文投稿《 {{name2}} 》已通过审核。</p><p>抵扣码：{{code}}</p><p>恭喜您！</p>', '论文审核通过模板', 1, 1, '', '2026-05-22 11:30:44', '2026-05-22 14:05:19', 0);
INSERT INTO `sys_email_template` VALUES (5, '论文审核未通过模板', '<p>论文投稿审核未通过通知 ！！！！</p><p>尊敬的{{name1}}：</p><p>您的论文投稿《 {{name2}} 》未通过审核。</p><p>感谢您的参与！！！</p>', '论文审核未通过模板', 1, 1, '', '2026-05-22 11:31:17', '2026-07-24 13:52:18', 0);
INSERT INTO `sys_email_template` VALUES (6, '注册通过模板', '<p>注册通过</p><p>尊敬的 {{name1}} , 您已成功注册！！！！</p>', '注册通过模板', 1, 1, '', '2026-05-22 14:22:34', '2026-05-22 14:22:34', 0);
